-- 0020_dream_seo_expansion.sql
-- Phase10-9(Dream SEO Content Expansion) — docs/DREAM_SEO_CONTENT_MAP.md의 keyword research 결과를
-- 실제 콘텐츠로 반영한다. 기존 25개 Parent(0010_seed_data.sql)와 101개 Situation
-- (0019_dream_situations_seed.sql)은 전혀 수정하지 않는다 — 순수 additive 확장이다.
--
-- 구성: A) 기존 25개 Parent 중 24개에 신규 Situation 추가(총 67개, 돼지꿈은 이미 품질
-- benchmark라 변경 없음) B) 신규 Parent 20개 + 각각의 dream_number_mappings + Situation(총 119개).
-- 신규 Parent의 interpretation은 "## 소제목" 경량 마크다운 규칙을 쓴다(app/dream/[keyword]/
-- page.tsx의 DreamHubContent.tsx가 파싱해 실제 <h2>로 렌더링 — 새 column을 추가하지 않고
-- 기존 interpretation TEXT 컬럼을 그대로 재사용, docs/DREAM_SEO_EXPANSION_REPORT.md §11 참조).
--
-- 반복 실행 안전성: dreams.keyword는 UNIQUE 제약이 없어(0003_dreams.sql) NOT EXISTS 가드로
-- 직접 중복을 막는다(0010과 동일한 이유). dream_situations는 (dream_id, keyword) UNIQUE가
-- 있어(0018) 기존 관례대로 ON CONFLICT DO NOTHING을 쓴다. dream_id는 항상 keyword로 조회한다
-- (하드코딩된 id에 의존하지 않음, 0019와 동일한 원칙).
--
-- 톤: 0019와 동일하게 "전통적으로 ~로 해석되곤 한다" 류의 완곡한 표현만 사용하고 확정적
-- 미래 예측/의료·재정 결정 유도 표현을 쓰지 않는다. numbers는 0~6개로 상황마다 의도적으로
-- 다르게 배정했다(전부 6개 채움 금지) — 실측 분포는 docs/DREAM_SEO_EXPANSION_REPORT.md 참조.

-- ============================================================
-- A. 기존 Parent 24개에 신규 Situation 추가 (돼지꿈 제외, 총 67개)
-- ============================================================

-- A-1. 뱀꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '뱀꿈'), '뱀을-잡는-꿈', '뱀을 잡는 꿈', '손으로 직접 뱀의 몸통이나 머리를 붙잡아 제압하는 장면이 나오는 꿈이다. 도망치는 뱀을 쫓아가 끝내 움켜쥐는 경우도 있고, 마당이나 방 안에서 갑자기 나타난 뱀을 순간적으로 낚아채는 경우도 있다. 뱀을 스스로 붙잡았다는 점에서, 가만히 기다리기보다 원하는 것을 직접 손에 넣으려는 태도와 연결해 해석되곤 한다. 전통적으로 뱀은 재물이나 기회를 상징하는 동물로 여겨져 온 만큼, 이를 붙잡는 행위는 눈앞의 기회를 놓치지 않고 붙드는 모습으로 풀이되는 경우가 많다. 뱀을 잡는 과정에서 힘이 들었는지, 의외로 수월했는지에 따라 지금 자신이 쏟고 있는 노력의 정도를 되짚어보는 계기로 삼기도 한다. 손아귀에 남은 뱀의 감촉이나 그때의 긴장감을 떠올려보면, 최근 마음속에서 붙잡고 싶었던 것이 무엇이었는지 자연스럽게 겹쳐볼 수 있다.', '스스로 나서서 기회를 붙잡는 모습을 상징하는 꿈', array[3,15,22,34], 7),
  ((select id from public.dreams where keyword = '뱀꿈'), '뱀에게-쫓기는-꿈', '뱀에게 쫓기는 꿈', '뱀 한 마리 혹은 여러 마리가 뒤에서 바짝 따라붙어 정신없이 도망치는 꿈이다. 골목을 돌고 돌아도 뱀이 계속 따라오거나, 다리가 무거워져 마음만큼 빨리 뛰지 못하는 답답함을 함께 느끼는 경우도 많다. 이런 꿈은 대체로 현실에서 아직 해결하지 못한 문제나 미뤄둔 걱정이 마음 한구석에 남아 있을 때 나타난다는 해석이 있다. 뱀에게 잡히지 않고 끝까지 도망쳤는지, 결국 붙잡혔는지에 따라 느껴지는 무게감도 달라진다. 쫓기는 상황 자체가 불편하게 느껴지더라도, 그 뱀이 무엇을 상징하는지 스스로 짚어보면 마음을 조급하게 만드는 원인을 찾는 데 도움이 된다는 이야기도 있다. 잠에서 깨고 나서도 두근거림이 남아 있다면, 잠시 숨을 고르고 지금 자신을 쫓는 것이 실제로 무엇인지 천천히 떠올려보는 것도 방법이다.', '마음속에 남은 불안과 조급함을 비추는 꿈', null, 8),
  ((select id from public.dreams where keyword = '뱀꿈'), '흰-뱀-꿈', '흰 뱀 꿈', '눈처럼 하얀 뱀이 스르르 몸을 움직이며 나타나는 꿈이다. 풀숲 사이에서 불쑥 모습을 드러내기도 하고, 집 안 어딘가에 똬리를 튼 채 가만히 있는 모습으로 등장하기도 한다. 흰빛을 띤 동물은 예로부터 신성하거나 특별한 존재로 여겨져, 흰 뱀이 나오는 꿈 또한 좋은 기운이 따르는 길몽으로 해석되곤 한다. 특히 색이 유난히 선명하고 뱀의 움직임이 차분했다면, 큰 동요 없이 순조롭게 풀려나가는 상황과 겹쳐 보는 시선도 있다. 흰 뱀을 무서워하지 않고 오히려 신비롭게 바라보았는지도 이 꿈을 되짚어볼 때 참고할 만한 부분이다. 꿈에서 느꼈던 그 고요하고 맑은 인상을 떠올리며, 요즘 자신에게 찾아온 좋은 변화나 기다려온 소식이 있는지 짚어보는 것도 좋다.', '맑고 좋은 기운이 따르는 길몽으로 여겨지는 꿈', array[7,19,28,33,41], 9),
  ((select id from public.dreams where keyword = '뱀꿈'), '검은-뱀-꿈', '검은 뱀 꿈', '짙고 어두운 색의 뱀이 조용히 움직이는 모습을 보는 꿈이다. 밝은 곳보다는 그늘지거나 어두운 공간에서 마주치는 경우가 많고, 뱀의 색이 유독 진하게 기억에 남는 것이 특징이다. 검은 뱀은 해석이 갈리는 편인데, 겉으로 드러나지 않은 힘이나 아직 드러나지 않은 재능을 상징한다는 이야기도 있고, 반대로 숨겨진 걱정거리를 암시한다는 풀이도 함께 전해진다. 그래서 이 꿈을 꾼 뒤에는 뱀을 보았을 때 느낀 감정이 두려움이었는지 묘한 이끌림이었는지를 떠올려보는 것이 도움이 된다는 시각도 있다. 뱀이 자신을 공격하지 않고 스쳐 지나갔다면 큰 무리 없이 지나갈 상황으로, 정면으로 마주쳤다면 한 번쯤 짚고 넘어가야 할 일로 풀이되기도 한다. 검은 뱀의 존재감이 꿈에서 유난히 컸다면, 최근 마음속에서 눌러두었던 생각이 있는지 가만히 되짚어보는 것도 의미가 있다.', '드러나지 않은 힘이나 걱정을 함께 담은 꿈', array[11,26,39], 10),
  ((select id from public.dreams where keyword = '뱀꿈'), '뱀이-변신하는-꿈', '뱀이 변신하는 꿈', '눈앞에 있던 뱀이 서서히 형체를 바꾸어 사람의 모습으로 변하는 꿈이다. 낯선 얼굴로 변하기도 하고, 때로는 익숙한 누군가의 모습으로 바뀌어 놀라는 경우도 있다. 동물이 사람으로 바뀌는 변신 자체가 예로부터 예사롭지 않은 장면으로 여겨져, 이런 꿈은 지금까지와는 다른 국면으로 상황이 바뀌는 조짐으로 해석되곤 한다. 뱀이 변한 사람이 반가운 인물이었는지 낯설고 불편한 인물이었는지에 따라 이 변화를 받아들이는 마음가짐도 달라질 수 있다는 이야기가 있다. 변신이 이루어지는 순간 느꼈던 놀라움이나 긴장감을 떠올려보면, 최근 자신의 주변에서 일어나고 있는 변화의 속도와 겹쳐볼 여지도 있다. 완전히 사람으로 변한 뒤 그 인물과 나눈 대화나 표정이 있었다면, 그 부분도 함께 기억해두면 이 꿈을 풀이하는 데 실마리가 될 수 있다.', '상황이 다른 국면으로 전환되는 조짐을 뜻하는 꿈', array[5,18,24,37], 11),
  ((select id from public.dreams where keyword = '뱀꿈'), '뱀알을-보는-꿈', '뱀알을 보는 꿈', '여러 개의 뱀알이 한데 모여 있는 모습을 발견하는 꿈이다. 땅속이나 풀숲, 혹은 낯선 장소의 틈에서 무더기로 알을 발견하는 경우가 흔하고, 알의 개수가 유난히 많았다는 인상이 남기도 한다. 알은 아직 세상에 드러나지 않은 가능성을 담고 있는 상징이어서, 뱀알을 보는 꿈 역시 앞으로 자라날 일이나 서서히 무르익어가는 계획과 연결지어 해석되는 경우가 많다. 알을 깨뜨리지 않고 조심스럽게 바라보기만 했다면 아직은 지켜보며 때를 기다려야 할 시기로, 알을 직접 만지거나 옮겼다면 계획에 좀 더 적극적으로 관여하게 될 상황으로 풀이하는 시각도 있다. 알에서 부화하는 장면까지 이어졌는지도 이 꿈의 인상을 좌우하는 부분이다. 눈에 담았던 알의 색이나 크기, 그리고 그것을 보았을 때의 기대감을 함께 떠올려보면 이 꿈이 자신에게 건네는 의미를 조금 더 구체적으로 그려볼 수 있다.', '서서히 무르익어가는 가능성을 뜻하는 꿈', array[9,16,27,32,44], 12)
on conflict (dream_id, keyword) do nothing;

-- A-2. 이빨 빠지는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '이빨 빠지는 꿈'), '윗니가-빠지는-꿈', '윗니가 빠지는 꿈', '위쪽 앞니나 어금니가 툭 하고 빠져 손바닥 위에 떨어지는 꿈이다. 거울을 보다가 빈자리를 발견하고 당황하는 경우도 있고, 말을 하던 도중 갑자기 이가 빠지는 느낌에 놀라 잠에서 깨는 경우도 있다. 예로부터 윗니는 부모나 손윗사람, 자신보다 나이가 많은 주변 사람을 가리킨다는 이야기가 전해져, 윗니가 빠지는 꿈은 그런 손윗사람과 관련된 소식이나 변화로 풀이되곤 한다. 이가 빠질 때 아팠는지, 아니면 별다른 통증 없이 빠졌는지도 이 꿈을 돌아볼 때 함께 떠올려볼 부분이다. 빠진 이가 깨끗한 모양이었는지 부서진 채였는지에 따라 그 소식을 받아들이는 마음의 무게도 다르게 느껴진다는 해석도 있다. 꿈에서 느낀 당혹감이 컸다면, 요즘 가족이나 웃어른과의 관계에서 마음 쓰이는 일이 없었는지 가볍게 짚어보는 것도 좋다.', '손윗사람과 관련된 변화나 소식을 뜻하는 꿈', null, 5),
  ((select id from public.dreams where keyword = '이빨 빠지는 꿈'), '아랫니가-빠지는-꿈', '아랫니가 빠지는 꿈', '아래쪽 이가 흔들리다가 결국 빠져버리는 꿈이다. 혀로 빈자리를 더듬어보며 허전함을 느끼는 장면이 유독 생생하게 기억에 남는 경우가 많다. 아랫니는 흔히 자녀나 손아랫사람, 자신이 챙기고 돌보는 대상을 가리킨다고 전해져, 이 꿈은 그런 가까운 사람과 얽힌 걱정이나 변화로 해석되는 경우가 많다. 이가 빠지는 순간 피가 났는지, 아니면 깔끔하게 빠졌는지도 꿈의 인상을 다르게 만드는 요소로 꼽힌다. 빠진 이를 손에 쥐고 어찌할 바를 몰라 했다면, 그만큼 마음이 쓰이는 대상이 가까이 있다는 뜻으로 풀이되기도 한다. 잠에서 깬 뒤에도 허전한 느낌이 남아 있다면, 요즘 신경 쓰이는 손아랫사람이나 챙겨야 할 일이 있는지 한 번쯤 떠올려보는 것도 괜찮다.', '손아랫사람을 향한 걱정을 담은 꿈', null, 6),
  ((select id from public.dreams where keyword = '이빨 빠지는 꿈'), '이가-빠지며-피가-나는-꿈', '이가 빠지며 피가 나는 꿈', '이가 빠지는 순간 입안 가득 피맛이 느껴지는 꿈이다. 손으로 입을 틀어막아도 피가 멈추지 않거나, 뱉어낸 이와 함께 붉은 피가 손바닥에 흥건히 묻어나는 장면이 인상 깊게 남는 경우가 많다. 단순히 이가 빠지는 꿈보다 피가 함께 등장하는 경우, 오히려 재물이나 결실과 연결지어 해석하는 오래된 풀이도 전해진다. 피를 보고 놀라기보다 담담하게 받아들였다면 눈앞의 변화를 무리 없이 받아들이는 상황으로, 크게 놀라 허둥댔다면 아직 마음의 준비가 덜 된 상태로 풀이되기도 한다. 피의 양이 많았는지 적었는지, 그리고 그것을 보며 느낀 감정이 두려움이었는지 홀가분함이었는지도 함께 떠올려볼 만하다. 강렬했던 그 장면의 기억을 되짚으며, 최근 자신에게 다가온 변화의 크기를 가늠해보는 것도 이 꿈을 이해하는 한 방법이다.', '변화 뒤에 따라오는 결실을 암시하는 꿈', array[4,13,29,36], 7),
  ((select id from public.dreams where keyword = '이빨 빠지는 꿈'), '이가-빠졌는데-안-아픈-꿈', '이가 빠졌는데 안 아픈 꿈', '이가 후두둑 빠지는데도 이상하리만치 통증이 전혀 느껴지지 않는 꿈이다. 손바닥 위에 떨어진 이를 보고도 담담하게 상황을 받아들이거나, 오히려 개운한 기분이 드는 경우도 있다. 보통 이 빠지는 꿈이 불안이나 걱정과 함께 떠오르는 것과 달리, 아프지 않았다는 점은 그 변화가 생각보다 순조롭게 지나갈 조짐으로 풀이되는 경우가 많다. 빠진 이의 자리를 혀로 확인해보면서도 크게 동요하지 않았다면, 지금 겪고 있거나 앞으로 겪을 변화에 대해 이미 마음의 준비가 되어 있다는 뜻으로 보기도 한다. 통증 없이 이가 빠지는 감각이 오히려 시원했다면, 묵혀두었던 걱정 하나를 자연스럽게 내려놓는 과정과 겹쳐볼 수 있다는 해석도 있다. 꿈에서 느낀 그 담담함을 떠올리며, 요즘 자신이 예상보다 수월하게 넘기고 있는 일이 있는지 짚어보는 것도 좋다.', '생각보다 순조롭게 지나가는 변화를 뜻하는 꿈', array[2,17,25,31], 8),
  ((select id from public.dreams where keyword = '이빨 빠지는 꿈'), '빠진-이를-다시-줍는-꿈', '빠진 이를 다시 줍는 꿈', '바닥에 떨어진 이를 몸을 숙여 다시 주워 담는 꿈이다. 손바닥 위에 조심스레 올려놓고 살펴보거나, 잃어버릴세라 주머니 깊숙이 넣어두는 장면으로 이어지기도 한다. 한 번 빠져나간 것을 스스로 다시 챙겨 든다는 점에서, 이 꿈은 놓쳤다고 생각했던 기회나 관계를 다시 붙잡는 상황과 연결해 해석되는 경우가 많다. 주운 이를 원래 자리에 다시 끼워 넣으려 했는지, 아니면 그냥 손에 쥐고만 있었는지에 따라 그 회복의 정도를 다르게 짚어볼 수 있다는 이야기도 있다. 이를 줍는 과정에서 서두르지 않고 차분했다면, 지금 자신이 무언가를 되찾기 위해 들이는 노력도 조급하지 않게 흘러가고 있다는 뜻으로 풀이되기도 한다. 손에 쥔 이의 감촉과 그때 느꼈던 안도감을 떠올려보면, 최근 다시 되돌리고 싶은 일이 무엇이었는지 자연스럽게 겹쳐볼 수 있다.', '놓쳤던 것을 다시 붙잡는 회복을 뜻하는 꿈', array[6,14,23,30,42], 9)
on conflict (dream_id, keyword) do nothing;

-- A-3. 똥꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '똥꿈'), '옷에-똥을-묻히는-꿈', '옷에 똥을 묻히는 꿈', '조심한다고 했는데도 옷자락이나 소매에 똥이 묻어버리는 꿈이다. 급하게 닦아내려 해도 자국이 쉽게 지워지지 않거나, 냄새 때문에 곤란해하는 장면으로 이어지기도 한다. 몸에 직접 묻는 것보다는 다소 완곡하게, 겉으로 드러나는 부분에 재물의 기운이 스치듯 닿는 모습으로 풀이되는 경우가 많다. 옷을 갈아입고 나서 개운함을 느꼈는지, 아니면 계속 신경이 쓰였는지에 따라 이 꿈이 남기는 인상도 달라진다. 묻은 자리가 눈에 잘 띄는 곳이었다면 주변 사람들 눈에 띌 만한 작은 행운으로, 잘 보이지 않는 자리였다면 조용히 챙기게 되는 소소한 이득으로 풀이하는 시각도 있다. 옷에 남은 자국을 지우려 애썼던 그 순간을 떠올리며, 요즘 신경 쓰고 있는 겉모습이나 평판이 있는지 가볍게 짚어보는 것도 좋다.', '겉으로 스치듯 닿는 작은 행운을 뜻하는 꿈', array[8,20,35], 6),
  ((select id from public.dreams where keyword = '똥꿈'), '남이-똥을-누는-것을-보는-꿈', '남이 똥을 누는 것을 보는 꿈', '다른 사람이 똥을 누는 모습을 곁에서 지켜보게 되는 꿈이다. 아는 사람일 때도 있고, 얼굴이 흐릿한 낯선 사람일 때도 있는데, 어느 쪽이든 자신이 직접 겪는 일이 아니라 지켜보는 입장이라는 점이 이 꿈의 특징으로 꼽힌다. 전통적으로 이런 꿈은 자신이 아닌 주변 사람에게 좋은 일이 생기거나, 가까운 이의 형편이 풀리는 모습을 미리 보는 것과 같다고 해석되곤 한다. 그 모습을 보며 부러움을 느꼈는지, 아니면 함께 기뻐해 주는 마음이었는지도 이 꿈을 돌아볼 때 참고할 만한 부분이다. 지켜본 사람이 누구였는지 구체적으로 떠오른다면, 최근 그 사람에게 좋은 소식이 있었는지 자연스럽게 겹쳐보는 것도 방법이다. 남의 일이었다고 해서 무심히 넘기기보다는, 주변 사람들의 상황에 한 번 더 관심을 기울여보는 계기로 삼는 경우도 있다.', '가까운 사람에게 찾아올 좋은 소식을 뜻하는 꿈', array[10,21,38], 7),
  ((select id from public.dreams where keyword = '똥꿈'), '똥이-금으로-변하는-꿈', '똥이 금으로 변하는 꿈', '눈앞에 있던 똥이 서서히 반짝이는 금덩이로 바뀌는 꿈이다. 처음에는 더럽다고 여겨 피하려다가, 색이 변하는 것을 보고 놀라서 다시 다가가는 장면으로 이어지기도 한다. 이미 재물의 상징으로 여겨지는 똥이 눈에 보이는 형태로 금까지 되었다는 점에서, 이런 꿈은 뚜렷하게 좋은 결과를 암시하는 길몽 중에서도 강한 축에 속한다고 풀이되곤 한다. 변한 금을 직접 손에 쥐었는지, 아니면 바라보기만 했는지에 따라 그 결실을 자신이 얼마나 실감 나게 받아들일지가 달라진다는 해석도 있다. 금으로 변하는 과정이 순식간이었는지 서서히 이루어졌는지도 함께 떠올려보면, 지금 진행 중인 일이 언제쯤 결실을 볼지 가늠해보는 데 참고가 될 수 있다. 꿈에서 느꼈던 그 벅찬 놀라움을 기억해두고, 요즘 공들이고 있는 일이 있다면 그 결과를 기대하는 마음으로 지켜보는 것도 좋다.', '뚜렷한 결실을 암시하는 강한 길몽으로 여겨진다', array[1,12,26,33,40,45], 8),
  ((select id from public.dreams where keyword = '똥꿈'), '화장실이-막혀서-못-치우는-꿈', '화장실이 막혀서 못 치우는 꿈', '화장실 변기가 막혀 아무리 애써도 처리가 되지 않는 꿈이다. 물을 내려도 그대로이거나, 오히려 넘칠 듯 차오르는 모습에 발을 동동 구르는 경우도 많다. 손을 써봐도 도구를 써봐도 좀처럼 뚫리지 않는 답답함이 이 꿈의 중심을 이루는데, 이는 현실에서 풀리지 않고 정체된 일이나 마음처럼 되지 않는 상황을 반영한다는 해석이 있다. 결국 포기하고 돌아섰는지, 아니면 끝까지 매달려 조금이라도 뚫었는지에 따라 이 답답함이 이어질 정도도 다르게 느껴볼 수 있다. 막힌 것을 처리하지 못한 채로 잠에서 깼다면, 요즘 뜻대로 풀리지 않는 일이 무엇인지 한 번쯤 짚어보는 계기로 삼아볼 만하다. 답답한 감정이 꿈에서 유독 크게 남았더라도, 지금 막혀 있는 부분을 서두르지 않고 차근차근 풀어가면 된다는 마음으로 받아들이는 경우도 있다.', '현실에서 정체된 답답함을 비추는 꿈', null, 9)
on conflict (dream_id, keyword) do nothing;

-- A-4. 개꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '개꿈'), '개를-잃어버리는-꿈', '개를 잃어버리는 꿈', '함께 있던 개가 어느 순간 눈앞에서 사라져 여기저기 찾아 헤매는 꿈이다. 목줄이 풀린 채 골목 사이로 달아나 버리거나, 사람 많은 곳에서 놓쳐버려 애타게 이름을 부르는 장면으로 이어지기도 한다. 개는 흔히 곁을 지켜주는 존재나 믿을 만한 인연을 상징한다고 여겨지는 만큼, 이를 잃어버리는 꿈은 가까운 인연이나 의지하던 대상과 멀어질까 걱정하는 마음과 연결지어 해석되는 경우가 많다. 개를 끝내 찾아냈는지, 아니면 찾지 못한 채로 꿈이 끝났는지에 따라 이 불안이 계속 이어질지 여부를 다르게 짚어보기도 한다. 개를 잃어버렸을 때 느낀 감정이 단순한 당황함이었는지, 아니면 마음이 무너질 듯한 상실감이었는지도 함께 떠올려볼 만하다. 잠에서 깬 뒤 허전함이 남는다면, 최근 소원해진 사람이나 관계가 없는지 가볍게 돌아보는 것도 도움이 된다.', '가까운 인연에 대한 걱정을 담은 꿈', null, 5),
  ((select id from public.dreams where keyword = '개꿈'), '개가-죽는-꿈', '개가 죽는 꿈', '곁에 있던 개가 힘없이 쓰러져 숨을 거두는 모습을 지켜보는 꿈이다. 오랫동안 함께한 개일 때도 있고, 꿈속에서만 등장한 낯선 개일 때도 있는데, 어느 쪽이든 그 순간의 먹먹함이 꿈에서 깨어난 뒤에도 오래 남는 경우가 많다. 동물이 죽는 꿈은 흔히 걱정거리나 묵은 문제가 끝을 맺는 모습으로 풀이되기도 하지만, 동시에 소중히 여기던 것과의 이별을 암시한다는 해석도 함께 전해진다. 개의 죽음을 슬퍼하며 눈물을 흘렸는지, 아니면 담담하게 지켜보았는지에 따라 이 꿈을 받아들이는 마음의 무게도 달라질 수 있다. 죽은 개를 정성껏 묻어주거나 배웅하는 장면까지 이어졌다면, 어떤 일을 매듭짓고 다음으로 넘어가려는 마음과 겹쳐 보는 시각도 있다. 꿈에서 느낀 상실감이 컸다면, 요즘 마음속에서 정리하고 싶은 일이나 관계가 있는지 천천히 떠올려보는 것도 좋다.', '묵은 걱정이나 인연이 매듭지어짐을 뜻하는 꿈', null, 6),
  ((select id from public.dreams where keyword = '개꿈'), '하얀-개-꿈', '하얀 개 꿈', '새하얀 털을 가진 개가 꼬리를 흔들며 다가오는 꿈이다. 처음 보는 개인데도 낯설지 않게 느껴지거나, 스스럼없이 곁으로 다가와 몸을 기대는 모습으로 나타나기도 한다. 흰색 동물은 예로부터 맑고 길한 기운을 지닌 존재로 여겨져, 하얀 개가 나오는 꿈 역시 반가운 소식이나 순조로운 흐름을 알리는 길몽으로 해석되곤 한다. 개가 유독 온순하고 친근하게 굴었다면, 그만큼 다가올 일도 무리 없이 순탄하게 풀릴 것이라는 해석도 있다. 하얀 개를 쓰다듬거나 함께 걸었던 감촉과 분위기를 떠올려보면, 지금 자신에게 다가오고 있는 좋은 기운을 좀 더 구체적으로 그려볼 수 있다. 꿈에서 느꼈던 따뜻함을 기억해두고, 요즘 기다리고 있는 소식이 있다면 한결 가벼운 마음으로 지켜보는 것도 좋다.', '반가운 소식과 순조로운 흐름을 뜻하는 길몽', array[3,15,24,29,41], 7),
  ((select id from public.dreams where keyword = '개꿈'), '검은-개-꿈', '검은 개 꿈', '짙은 검은 털을 가진 개와 마주치는 꿈이다. 어두운 골목이나 인적이 드문 곳에서 불쑥 나타나는 경우가 많고, 개의 눈빛이나 몸짓이 유난히 또렷하게 기억에 남기도 한다. 검은 개는 든든하게 곁을 지켜주는 수호자 같은 존재로 풀이되기도 하고, 반대로 은근한 불안이나 경계해야 할 대상을 암시한다는 해석도 함께 전해진다. 개가 짖지 않고 조용히 곁을 지켰다면 믿음직한 인연이 가까이 있다는 뜻으로, 낯설게 굴며 거리를 두었다면 아직은 마음을 다 열지 못한 관계로 풀이해보는 시각도 있다. 검은 개를 마주쳤을 때 느낀 감정이 든든함이었는지 경계심이었는지도 이 꿈을 돌아볼 때 함께 떠올려볼 부분이다. 개의 존재감이 꿈에서 유난히 크게 남았다면, 요즘 자신을 지지해주는 사람이 누구인지 한 번쯤 짚어보는 것도 좋다.', '든든한 수호자 혹은 은근한 경계심을 뜻하는 꿈', array[7,19,36], 8),
  ((select id from public.dreams where keyword = '개꿈'), '개와-노는-꿈', '개와 노는 꿈', '강아지나 개와 함께 마당이나 공원을 뛰어다니며 노는 꿈이다. 공을 던지고 물어오는 놀이를 반복하거나, 서로 몸을 부대끼며 장난치는 장면이 유독 즐겁게 기억되는 경우가 많다. 개와 스스럼없이 어울려 노는 모습은 편안한 인간관계나 마음이 잘 맞는 인연을 상징한다고 풀이되는 경우가 많다. 놀이가 끝날 때까지 지치지 않고 웃으며 즐거웠다면, 지금 맺고 있는 관계 역시 큰 갈등 없이 순탄하게 이어지고 있다는 뜻으로 보기도 한다. 함께 논 개가 유독 활기차고 애교가 많았다면, 그만큼 주변에서 받는 애정이나 지지도 크다는 해석도 있다. 꿈에서 느꼈던 그 즐거움과 편안함을 떠올려보면, 요즘 자신을 웃게 만드는 사람이나 순간이 무엇인지 자연스럽게 겹쳐볼 수 있다.', '편안하고 즐거운 인연을 상징하는 꿈', array[5,14,22,31,40], 9)
on conflict (dream_id, keyword) do nothing;

-- A-5. 용꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '용꿈'), '용이-되는-꿈', '용이 되는 꿈', '꿈속에서 스스로가 점점 용의 형상으로 바뀌어가는 체험을 하는 경우다. 몸이 커지고 비늘이 돋아나며 하늘로 오를 힘이 생기는 감각은, 자신의 처지나 위상이 이전과는 다른 단계로 넘어가는 변화의 상징으로 해석되곤 한다. 다른 존재가 되어보는 꿈은 대개 지금까지와는 다른 역할이나 책임을 떠안게 되는 시기와 맞물려 나타난다고 여겨지기도 한다. 특히 변신 과정에서 고통이나 두려움 없이 자연스럽게 이루어졌다면, 스스로 준비가 되어 있는 상태에서 맞이하는 전환으로 풀이되는 경우가 많다. 반대로 변신이 버겁거나 완전히 끝나지 않은 채 꿈이 끝났다면, 아직 새로운 역할에 온전히 적응하지 못한 심리 상태를 반영한다는 해석도 있다. 이 꿈을 꾼 사람 중에는 실제로 승진, 독립, 새로운 도전을 앞두고 있는 경우가 많다는 이야기도 전해진다. 자신이 용이 되어 무엇을 가장 먼저 하고 싶었는지 떠올려보면, 지금 마음속에 있는 목표를 더 선명하게 확인할 수 있다.', '자신의 위상이 달라지는 전환기를 상징하는 꿈으로 여겨진다', array[3,14,22,29,37,41], 6),
  ((select id from public.dreams where keyword = '용꿈'), '여러-마리-용이-나오는-꿈', '여러 마리 용이 나오는 꿈', '한 마리가 아니라 여러 마리의 용이 한꺼번에 나타나는 꿈이다. 하늘을 가득 채우듯 여러 용이 동시에 날아오르는 장면은, 좋은 일이 한 번에 몰려오거나 여러 방면에서 기회가 겹쳐 나타나는 시기와 연결지어 해석되곤 한다. 다만 용이 여러 마리라는 점에서, 하나의 기회에 집중하기보다 여러 갈래의 선택지 앞에서 고민하게 되는 상황을 암시한다는 풀이도 있다. 용들이 서로 뒤엉키지 않고 각자 질서 있게 움직였다면 여러 일을 무리 없이 병행할 수 있는 여력이 있다는 의미로 여겨지기도 하고, 반대로 어지럽게 뒤섞여 있었다면 우선순위를 정리해야 할 필요성을 보여준다는 해석도 있다. 몇 마리의 용이 등장했는지, 그중 유독 눈에 띄는 용이 있었는지를 기억해두면 이 꿈을 되짚어볼 때 도움이 된다. 예로부터 용이 무리를 이루어 나타나는 모습은 주변 사람들과 함께 이루는 성과나 협업의 기운으로 풀이되는 경우도 많았다.', '여러 기회가 동시에 겹쳐 찾아오는 상황을 상징하는 꿈', array[5,12,19,26,33], 7),
  ((select id from public.dreams where keyword = '용꿈'), '용이-싸우는-꿈', '용이 싸우는 꿈', '두 마리 이상의 용이 하늘이나 물속에서 격렬하게 맞붙어 싸우는 꿈이다. 거대한 존재끼리 힘을 겨루는 장면은 예로부터 자신을 둘러싼 환경에서 큰 힘들이 부딪히는 갈등이나 경쟁 상황을 반영한다고 해석되곤 한다. 꿈속에서 자신이 그 싸움을 지켜보는 입장이었다면, 스스로 어찌할 수 없는 큰 변화나 다툼의 소용돌이 한가운데 서 있다는 심리를 나타낸다는 풀이도 있다. 반면 용들의 싸움에 직접 휘말리거나 몸을 다치는 느낌이 들었다면, 현실에서도 갈등의 여파가 자신에게 직접 미칠 수 있다는 경계의 의미로 여겨지기도 한다. 어느 쪽 용이 더 우세했는지, 결국 승부가 어떻게 끝났는지를 함께 떠올려보면 지금 자신이 느끼는 힘의 균형과 견주어볼 수 있다. 다만 이 꿈은 다툼 자체보다 그 뒤에 오는 변화에 더 무게를 두고 해석되는 경우가 많다는 점도 참고할 만하다.', '큰 힘들이 부딪히는 갈등 국면을 상징하는 꿈으로 풀이된다', null, 8)
on conflict (dream_id, keyword) do nothing;

-- A-6. 호랑이꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '호랑이꿈'), '새끼-호랑이를-보는-꿈', '새끼 호랑이를 보는 꿈', '다 자란 호랑이가 아니라 작고 어린 새끼 호랑이를 마주하는 꿈이다. 아직 힘을 다 갖추지 못했지만 호랑이 특유의 기운을 품고 있는 새끼의 모습은, 이제 막 시작 단계에 있는 일이나 앞으로 크게 성장할 가능성을 지닌 무언가를 상징한다고 해석되곤 한다. 새끼 호랑이를 품에 안거나 가까이서 쓰다듬었다면, 작은 계획이나 관계를 조심스럽게 키워나가고 있는 자신의 모습과 겹쳐 볼 수 있다는 풀이도 있다. 임신이나 출산을 앞둔 사람이 이런 꿈을 꾸는 경우 태몽으로 여겨지기도 하며, 그렇지 않더라도 새로운 시작을 향한 기대감을 반영한다는 이야기가 전해진다. 새끼 호랑이가 유독 건강하고 활기차 보였다면 그만큼 순조로운 출발을 예고한다는 해석이 따르고, 반대로 약하거나 위태로워 보였다면 아직은 세심한 보살핌이 필요한 시기임을 암시한다고도 본다. 어떤 상황에서 새끼 호랑이를 만났는지 함께 떠올려보면 이 꿈이 가리키는 대상을 조금 더 구체적으로 짚어볼 수 있다.', '작지만 크게 자랄 가능성을 상징하는 꿈으로 풀이된다', array[2,11,18,25,34], 5),
  ((select id from public.dreams where keyword = '호랑이꿈'), '호랑이가-집에-들어오는-꿈', '호랑이가 집에 들어오는 꿈', '호랑이가 대문이나 마당을 지나 집 안까지 성큼 들어오는 꿈이다. 산속 깊은 곳에 있어야 할 존재가 스스로 자신의 공간까지 찾아왔다는 점에서, 강한 기운이나 귀한 인연이 자신의 삶 안으로 직접 들어오는 상황과 연결해 해석되곤 한다. 호랑이가 들어와 집 안을 편히 돌아다니거나 자리를 잡고 앉았다면, 그 기운이 오래도록 곁에 머무를 것이라는 의미로 여겨지기도 한다. 예로부터 이런 꿈은 집안에 든든한 지원군이 생기거나 가족 중 누군가에게 좋은 소식이 있을 조짐으로 풀이되는 경우가 많았다. 다만 호랑이가 들어오는 순간 놀라거나 두려움을 느꼈다면, 그 변화가 크고 갑작스럽게 다가올 수 있다는 뜻으로 해석하기도 한다. 문이나 창문 어느 쪽으로 들어왔는지, 집 안 어느 공간으로 향했는지를 기억해두면 이 꿈의 의미를 더 세밀하게 짚어볼 수 있다는 이야기도 있다.', '든든한 기운이 삶 안으로 들어오는 것을 상징하는 꿈', array[7,15,23,30,38,44], 6),
  ((select id from public.dreams where keyword = '호랑이꿈'), '호랑이에게-물리는-꿈', '호랑이에게 물리는 꿈', '호랑이가 팔이나 다리 등 몸의 일부를 무는 꿈이다. 물리는 순간의 통증이나 놀람이 꿈에서도 생생하게 느껴지는 경우가 많아, 잠에서 깬 뒤에도 강렬한 인상으로 남는 꿈으로 꼽힌다. 강한 존재에게 몸이 닿았다는 점에서, 원치 않는 방식으로라도 강한 기운이나 영향력이 자신에게 전해지는 상황을 암시한다는 해석이 전해진다. 물린 부위가 어디였는지에 따라 의미를 다르게 보기도 하는데, 손이나 팔을 물렸다면 일이나 성과와 관련된 자극으로, 다리를 물렸다면 이동이나 결정과 관련된 변화로 풀이되곤 한다. 물린 뒤에도 크게 다치지 않고 그 자리를 벗어났다면 강한 자극을 견뎌내고 오히려 얻는 것이 있는 상황으로 보는 시각도 있다. 반대로 상처가 깊고 아팠다면, 최근 겪고 있는 부담이나 스트레스가 꿈에 그대로 투영된 것일 수 있다는 이야기도 있다. 이 꿈을 꾼 뒤에는 최근 자신에게 강하게 다가온 사람이나 사건이 있었는지 돌아보는 것도 도움이 될 수 있다.', '강하고 원치 않는 자극이 전해지는 것을 상징하는 꿈', array[16,41], 7)
on conflict (dream_id, keyword) do nothing;

-- A-7. 물고기 잡는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '물고기 잡는 꿈'), '물고기가-도망가는-꿈', '물고기가 도망가는 꿈', '낚싯대를 드리우거나 손을 뻗기도 전에 물고기가 먼저 알아채고 재빠르게 달아나 버리는 꿈이다. 붙잡았다가 놓치는 것과 달리, 애초에 다가가기도 전에 기회가 저만치 멀어지는 장면이라는 점에서 조금 다른 결의 아쉬움을 담고 있다고 해석되곤 한다. 물고기가 도망가는 방향이나 속도가 유난히 빠르게 느껴졌다면, 지금 준비가 다소 늦어져 흐름을 놓치고 있는 상황을 반영한다는 풀이도 있다. 여러 마리 중 한두 마리만 도망갔는지, 아니면 전부 흩어져 버렸는지에 따라서도 아쉬움의 크기를 가늠해볼 수 있다는 이야기가 있다. 물속이 유난히 탁하거나 시야가 흐렸다면, 상황을 제대로 파악하지 못한 채 기회를 흘려보내고 있다는 의미로 보기도 한다. 이 꿈을 꾼 뒤에는 눈앞의 일에 좀 더 빠르게 반응해보는 것을 계기로 삼는 경우도 있다.', '준비가 늦어져 기회가 멀어지는 상황을 상징하는 꿈', null, 5),
  ((select id from public.dreams where keyword = '물고기 잡는 꿈'), '죽은-물고기를-보는-꿈', '죽은 물고기를 보는 꿈', '물 위에 떠 있거나 바닥에 가라앉은 죽은 물고기를 목격하는 꿈이다. 살아 움직이던 생명이 멈춰 있는 모습을 보는 만큼, 진행하던 일이나 관계가 하나의 매듭을 짓거나 더 이상 이전과 같은 활력을 갖지 못하는 상황을 나타낸다는 해석이 따른다. 다만 이런 꿈이 무조건 나쁜 신호로만 읽히는 것은 아니어서, 하나의 국면이 끝나야 다음 국면으로 넘어갈 수 있다는 자연스러운 순환의 의미로 풀이되기도 한다. 죽은 물고기를 보고 놀라거나 불쾌감을 느꼈다면 마무리 짓는 과정에서 아직 마음의 정리가 덜 된 상태를 반영한다는 이야기도 있고, 담담하게 지켜보았다면 이미 스스로 그 끝을 받아들이고 있다는 신호로 보기도 한다. 물고기의 수가 한 마리였는지 여러 마리였는지, 물이 맑았는지 탁했는지도 함께 떠올려보면 좀 더 구체적인 해석에 참고가 될 수 있다. 예로부터 이런 장면은 지나간 일에 미련을 두기보다 새로운 시작을 준비하라는 뜻으로 전해지기도 한다.', '하나의 국면이 마무리되는 상황을 상징하는 꿈', null, 6)
on conflict (dream_id, keyword) do nothing;

-- A-8. 까치꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '까치꿈'), '까치가-창문을-두드리는-꿈', '까치가 창문을 두드리는 꿈', '까치 한 마리가 창가에 앉아 부리로 톡톡 유리를 두드리는 꿈이다. 예로부터 까치는 반가운 소식을 전하는 새로 여겨져 왔는데, 그 까치가 직접 창문까지 다가와 신호를 보내는 모습은 곧 어떤 소식이나 연락이 도착할 조짐으로 해석되곤 한다. 특히 문이 아니라 창문을 두드렸다는 점에서, 예상하지 못한 경로나 뜻밖의 사람을 통해 소식이 전해질 수 있다는 풀이도 전해진다. 창문을 열어 까치를 맞아들였다면 그 소식을 반갑게 받아들일 준비가 되어 있다는 의미로, 반대로 창문을 열지 못하고 머뭇거렸다면 마음의 준비가 조금 더 필요한 상태로 여겨지기도 한다. 까치가 두드리는 소리가 유난히 크고 또렷하게 들렸다면 그만큼 중요한 소식일 가능성이 크다는 이야기도 있다. 아침에 이런 꿈을 꾸고 일어났다면 그날 하루 연락이 오는 곳들을 조금 더 눈여겨보게 되는 계기가 되기도 한다.', '뜻밖의 경로로 소식이 전해지는 것을 상징하는 꿈', array[4,13,21,28,35], 4),
  ((select id from public.dreams where keyword = '까치꿈'), '여러-마리-까치를-보는-꿈', '여러 마리 까치를 보는 꿈', '한두 마리가 아니라 여러 마리의 까치가 한곳에 모여 있거나 무리 지어 날아다니는 꿈이다. 좋은 소식을 전한다고 알려진 까치가 여러 마리 동시에 나타난다는 점에서, 여러 곳으로부터 반가운 연락이나 성과가 잇따라 들려오는 시기와 연결해 해석되곤 한다. 까치들이 나뭇가지 위에 나란히 앉아 있었다면 소식들이 차례로 정돈되어 도착할 것이라는 의미로 보기도 하고, 어지럽게 흩어져 날아다녔다면 여러 소식이 한꺼번에 몰려와 정신이 없을 수 있다는 풀이도 있다. 까치의 수를 세어보려 했던 기억이 있다면, 그 숫자가 이 시기에 챙겨야 할 일의 가짓수와 겹쳐 보인다는 이야기도 전해진다. 까치 울음소리까지 함께 들렸는지도 떠올려보면 좋은데, 소리가 클수록 소식의 비중도 크다고 여기는 경우가 많다. 여러 마리의 까치를 본 꿈은 대체로 한 가지보다는 여러 갈래의 좋은 흐름이 겹쳐 있는 시기를 상징하는 꿈으로 보기도 한다.', '여러 곳에서 좋은 소식이 겹쳐 오는 것을 상징하는 꿈', array[1,10,17,24,32,40], 5)
on conflict (dream_id, keyword) do nothing;

-- A-9. 거북이꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '거북이꿈'), '거북이가-알을-낳는-꿈', '거북이가 알을 낳는 꿈', '거북이가 모래사장이나 땅에 구덩이를 파고 알을 낳는 모습을 지켜보는 꿈이다. 오랜 세월을 상징하는 거북이가 새 생명을 세상에 내놓는 장면이라는 점에서, 오랫동안 준비해 온 일이 마침내 결실을 맺거나 새로운 시작으로 이어지는 상황을 나타낸다고 해석되곤 한다. 알의 개수가 많았다면 그만큼 여러 갈래로 뻗어나갈 성과나 가능성을 의미한다는 풀이가 있고, 알이 몇 개 되지 않았더라도 그 안에 담긴 가능성의 크기에 더 무게를 두어 해석하기도 한다. 거북이가 알을 낳는 과정을 끝까지 지켜보았다면, 지금 진행 중인 일의 결과를 직접 확인하고 싶어하는 마음이 반영된 것으로 보기도 한다. 태몽으로 이런 꿈을 꾸는 경우도 전해지는데, 거북이 특유의 장수와 안정의 이미지가 더해져 오래도록 편안한 삶을 살 아이라는 의미로 풀이되기도 한다. 알을 낳은 자리를 다시 흙으로 덮는 장면까지 보았다면, 결실을 소중히 지켜나가려는 마음가짐과 맞닿아 있다는 이야기도 있다.', '오랜 준비가 결실로 이어지는 것을 상징하는 꿈', array[6,14,19,27,36,43], 4),
  ((select id from public.dreams where keyword = '거북이꿈'), '큰-거북이를-보는-꿈', '큰 거북이를 보는 꿈', '몸집이 유난히 크고 등딱지가 단단해 보이는 거북이를 마주하는 꿈이다. 거북이는 원래도 장수와 안정을 상징하는 동물로 여겨지는데, 그 크기가 남다르게 컸다는 점에서 그만큼 크고 든든한 행운이나 안정적인 기반을 의미한다는 해석이 전해진다. 거북이가 유유히 움직이며 위압감을 주지 않았다면, 서두르지 않아도 자연스럽게 다가오는 좋은 흐름을 뜻한다는 풀이도 있다. 큰 거북이의 등에 올라타거나 등딱지를 만져보았다면, 그 안정감을 직접 자신의 것으로 받아들이게 되는 상황과 연결지어 보기도 한다. 거북이를 어디에서 만났는지도 의미를 더하는데, 바다나 강처럼 넓은 곳에서 보았다면 더 크고 장기적인 흐름으로, 좁은 공간에서 보았다면 가까운 시일 내의 안정으로 풀이하는 경우가 많다. 이 꿈을 꾼 뒤에는 눈앞의 작은 변화보다 멀리 내다보는 계획을 다시 점검해보는 계기로 삼기도 한다.', '크고 든든한 안정과 행운을 상징하는 꿈으로 풀이된다', array[2,9,18,25,33,41], 5)
on conflict (dream_id, keyword) do nothing;

-- A-10. 소꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '소꿈'), '소가-새끼를-낳는-꿈', '소가 새끼를 낳는 꿈', '외양간이나 들판에서 소가 힘겹게 새끼를 낳는 장면을 지켜보는 꿈이다. 예로부터 소는 집안의 재산이나 노동력을 상징하는 동물로 여겨져 온 만큼, 그 소가 새끼를 낳는 모습은 재산이나 살림이 새롭게 불어나는 시작점을 뜻한다는 해석으로 이어지곤 한다. 송아지가 건강하게 태어나 바로 일어서는 모습까지 보았다면, 새로 시작하는 일이 큰 어려움 없이 순조롭게 자리를 잡아갈 것이라는 의미로 풀이되기도 한다. 반대로 출산 과정이 힘겹고 오래 걸렸다면, 좋은 결과를 얻기까지 그만큼의 수고와 인내가 필요하다는 뜻으로 여겨지기도 한다. 태어난 송아지가 몇 마리였는지도 눈여겨볼 부분인데, 여러 마리였다면 한 가지 일에서 여러 갈래의 성과가 파생될 수 있다는 이야기도 전해진다. 임신 중인 사람이 이 꿈을 꾸었다면 태몽으로 받아들여, 튼튼하고 복 있는 아이를 얻을 조짐으로 보는 경우도 많다.', '재산과 살림이 새롭게 불어나는 것을 상징하는 꿈', array[5,13,22,30,38,44], 5),
  ((select id from public.dreams where keyword = '소꿈'), '검은-소-꿈', '검은 소 꿈', '온몸이 새까만 검은 소를 마주하거나 그 소를 몰고 가는 꿈이다. 색이 짙고 어두운 소는 흔히 보는 누런 소보다 더 무겁고 강한 기운을 지닌 존재로 여겨져, 그만큼 크고 묵직한 변화나 성과를 예고한다는 해석이 따르곤 한다. 검은 소가 유순하게 자신을 따라왔다면 그 큰 기운을 무리 없이 자신의 것으로 받아들일 수 있다는 뜻으로 풀이되고, 반대로 소가 사납게 굴거나 다루기 어려웠다면 그만한 결과를 얻기까지 만만치 않은 과정을 거쳐야 한다는 의미로 보기도 한다. 검은 소를 타고 어딘가로 이동했다면, 지금과는 다른 국면으로 넘어가는 전환의 시기와 맞닿아 있다는 풀이도 전해진다. 색이 검다는 점 때문에 무겁거나 어두운 느낌으로 받아들이는 사람도 있지만, 전통적으로는 오히려 귀하고 특별한 기운으로 해석되는 경우가 더 많다. 소를 어디로 이끌고 갔는지, 그 목적지가 어떤 곳이었는지도 함께 떠올려보면 이 꿈의 의미를 더 구체적으로 짚어볼 수 있다.', '묵직하고 귀한 기운을 상징하는 꿈으로 풀이되곤 한다', array[8,17,24,31,42], 6)
on conflict (dream_id, keyword) do nothing;

-- A-11. 쥐꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '쥐꿈'), '쥐가-도망가는-꿈', '쥐가 도망가는 꿈', '쥐가 사람을 보자마자 놀란 듯 재빠르게 구석이나 벽 틈으로 달아나는 꿈이다. 쥐는 종종 자잘한 걱정거리나 신경 쓰이는 문제들을 상징한다고 여겨지는데, 그 쥐가 스스로 도망쳐 사라지는 모습은 마음을 짓누르던 작은 근심들이 조금씩 정리되어 가는 상황을 나타낸다는 해석으로 이어지곤 한다. 쥐를 굳이 뒤쫓지 않고 그냥 지켜만 보았다면, 억지로 해결하려 애쓰지 않아도 문제들이 자연스럽게 풀려가는 흐름을 의미한다는 풀이도 있다. 다만 재물과 관련지어 쥐를 해석하는 오랜 전통에서는, 쥐가 도망가는 모습을 작은 이익이나 기회가 손에서 빠져나가는 신호로 보기도 한다. 쥐가 도망간 방향이 자신의 공간 밖이었는지, 아니면 더 깊숙한 곳으로 숨어들었는지에 따라서도 의미가 달라진다는 이야기가 전해진다. 이 꿈을 꾼 뒤에는 최근 신경 쓰던 작은 일들 중 실제로 자연스럽게 해결된 것이 있는지 돌아보는 것도 좋다.', '작은 걱정거리가 정리되어 가는 것을 상징하는 꿈', null, 5),
  ((select id from public.dreams where keyword = '쥐꿈'), '흰-쥐-꿈', '흰 쥐 꿈', '평범한 잿빛이나 갈색 쥐가 아니라 온몸이 새하얀 흰 쥐를 만나는 꿈이다. 흰빛을 띤 동물은 예로부터 귀하고 신성한 존재로 여겨져 왔는데, 흰 쥐 역시 이런 맥락에서 특별하고 귀한 행운을 상징하는 동물로 해석되곤 한다. 흔히 쥐를 곳간의 재물과 연결짓는 전통을 떠올려보면, 흰 쥐는 그중에서도 유독 귀하고 드문 형태의 재물이나 기회를 뜻한다는 풀이가 전해진다. 흰 쥐가 자신에게 먼저 다가오거나 몸을 비볐다면, 그 귀한 기운이 스스로 찾아드는 상황으로 여겨지기도 하고, 흰 쥐를 직접 안거나 손에 올려두었다면 이미 그 행운을 자기 것으로 만들었다는 의미로 보기도 한다. 흰 쥐가 유난히 반짝이거나 빛나 보였다면 그만큼 흔치 않은 좋은 소식이 따를 조짐으로 해석하는 경우도 있다. 이 꿈은 대체로 평범하지 않은, 남다른 형태의 좋은 기운을 상징하는 꿈으로 보기도 한다.', '귀하고 특별한 행운을 상징하는 꿈으로 풀이된다', array[3,11,20,28,36,45], 6)
on conflict (dream_id, keyword) do nothing;

-- A-12. 임신하는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '임신하는 꿈'), '쌍둥이를-임신하는-꿈', '쌍둥이를 임신하는 꿈', '꿈속에서 유난히 배가 크게 부풀어 있고, 태아가 하나가 아니라 둘이라는 사실을 알게 되는 순간 놀라움과 설렘이 동시에 밀려온다. 전통적으로 쌍둥이를 임신하는 꿈은 한 번에 두 가지 좋은 일이 겹쳐서 찾아온다는 의미로 해석되곤 한다. 특히 오랫동안 준비해 온 일과 전혀 기대하지 않았던 일이 비슷한 시기에 동시에 풀리는 경우를 암시한다는 해석도 있다. 배 속에서 두 태아가 각기 다른 움직임을 보였다면, 서로 다른 방향에서 좋은 소식이 들어온다는 뜻으로 풀이되는 경우가 많다. 꿈에서 느낀 벅찬 감정이 클수록 실제로 다가올 기쁨의 크기도 그만큼 크다고 여겨지기도 한다. 아직 오지 않은 일들을 미리 축하하듯, 마음을 편안하게 가지고 주변에서 들려오는 소식들을 하나씩 챙겨보는 것도 좋겠다.', '두 가지 좋은 소식이 동시에 겹쳐 찾아온다는 의미로 해석된다', array[3,11,19,27,38], 5),
  ((select id from public.dreams where keyword = '임신하는 꿈'), '임신한-배를-만지는-꿈', '임신한 배를 만지는 꿈', '손바닥으로 둥글게 부푼 배를 조심스럽게 쓰다듬는 감촉이 유난히 생생하게 남는 꿈이다. 이런 꿈은 전통적으로 이미 자신에게 다가오고 있는 좋은 기운을 스스로 확인하고 받아들이는 과정으로 해석되곤 한다. 배를 만졌을 때 태동처럼 무언가 꿈틀거리는 느낌이 있었다면, 준비하던 일이 곧 구체적인 결실로 이어진다는 뜻으로 풀이되는 경우가 많다. 반대로 배가 단단하고 따뜻하게 느껴졌다면 지금의 노력이 안정적인 결과로 자리 잡아 가고 있다는 신호로 여겨지기도 한다. 만지는 사람이 자신이 아니라 배우자나 가족이었다면, 주변 사람의 도움으로 일이 순조롭게 풀린다는 의미를 더한다는 해석도 있다. 손끝에 남은 온기를 떠올리며, 지금 진행 중인 일에 조금 더 애정을 갖고 지켜보면 좋은 흐름을 이어갈 수 있을 것이다.', '준비하던 일이 곧 구체적인 결실로 이어진다는 신호로 여겨진다', array[2,9,14,23,31,44], 6),
  ((select id from public.dreams where keyword = '임신하는 꿈'), '유산하는-꿈', '유산하는 꿈', '꿈속에서 갑작스레 아기를 잃는 장면은 깨고 나서도 마음이 무겁게 가라앉을 만큼 힘들게 느껴지는 경우가 많다. 하지만 해몽에서는 이런 꿈을 있는 그대로의 의미보다는 상징으로 받아들이는 경우가 많아서, 준비하던 계획이 지금의 형태로는 마무리되고 새로운 방향으로 다시 시작된다는 뜻으로 풀이되곤 한다. 마음속에 오래 품고 있던 걱정이나 부담이 꿈을 통해 먼저 표출된 것이라는 해석도 있다. 꿈에서 느낀 상실감이 컸다면, 그만큼 지금 마음을 쓰고 있는 일에 대한 애착이 크다는 뜻으로 이해되기도 한다. 다만 이런 꿈은 실제 몸 상태에 대한 불안이 반영된 것일 수도 있으므로, 걱정이 계속된다면 꿈풀이보다 가까운 사람과 이야기를 나누며 마음을 다독이는 편이 좋다. 꿈은 어디까지나 마음이 지나가는 하나의 풍경일 뿐, 지금의 감정을 너무 무겁게 짊어지지 않아도 괜찮다.', '지금의 계획이 새로운 방향으로 다시 시작된다는 뜻으로 풀이된다', null, 7)
on conflict (dream_id, keyword) do nothing;

-- A-13. 조상이 나타나는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '조상이 나타나는 꿈'), '조상이-화를-내는-꿈', '조상이 화를 내는 꿈', '평소와 달리 조상이 굳은 표정으로 언성을 높이거나 매섭게 나무라는 모습으로 나타나는 꿈이다. 이런 꿈은 전통적으로 지금의 생활 방식이나 태도에 대해 다시 한번 점검해 보라는 경고의 의미로 해석되곤 한다. 특히 소홀히 하고 있던 집안일이나 관계, 약속 같은 것들을 떠올리게 하는 계기가 되기도 한다. 조상이 화를 낸 이유가 꿈속에서 구체적으로 드러났다면, 그 내용과 관련된 부분을 실제 생활에서 되짚어 보라는 신호로 여겨지기도 한다. 무섭게 느껴졌던 표정과 달리, 이는 걱정과 관심에서 비롯된 꾸짖음으로 받아들여지는 경우도 많다. 놀란 마음을 가라앉히고 최근 소홀했던 부분이 없는지 차분히 돌아보는 시간을 가져보는 것도 도움이 될 수 있다.', '생활 태도를 다시 점검해 보라는 경고의 의미로 해석된다', null, 4),
  ((select id from public.dreams where keyword = '조상이 나타나는 꿈'), '조상의-제사를-지내는-꿈', '조상의 제사를 지내는 꿈', '정성스럽게 상을 차리고 절을 올리며 조상의 제사를 지내는 꿈이다. 전통적으로 이런 꿈은 조상에 대한 마음가짐이 좋은 기운으로 이어져 집안 전체에 안정과 화목이 깃든다는 뜻으로 풀이되는 경우가 많다. 제사 음식이 풍성하게 차려져 있었다면 그만큼 생활 전반에 여유와 복이 따른다는 의미로 해석되곤 한다. 절을 올릴 때 마음이 편안하고 정성스러웠다면, 준비하고 있는 일이 순조롭게 마무리된다는 신호로 여겨지기도 한다. 제사 자리에 가족들이 함께 모여 있었다면 주변 사람들과의 관계에서도 좋은 흐름이 이어진다는 해석도 있다. 오랜만에 집안의 어른들을 떠올리며 예를 갖췄던 마음가짐을 일상에서도 이어가 보는 것이 좋겠다.', '집안에 안정과 화목이 깃든다는 뜻으로 풀이되는 길몽이다', array[4,15,22,28,36,41], 5)
on conflict (dream_id, keyword) do nothing;

-- A-14. 죽은 사람이 나오는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '죽은 사람이 나오는 꿈'), '죽은-사람이-데려가려는-꿈', '죽은 사람이 데려가려는 꿈', '돌아가신 분이 손을 내밀며 함께 가자고 이끄는 듯한 느낌을 주는 꿈으로, 잠에서 깬 뒤에도 서늘한 기운이 남는 경우가 많다. 이런 꿈은 얼핏 불길하게 느껴지지만, 해몽에서는 오히려 지금까지 붙잡고 있던 무언가를 내려놓아야 할 때가 되었다는 의미로 풀이되곤 한다. 손을 잡고 따라가려 했는지, 아니면 뿌리치고 돌아섰는지에 따라 해석이 달라지기도 한다. 뿌리치고 돌아섰다면 스스로 지켜야 할 것을 잘 지키고 있다는 뜻으로 여겨지기도 하고, 순순히 따라갔다면 마음속 미련이나 집착을 정리할 때가 되었다는 해석도 있다. 꿈에서 느낀 두려움이 컸다 해도 그 자체로 나쁜 징조라기보다는 변화에 대한 마음의 저항으로 이해되는 경우가 많다. 놀란 감정은 잠시 접어두고, 요즘 지나치게 붙잡고 있는 일이나 감정이 없는지 돌아보는 시간을 가져보면 좋겠다.', '마음속 미련이나 집착을 정리할 때가 되었다는 신호로 읽힌다', null, 5),
  ((select id from public.dreams where keyword = '죽은 사람이 나오는 꿈'), '죽은-사람이-돈을-주는-꿈', '죽은 사람이 돈을 주는 꿈', '돌아가신 분이 웃으며 다가와 손에 지폐나 동전을 쥐여 주는 꿈이다. 전통적으로 죽은 사람에게 돈을 받는 꿈은 해몽에서 손꼽히는 길몽 중 하나로 꼽히며, 뜻밖의 재물운이나 좋은 소식이 따른다는 의미로 해석되곤 한다. 건네받은 돈의 양이 많았다면 그만큼 다가올 좋은 기운의 크기도 크다는 뜻으로 풀이되는 경우가 많다. 지폐였는지 동전이었는지, 혹은 낡은 돈이었는지 새 돈이었는지에 따라서도 재물이 들어오는 형태가 다르게 풀이된다는 해석도 있다. 돈을 받으며 고맙다는 인사를 주고받았다면, 인간관계를 통해 좋은 기회가 열린다는 신호로 여겨지기도 한다. 손에 쥔 돈의 감촉이 유난히 생생했다면 며칠 안에 관련된 소식이 들려올 수 있다는 이야기도 전해진다. 꿈에서 받은 온기를 떠올리며 평소보다 조금 더 열린 마음으로 주변을 살펴보는 것도 좋겠다.', '뜻밖의 재물운이나 좋은 소식이 따른다는 손꼽히는 길몽이다', array[7,13,20,29,34,45], 6),
  ((select id from public.dreams where keyword = '죽은 사람이 나오는 꿈'), '죽은-사람이-살아-돌아오는-꿈', '죽은 사람이 살아 돌아오는 꿈', '세상을 떠난 사람이 아무 일 없었다는 듯 예전 모습 그대로 돌아와 일상적인 대화를 나누는 꿈이다. 반가움과 당혹감이 뒤섞인 채로 잠에서 깨는 경우가 많은데, 해몽에서는 이런 꿈을 그 사람에 대한 그리움이나 마무리하지 못한 감정이 표면으로 떠오른 것으로 해석하는 경우가 많다. 동시에 오랫동안 멈춰 있던 일이나 인연이 다시 움직이기 시작한다는 뜻으로 풀이되기도 한다. 돌아온 사람이 예전과 같이 밝은 모습이었다면, 지나간 상황이 긍정적인 방향으로 재개된다는 신호로 여겨지기도 한다. 반대로 표정이 어둡거나 말이 없었다면, 아직 정리되지 않은 마음이 남아 있다는 뜻으로 해석되는 경우도 있다. 꿈속 대화 내용이 유난히 또렷하게 기억난다면, 그 내용이 실제 생활에서 힌트가 될 수 있다는 이야기도 전해진다. 놀라움이 가시고 나면, 그 사람과의 기억 중 아직 마음에 남아 있는 부분이 무엇인지 천천히 짚어보는 것도 도움이 될 수 있다.', '멈춰 있던 일이나 인연이 다시 움직이기 시작한다는 뜻이다', array[16,33], 7)
on conflict (dream_id, keyword) do nothing;

-- A-15. 결혼식 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '결혼식 꿈'), '전-애인과-결혼하는-꿈', '전 애인과 결혼하는 꿈', '지금은 연락도 하지 않는 옛 연인과 나란히 서서 결혼식을 올리는 꿈이다. 실제로 다시 만나고 싶다는 뜻이라기보다는, 그 사람과의 관계에서 아직 완전히 정리되지 않은 감정이나 매듭이 남아 있다는 의미로 해석되곤 한다. 예식이 화기애애한 분위기였다면 지난 인연에 대한 마음이 이제는 편안하게 정리되었다는 신호로 여겨지기도 한다. 반대로 어색하거나 불편한 분위기였다면, 여전히 마음 한편에 풀리지 않은 앙금이 남아 있다는 뜻으로 풀이되는 경우가 많다. 결혼식 장소나 하객들의 모습이 낯설게 느껴졌다면, 지금의 삶이 그 시절과는 전혀 다른 방향으로 나아가고 있다는 뜻이라는 해석도 있다. 옛 감정에 흔들리기보다는, 그 인연이 남긴 배움이 무엇이었는지 되짚어보는 계기로 삼아보는 것도 좋겠다.', '지난 인연의 감정이 정리되거나 아직 남아있다는 신호다', array[8,25], 4),
  ((select id from public.dreams where keyword = '결혼식 꿈'), '결혼식에서-우는-꿈', '결혼식에서 우는 꿈', '화려하게 장식된 예식장 한가운데서 이유 모를 눈물이 계속 흘러내리는 꿈이다. 축하받는 자리에서 눈물이 난다는 것이 어색하게 느껴질 수 있지만, 해몽에서는 이런 꿈을 그동안 쌓아 온 감정이 자연스럽게 풀려나가는 과정으로 해석하는 경우가 많다. 눈물을 흘리면서도 표정이 편안했다면, 마음속에 있던 긴장이나 부담이 해소된다는 뜻으로 여겨지기도 한다. 반대로 눈물과 함께 답답함이나 서러움이 느껴졌다면, 아직 해결되지 않은 걱정거리가 남아 있다는 신호로 풀이되곤 한다. 신부나 신랑이 아니라 하객이 우는 장면이었다면, 주변 사람의 감정에 자신도 모르게 영향을 받고 있다는 의미로 해석되는 경우도 있다. 꿈에서 흘린 눈물만큼 마음이 한결 가벼워질 수 있으니, 요즘 쌓아두었던 감정이 있다면 조금씩 풀어내는 시간을 가져보는 것도 좋겠다.', '쌓여있던 감정이 자연스럽게 풀려나가는 과정으로 해석된다', null, 5)
on conflict (dream_id, keyword) do nothing;

-- A-16. 불이 나는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '불이 나는 꿈'), '불이-꺼지는-꿈', '불이 꺼지는 꿈', '활활 타오르던 불이 서서히 잦아들다가 마침내 완전히 꺼지는 장면을 지켜보는 꿈이다. 불이 꺼지는 방식에 따라 해석이 갈리는 편인데, 스스로 진화해서 꺼졌다면 골치를 앓던 문제가 마무리 국면에 들어섰다는 뜻으로 풀이되는 경우가 많다. 반면 저절로 사그라들며 꺼졌다면, 한동안 이어지던 열정이나 관심이 자연스럽게 식어가고 있다는 의미로 해석되곤 한다. 꺼진 자리에 연기만 남아 있었다면, 겉으로는 상황이 정리된 듯 보여도 마음속에는 아직 여운이 남아 있다는 뜻으로 여겨지기도 한다. 어둠 속에서 오히려 마음이 차분해지는 느낌이었다면, 복잡했던 상황이 정리되며 안정을 찾아간다는 해석도 있다. 불씨가 완전히 식은 자리를 보며, 지금 마무리 짓고 싶은 일이 무엇인지 한 번쯤 생각해 보는 것도 좋겠다.', '골치 아픈 문제가 마무리 국면에 들어섰다는 뜻으로 풀이된다', array[17,30], 5),
  ((select id from public.dreams where keyword = '불이 나는 꿈'), '산불이-나는-꿈', '산불이 나는 꿈', '산 전체를 뒤덮을 만큼 커다란 산불이 무섭게 번져나가는 꿈이다. 규모가 클수록 오히려 좋은 쪽으로 풀이되는 경우가 많아서, 산불이 나는 꿈은 전통적으로 넓은 범위에 걸쳐 크게 일이 확장되거나 명성이 널리 퍼지는 것을 상징하는 꿈으로 보기도 한다. 불길이 산 전체를 감싸는 모습이 장관처럼 느껴졌다면, 그만큼 벌이고 있는 일의 규모가 커진다는 뜻으로 해석되곤 한다. 바람을 타고 불이 빠르게 번져나갔다면, 소식이나 성과가 예상보다 빠르게 퍼져나간다는 의미로 여겨지기도 한다. 멀리서 그 불빛을 지켜보는 입장이었다면, 주변에서 일어나는 큰 변화의 수혜를 함께 누릴 수 있다는 해석도 있다. 뜨거운 열기가 생생하게 느껴졌던 만큼, 앞으로 다가올 기회에도 적극적으로 다가서 보는 것이 좋겠다.', '일의 규모가 크게 확장되고 명성이 퍼진다는 뜻으로 해석된다', array[1,10,18,26,39,43], 6),
  ((select id from public.dreams where keyword = '불이 나는 꿈'), '불속에서-살아남는-꿈', '불속에서 살아남는 꿈', '거센 불길에 휩싸였다가도 다치지 않고 무사히 빠져나오는 꿈이다. 위기의 한복판에 있었다는 두려움과는 달리, 이런 꿈은 전통적으로 어려운 상황을 스스로의 힘으로 이겨낸다는 의미로 해석되곤 한다. 불속에서 침착하게 길을 찾아 나왔다면, 지금 겪고 있는 어려움도 냉정하게 대처하면 충분히 헤쳐나갈 수 있다는 신호로 여겨지기도 한다. 몸에 그을음만 남고 상처가 없었다면, 고비를 넘긴 뒤에는 큰 후유증 없이 상황이 마무리된다는 뜻으로 풀이되는 경우가 많다. 누군가의 도움을 받아 빠져나왔다면, 주변 사람의 도움이 위기 극복에 중요한 역할을 한다는 해석도 있다. 불길을 뚫고 나온 뒤 느낀 안도감이 컸다면, 그만큼 실제로도 큰 짐을 덜어내는 일이 생길 수 있다는 이야기도 전해진다. 두려웠던 순간을 이겨냈다는 사실을 떠올리며, 지금 마주한 어려움에도 조금 더 자신감을 가져보는 것이 좋겠다.', '어려운 상황을 스스로의 힘으로 이겨낸다는 의미로 풀이된다', array[5,12,21,32,40], 7)
on conflict (dream_id, keyword) do nothing;

-- A-17. 물에 빠지는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '물에 빠지는 꿈'), '물에-빠진-사람을-구하는-꿈', '물에 빠진 사람을 구하는 꿈', '허우적대는 사람을 발견하고 망설임 없이 물속으로 뛰어들어 구해내는 꿈이다. 전통적으로 이런 꿈은 주변 사람에게 실질적인 도움을 주게 되거나, 자신의 능력을 인정받는 계기가 생긴다는 뜻으로 풀이되는 경우가 많다. 구해낸 사람이 아는 사람이었다면 그 사람과의 관계가 더욱 돈독해진다는 의미로 해석되곤 한다. 반대로 낯선 사람이었다면, 예상하지 못한 곳에서 좋은 인연이나 기회가 찾아온다는 신호로 여겨지기도 한다. 구조 과정이 힘들었지만 결국 성공적으로 끝났다면, 지금 애쓰고 있는 일도 결국에는 좋은 결과로 이어진다는 해석도 있다. 물 밖으로 함께 나온 뒤 안도하는 표정을 봤다면, 그 안도감만큼 실제 생활에서도 마음이 놓이는 소식이 따른다고 전해진다. 누군가를 도왔던 그 마음을 떠올리며, 앞으로도 주변을 살피는 여유를 가져보면 좋겠다.', '주변에 실질적인 도움을 주고 인정받는다는 신호로 해석된다', array[6,14,24,35,42], 4),
  ((select id from public.dreams where keyword = '물에 빠지는 꿈'), '홍수가-나는-꿈', '홍수가 나는 꿈', '거센 물살이 마을이나 집 안까지 순식간에 밀고 들어오는 홍수 꿈이다. 감당하기 어려울 만큼 밀려드는 물의 기세에 압도되기 쉽지만, 해몽에서는 이런 꿈을 한꺼번에 몰려드는 변화나 기회로 해석하는 경우가 많다. 흙탕물이 아니라 비교적 맑은 물이 밀려들었다면, 감당하기 벅찰 정도로 좋은 일이 한꺼번에 몰려온다는 뜻으로 풀이되기도 한다. 물살에 휩쓸리지 않고 높은 곳으로 몸을 피했다면, 갑작스러운 변화 속에서도 스스로 중심을 잘 지켜낸다는 의미로 여겨지기도 한다. 물이 차오르는 속도가 유난히 빨랐다면, 그만큼 상황이 예상보다 빠르게 전개될 수 있다는 신호로 해석되는 경우도 있다. 넘실대는 물을 바라보며 느낀 감정이 두려움보다 놀라움에 가까웠다면, 다가올 변화를 받아들일 준비가 되어 있다는 뜻으로 볼 수 있다. 갑작스러운 변화가 예상되더라도, 평소보다 조금 더 유연한 마음으로 상황을 지켜보는 것이 도움이 될 수 있다.', '감당하기 벅찰 만큼 좋은 일이 한꺼번에 몰려온다는 의미다', array[3,19,27], 5),
  ((select id from public.dreams where keyword = '물에 빠지는 꿈'), '흙탕물에-빠지는-꿈', '흙탕물에 빠지는 꿈', '맑지 않고 탁하게 흐려진 흙탕물 속으로 몸이 빠져드는 꿈이다. 옷이나 몸에 흙탕물이 잔뜩 묻어 찝찝한 기분이 오래 남는 경우가 많은데, 이런 꿈은 전통적으로 주변 사람과의 갈등이나 번거로운 구설에 휘말릴 수 있다는 의미로 해석되곤 한다. 물속에서 허우적대며 쉽게 빠져나오지 못했다면, 당분간 복잡한 상황이 이어질 수 있다는 신호로 풀이되는 경우가 많다. 반대로 흙탕물 속에서도 비교적 수월하게 빠져나왔다면, 골치 아픈 일이 있더라도 큰 탈 없이 지나간다는 뜻으로 여겨지기도 한다. 흙탕물이 유난히 냄새나고 불쾌하게 느껴졌다면, 가까운 사람과의 관계에서 오해가 생기지 않도록 말을 조심할 필요가 있다는 해석도 있다. 몸에 남은 얼룩을 씻어내듯, 요즘 마음에 걸리는 관계나 상황이 있다면 서둘러 매듭짓는 편이 좋겠다.', '번거로운 갈등이나 구설에 휘말릴 수 있다는 의미로 해석된다', null, 6)
on conflict (dream_id, keyword) do nothing;

-- A-18. 하늘을 나는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '하늘을 나는 꿈'), '떨어질까-불안한-채-나는-꿈', '떨어질까 불안한 채 나는 꿈', '하늘을 날고는 있지만 고도가 자꾸 흔들리고, 금방이라도 아래로 떨어질 것 같은 불안감이 계속 따라붙는 꿈이다. 두 팔을 허우적대며 균형을 잡으려 애쓰고, 땅이 가까워졌다 멀어졌다를 반복하는 장면이 이어지기도 한다. 이런 꿈은 전통적으로 지금의 위치나 상황이 생각보다 불안정하다는 신호로 해석되곤 한다. 애써 쌓아온 것을 놓칠까 봐 마음 한구석이 조마조마한 심리 상태를 반영한다는 풀이도 있다. 특히 최근 크고 작은 결정을 앞두고 있다면 더 신중해지라는 뜻으로 여겨지기도 한다. 물론 이는 오래전부터 전해 내려온 상징적 해석일 뿐, 정해진 결과를 말하는 것은 아니다. 오늘은 서두르기보다 한 번 더 확인하고 넘어가는 여유를 가져보는 것도 좋겠다.', '불안정한 상황에 대한 경계심을 상징하는 꿈으로 풀이된다', null, 4),
  ((select id from public.dreams where keyword = '하늘을 나는 꿈'), '다른-사람과-함께-나는-꿈', '다른 사람과 함께 나는 꿈', '낯선 사람이든 가까운 사람이든, 누군가와 나란히 손을 맞잡거나 옆을 지키며 함께 하늘을 날아가는 꿈이다. 혼자가 아니라는 감각이 뚜렷하게 느껴지고, 같은 방향으로 나아가고 있다는 안정감이 꿈 전반에 깔린다. 이런 장면은 전통적으로 협력이나 동행을 통해 좋은 흐름이 만들어진다는 뜻으로 해석되곤 한다. 함께 나는 상대가 가족이나 동료였다면 그 관계에서 힘을 얻는다는 의미로 풀이되는 경우가 많다. 둘이 같은 속도로 날았는지, 한쪽이 앞서갔는지에 따라 세부적인 해석이 달라진다고 보는 사람들도 있다. 이러한 풀이는 문화적으로 전해져 온 상징일 뿐이라는 점은 참고해두면 좋다. 오늘은 혼자 끙끙대던 일이 있다면 주변 사람과 나눠보는 것도 나쁘지 않은 선택이 될 수 있다.', '협력과 동행이 좋은 흐름을 만든다는 의미로 여겨진다', array[7,15,22,31,38,44], 5)
on conflict (dream_id, keyword) do nothing;

-- A-19. 돈을 줍는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '돈을 줍는 꿈'), '돈을-주웠는데-남에게-뺏기는-꿈', '돈을 주웠는데 남에게 뺏기는 꿈', '바닥에 떨어진 돈을 발견하고 반가운 마음에 주워 들었는데, 순식간에 누군가 손에서 낚아채 가거나 어느새 사라져버리는 꿈이다. 손에 쥐었던 것을 눈앞에서 놓치는 허탈함이 꿈에서 깨고 난 뒤에도 남는 경우가 많다. 이런 꿈은 전통적으로 손에 들어올 뻔한 기회를 놓치게 되는 상황과 연결해 해석되곤 한다. 방심하거나 주변을 제대로 살피지 못해 애써 얻은 것을 지키지 못하는 흐름을 경고하는 의미로 보기도 한다. 돈을 뺏은 상대가 누구였는지가 기억에 남는다면, 그 대상과의 관계를 돌아보게 하는 신호로 풀이되는 경우도 있다. 다만 이 역시 확정된 결과라기보다는 조심하라는 전통적인 상징으로 받아들이는 편이 좋다. 오늘은 이미 손에 쥔 것을 소홀히 관리하고 있지 않은지 한 번 점검해보면 도움이 될 수 있다.', '손에 든 기회를 놓칠 수 있다는 경고로 해석되곤 한다', null, 5),
  ((select id from public.dreams where keyword = '돈을 줍는 꿈'), '외국-돈을-줍는-꿈', '외국 돈을 줍는 꿈', '길을 걷다가 처음 보는 지폐나 동전을 줍는데, 어느 나라 돈인지 알아보기 힘들어 한참을 들여다보게 되는 꿈이다. 익숙하지 않은 화폐 단위와 낯선 그림 때문에 그 가치를 가늠하기 어려운 느낌이 이어지기도 한다. 이런 꿈은 전통적으로 예상하지 못한 곳, 익숙하지 않은 경로에서 기회가 찾아온다는 뜻으로 해석되곤 한다. 평소 관심 밖이었던 분야나 낯선 인연에서 뜻밖의 소식이 들려올 수 있다는 해석도 있다. 돈의 액수를 가늠할 수 없었다는 점에서, 아직은 그 기회의 크기를 알 수 없는 상태라는 의미로 풀이되는 경우가 많다. 이는 예로부터 전해지는 상징적인 풀이일 뿐이라는 점도 함께 기억해두면 좋다. 오늘은 낯설다는 이유로 지나쳤던 정보나 제안을 다시 한번 살펴보는 것도 괜찮겠다.', '낯선 곳에서 뜻밖의 기회가 찾아온다는 의미로 풀이된다', array[3,9,18,27,40], 6),
  ((select id from public.dreams where keyword = '돈을 줍는 꿈'), '돈뭉치를-발견하는-꿈', '돈뭉치를 발견하는 꿈', '서랍 속이나 상자 안, 혹은 뜻밖의 장소에서 두툼하게 묶인 돈뭉치를 발견하고 놀라는 꿈이다. 낱장의 돈이 아니라 여러 장이 한꺼번에 묶여 있는 모습을 봤다는 점에서 규모 자체가 크게 느껴지는 경우가 많다. 이런 꿈은 전통적으로 작은 수입이 아니라 제법 묵직한 기회나 성과와 연결해 해석되곤 한다. 발견한 장소가 평소 잘 열어보지 않던 곳이었다면, 미처 신경 쓰지 못했던 곳에서 성과가 나온다는 뜻으로 여겨지기도 한다. 돈뭉치의 두께나 양이 유난히 인상적이었다면 그만큼 기대감도 함께 커지는 편이라는 해석도 있다. 물론 이러한 풀이는 오래전부터 전해 내려온 상징일 뿐임을 함께 기억해두면 좋다. 오늘은 그동안 눈여겨보지 않았던 곳에 뜻밖의 기회가 숨어 있을 수 있으니 한 번 더 살펴보는 것도 좋겠다.', '묵직한 기회나 성과를 상징하는 꿈으로 여겨지기도 한다', array[5,14,23,29,36,42], 7)
on conflict (dream_id, keyword) do nothing;

-- A-20. 로또 당첨되는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '로또 당첨되는 꿈'), '로또-번호를-알려주는-꿈', '로또 번호를 알려주는 꿈', '꿈속에서 누군가 다가와 귓속말처럼 몇 개의 숫자를 알려주고, 잠에서 깬 뒤에도 그 숫자를 떠올리려 애쓰게 되는 꿈이다. 알려준 사람이 낯선 얼굴이었는지, 익숙한 사람이었는지에 따라 기억에 남는 느낌이 조금씩 다르다는 이야기도 있다. 이런 꿈은 전통적으로 무의식 속에 자리한 기대와 바람이 구체적인 형태로 드러난 것으로 해석되곤 한다. 숫자를 또렷하게 기억했다면 그만큼 마음속 기대가 강하게 자리하고 있다는 뜻으로 풀이되는 경우가 많다. 다만 꿈에서 본 숫자가 실제 결과와 이어진다는 근거는 없으며, 이는 어디까지나 심리적인 상징으로 받아들이는 것이 좋다는 해석도 있다. 그보다는 무언가를 간절히 바라고 있는 지금의 마음 상태를 돌아보게 하는 꿈으로 여겨지기도 한다. 오늘은 그 숫자보다 스스로 무엇을 기대하고 있는지를 한 번 들여다보는 시간을 가져봐도 좋겠다.', '마음속 기대와 바람이 드러난 상징으로 해석되곤 한다', array[8,19,27,35], 4),
  ((select id from public.dreams where keyword = '로또 당첨되는 꿈'), '로또를-사는-꿈', '로또를 사는 꿈', '복권 판매점 앞에 줄을 서 있다가 차례가 되어 번호를 고르고 로또를 사는 꿈이다. 어떤 숫자를 고를지 한참을 고민하다가 마침내 용지를 내미는 순간의 설렘이 꿈 속에서도 생생하게 느껴지곤 한다. 이런 꿈은 전통적으로 변화를 향한 기대와 바람이 행동으로 이어지는 모습을 상징하는 꿈으로 보기도 한다. 그저 바라기만 하는 것이 아니라 직접 나서서 무언가를 시도하려는 마음가짐과 연결해 해석되는 경우가 많다. 산 로또를 손에 쥐고 결과를 기다리는 장면까지 이어졌다면, 기대감이 한동안 이어질 것이라는 뜻으로 여겨지기도 한다. 이러한 해석 역시 문화적으로 전해 내려온 상징일 뿐임을 참고해두면 좋다. 오늘은 막연히 바라기만 했던 일이 있다면 작은 것부터 실제로 행동에 옮겨보는 것도 괜찮겠다.', '변화를 향한 기대가 행동으로 이어짐을 상징한다', array[2,11,20,28,33,45], 5)
on conflict (dream_id, keyword) do nothing;

-- A-21. 산에 오르는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '산에 오르는 꿈'), '산에서-길을-잃는-꿈', '산에서 길을 잃는 꿈', '등산을 하다가 어느 순간 다니던 길이 사라지고, 사방이 비슷비슷한 나무로 둘러싸여 방향을 가늠할 수 없게 되는 꿈이다. 분명 따라오던 표지판이나 이정표가 더 이상 보이지 않아 당황스러운 마음이 커지기도 한다. 이런 꿈은 전통적으로 지금 나아가고 있는 방향에 대한 확신이 흔들리는 상태와 연결해 해석되곤 한다. 목표는 있지만 그 목표에 닿는 방법을 잘 모르겠는 심리 상태를 반영한다는 풀이도 있다. 길을 잃은 채로 헤맨 시간이 길게 느껴졌다면, 그만큼 혼란스러운 마음이 오래 이어지고 있다는 뜻으로 보기도 한다. 다만 이는 예로부터 전해지는 상징적인 해석일 뿐, 실제 결과를 단정하는 것은 아니다. 오늘은 계획했던 일의 방향을 다시 한번 차분히 점검해보는 시간을 가져보면 좋겠다.', '방향에 대한 확신이 흔들리는 상태를 상징하는 꿈이다', null, 4),
  ((select id from public.dreams where keyword = '산에 오르는 꿈'), '험한-산을-오르는-꿈', '험한 산을 오르는 꿈', '바위투성이의 가파른 산길을 두 손까지 짚어가며 오르는, 유난히 힘겨운 등산의 꿈이다. 발을 디딜 때마다 돌이 흔들리고 숨이 가빠오지만, 멈추지 않고 계속 위를 향해 나아가는 장면이 이어진다. 이런 꿈은 전통적으로 쉽지 않은 과정을 거쳐야 원하는 것을 이룰 수 있다는 뜻으로 해석되곤 한다. 험한 길일수록 그 끝에 닿았을 때의 성취감도 크다는 의미로 풀이되는 경우가 많다. 중간에 포기하지 않고 끝까지 오르는 모습을 보였다면, 지금의 어려움을 견뎌낼 힘이 충분하다는 신호로 여겨지기도 한다. 이러한 해석은 오래전부터 전해 내려온 상징일 뿐이라는 점도 함께 기억해두면 좋다. 오늘 조금 벅차게 느껴지는 일이 있다면, 포기하기보다 한 걸음씩 더 나아가 보는 것도 괜찮겠다.', '어려움을 견뎌야 원하는 것을 이룬다는 의미로 풀이된다', array[6,13,21,30,37], 5)
on conflict (dream_id, keyword) do nothing;

-- A-22. 바다를 보는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '바다를 보는 꿈'), '바다에서-수영하는-꿈', '바다에서 수영하는 꿈', '넓게 펼쳐진 바다 한가운데서 자유롭게 팔다리를 저으며 수영하는 꿈이다. 파도가 부드럽게 몸을 밀어주는 느낌이 들고, 물속에서도 답답함 없이 편안하게 움직여지는 감각이 이어진다. 이런 꿈은 전통적으로 마음속 걱정이나 얽매임에서 벗어나 자유로워진 상태를 상징하는 꿈으로 보기도 한다. 넓은 바다를 두려움 없이 헤엄쳤다면, 지금의 환경이나 상황에 잘 적응하고 있다는 뜻으로 풀이되는 경우가 많다. 물살을 가르며 나아가는 힘이 유난히 강하게 느껴졌다면 그만큼 활력이 채워지고 있다는 해석도 있다. 다만 이는 문화적으로 전해 내려온 상징적인 풀이일 뿐임을 참고해두면 좋다. 오늘은 그동안 움츠러들어 있던 일이 있다면 조금 더 자유롭게 시도해보는 것도 나쁘지 않겠다.', '걱정에서 벗어난 자유로운 상태를 상징하는 꿈으로 본다', array[4,12,19,26,34,41], 4),
  ((select id from public.dreams where keyword = '바다를 보는 꿈'), '배를-타고-바다에-나가는-꿈', '배를 타고 바다에 나가는 꿈', '항구에서 배에 올라 엔진 소리와 함께 서서히 육지가 멀어지는 것을 지켜보는 꿈이다. 뒤돌아볼수록 작아지는 해안선과 달리, 앞으로는 끝없이 펼쳐진 바다만 보이는 장면이 이어지기도 한다. 이런 꿈은 전통적으로 익숙한 곳을 벗어나 새로운 시작을 향해 나아가는 모습과 연결해 해석되곤 한다. 바다가 잔잔했다면 그 도전이 비교적 순조롭게 풀려나갈 것이라는 뜻으로 여겨지기도 한다. 배를 직접 몰았는지, 그저 타고 있었는지에 따라 스스로 상황을 이끄는 정도가 다르게 해석된다는 이야기도 있다. 이러한 풀이는 예로부터 전해지는 상징일 뿐이라는 점도 함께 기억해두면 좋다. 오늘은 미뤄왔던 새로운 시도가 있다면 한 걸음 내디뎌 보는 것도 괜찮은 선택이 될 수 있다.', '새로운 시작을 향한 도전을 상징하는 꿈으로 해석된다', array[1,10,17,25,33], 5)
on conflict (dream_id, keyword) do nothing;

-- A-23. 도둑에게 쫓기는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '도둑에게 쫓기는 꿈'), '도둑이-물건을-훔쳐가는-꿈', '도둑이 물건을 훔쳐가는 꿈', '눈앞에서 도둑이 물건을 챙겨 들고 유유히 빠져나가는데, 몸이 굳은 듯 움직이지 못하고 그저 지켜보게 되는 꿈이다. 소리를 지르려 해도 목소리가 나오지 않거나, 쫓아가려 해도 다리가 마음처럼 움직이지 않는 답답함이 함께 느껴지곤 한다. 이런 꿈은 전통적으로 가진 것을 지키지 못하고 속수무책으로 잃게 되는 상황에 대한 불안을 반영한다는 해석이 있다. 시간이나 에너지, 기회처럼 눈에 보이지 않는 것을 소모하고 있다는 경고로 풀이되는 경우도 있다. 훔쳐 간 물건이 특별히 아끼던 것이었다면, 그만큼 상실감이 크게 느껴지는 것으로 여겨지기도 한다. 다만 이는 예로부터 전해지는 상징적 해석일 뿐, 실제로 벌어질 일을 가리키는 것은 아니다. 오늘은 소홀히 하고 있던 것이 없는지 주변을 한 번 더 살펴보는 것이 도움이 될 수 있다.', '가진 것을 지키지 못할 불안을 반영한 꿈으로 여겨진다', null, 4),
  ((select id from public.dreams where keyword = '도둑에게 쫓기는 꿈'), '집에-도둑이-들었지만-무사한-꿈', '집에 도둑이 들었지만 무사한 꿈', '외출했다 돌아와 보니 문이 열려 있거나 어질러진 흔적이 있어 도둑이 든 것을 알아차리지만, 다행히 크게 잃은 것 없이 무사한 꿈이다. 놀란 가슴을 쓸어내리며 집 안을 하나하나 확인해보는 장면으로 이어지기도 한다. 이런 꿈은 전통적으로 위기를 겪을 뻔했지만 큰 탈 없이 지나간다는 뜻으로 해석되곤 한다. 실제로 무언가를 잃은 것이 아니라 흔적만 남았다는 점에서, 위험을 아슬아슬하게 피해 가는 흐름으로 풀이되는 경우가 많다. 놀란 마음이 컸던 만큼 그 뒤에 찾아오는 안도감도 크게 느껴진다는 해석도 있다. 이러한 풀이는 오래전부터 전해 내려온 상징일 뿐이라는 점도 함께 참고해두면 좋다. 오늘은 큰 걱정 없이 하루를 보내되, 문단속처럼 기본적인 것은 한 번 더 챙겨보는 것도 괜찮겠다.', '위기를 무사히 넘긴다는 안도감을 상징하는 꿈으로 본다', array[9,16,24,32,39], 5)
on conflict (dream_id, keyword) do nothing;

-- A-24. 시험 보는 꿈
insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '시험 보는 꿈'), '시험을-망치는-꿈', '시험을 망치는 꿈', '시험지를 받아 들었는데 머릿속이 하얘지고, 아는 문제조차 손을 대지 못한 채 시간만 흘러가는 꿈이다. 답안지 곳곳이 빈칸으로 남은 채 종료 종이 울리는 장면에서 식은땀을 흘리며 깨어나는 경우도 많다. 이런 꿈은 전통적으로 누군가에게 평가받는 상황에 대한 부담감이나 불안이 드러난 것으로 해석되곤 한다. 실제 시험과 무관하게, 현재 마주한 일을 제대로 해내지 못할까 봐 걱정하는 마음을 반영한다는 풀이도 있다. 유난히 많은 문제를 못 풀었다는 느낌이 강했다면, 그만큼 부담감이 크게 자리하고 있다는 뜻으로 여겨지기도 한다. 다만 이는 예로부터 전해지는 상징적인 해석일 뿐, 실제 결과와는 무관하다는 점도 기억해두면 좋다. 오늘은 스스로에게 너무 높은 기준을 들이대고 있지 않은지 한 번 돌아보는 것도 좋겠다.', '평가받는 상황에 대한 부담감을 반영한 꿈으로 해석된다', null, 4),
  ((select id from public.dreams where keyword = '시험 보는 꿈'), '시험공부를-하나도-못한-꿈', '시험공부를 하나도 못한 꿈', '당장 오늘이 시험인데 정작 공부를 하나도 하지 못했다는 사실을 뒤늦게 깨닫고 당황하는 꿈이다. 책을 급하게 펼쳐 훑어보지만 머릿속에 아무것도 들어오지 않고, 시간은 자꾸만 줄어드는 초조함이 이어지기도 한다. 이런 꿈은 전통적으로 무언가를 앞두고 준비가 부족하다고 느끼는 불안한 심리 상태를 반영한다는 해석이 있다. 실제로 공부와 관련이 없더라도, 다가오는 일에 충분히 대비하지 못했다는 걱정이 형태를 바꿔 나타난 것으로 풀이되는 경우가 많다. 시험 시작 시간이 코앞으로 다가올수록 조급함이 커졌다면, 그만큼 현실에서도 시간에 쫓기고 있다는 뜻으로 보기도 한다. 이러한 풀이 역시 문화적으로 전해 내려온 상징일 뿐임을 참고해두면 좋다. 오늘은 미뤄뒀던 준비가 있다면 늦기 전에 조금씩 시작해보는 것이 도움이 될 수 있다.', '준비 부족에 대한 불안한 심리를 반영한 꿈으로 풀이된다', null, 5)
on conflict (dream_id, keyword) do nothing;

-- ============================================================
-- B. 신규 Parent 20개 + dream_number_mappings + Situation (총 119개)
-- ============================================================

-- B-1. 고양이꿈 (신규 Parent, category: 동물)
with new_dream_1 as (
  insert into public.dreams (keyword, category, interpretation)
  select '고양이꿈', '동물', '## 고양이꿈은 보통 어떻게 해석할까?
고양이는 예민한 감각과 독립적인 기질을 지닌 동물로 여겨져, 꿈속에서는 경계심이나 직감, 혹은 가까운 관계에서 오가는 감정과 연결해 해석되는 경우가 많다. 전통적으로 고양이가 등장하는 꿈은 상황에 따라 좋은 조짐과 조심해야 할 신호가 함께 담겨 있다고 보는 경우가 많아, 고양이의 태도나 표정을 함께 살펴보는 것이 중요하다. 다가오는지 멀어지는지, 편안해 보이는지 경계하는지에 따라 해석의 방향이 크게 달라진다는 점도 특징으로 꼽힌다. 고양이라는 동물 자체가 사람과 가깝고도 알 수 없는 존재로 여겨지는 만큼, 이 꿈은 가까운 관계 속에서 아직 다 파악하지 못한 마음을 돌아보게 하는 계기로 받아들여지기도 한다.

## 고양이의 색깔에 따라
같은 고양이라도 털 색깔에 따라 느낌이 달라지는 경우가 많다. 검은 고양이는 문화권에 따라 불길함과 신비로움이 엇갈려 해석되는 대표적인 소재로 꼽히고, 흰 고양이는 대체로 맑고 좋은 기운이나 반가운 소식과 연결해 해석되는 경우가 많다.

## 행동이나 상황에 따라
고양이가 보이는 행동에 따라서도 해석이 크게 갈린다. 조용히 곁을 지키거나 품에 안기는 모습은 안정과 좋은 인연을, 할퀴거나 쫓아오는 모습은 가까운 관계의 갈등이나 현실의 부담감을 나타내는 경우가 많다. 새끼 고양이가 등장하는 꿈은 작은 시작이 자라나는 조짐으로, 고양이가 힘을 잃는 꿈은 한 국면이 마무리되고 있다는 신호로 풀이되기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '고양이꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,9,17,24,32,40] from new_dream_1;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이를-보는-꿈', '고양이를 보는 꿈', '멀리서 고양이를 발견하거나 스쳐 지나가는 것을 보는 꿈이다. 고양이는 예로부터 예민한 감각과 독립적인 기질을 지닌 동물로 여겨져, 꿈속에 등장할 때는 주변을 향한 경계심이나 직감이 강조되는 상징으로 해석되곤 한다. 특별한 행동 없이 그냥 바라보는 정도였다면, 최근 생활 속에서 뭔가를 지켜보거나 관망하는 태도와 맞닿아 있다는 해석도 있다. 고양이가 여유롭게 움직이고 있었는지, 아니면 잔뜩 웅크려 있었는지에 따라 느낌이 달라졌을 것이다. 평온한 모습이었다면 지금의 상황을 침착하게 바라보고 있다는 뜻으로, 긴장한 모습이었다면 마음 한편에 남아있는 불안이 투영된 것으로 풀이되기도 한다. 꿈에서 느낀 감정을 되짚어보면 현재 자신이 어떤 태도로 상황을 대하고 있는지 가늠해볼 수 있다.', '주변을 향한 경계심과 관망의 태도를 보여주는 꿈', array[3,12,21,29,36], 1),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이가-집으로-들어오는-꿈', '고양이가 집으로 들어오는 꿈', '낯선 고양이가 자연스럽게 집 안으로 들어와 자리를 잡는 꿈이다. 집이라는 공간은 안정과 소유를 뜻하는 경우가 많아, 그 안으로 무언가가 들어오는 장면은 전통적으로 새로운 인연이나 기회가 생활 속으로 스며드는 상황과 연결해 해석되곤 한다. 고양이가 겁 없이 편안하게 들어왔다면 그 인연이나 기회가 순조롭게 자리를 잡을 것이라는 뜻으로 풀이되는 경우가 많다. 반대로 고양이가 조심스럽게 눈치를 보며 들어왔다면, 아직은 낯설고 조심스러운 변화의 초입 단계로 보기도 한다. 이 꿈을 꾼 뒤에는 최근 주변에서 새롭게 다가온 사람이나 제안이 있었는지 돌아보는 계기로 삼는 경우도 있다. 고양이가 들어온 뒤 집안에서 어떻게 행동했는지도 함께 떠올려보면 좋은 실마리가 될 수 있다.', '새로운 인연이나 기회가 생활 속으로 들어오는 신호', array[2,11,19,27,34,42], 2),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이를-안는-꿈', '고양이를 안는 꿈', '고양이를 품에 안아 올리거나 가까이 끌어안는 꿈이다. 안는다는 행위는 무언가를 자신의 영역 안으로 받아들이고 지키려는 마음과 겹쳐지는 경우가 많아, 소중한 관계나 성과를 품는 상황으로 해석되곤 한다. 고양이가 얌전히 안겨 있었다면 관계나 상황이 안정적으로 자리 잡고 있다는 뜻으로 여겨지기도 하고, 품 안에서 꿈틀대며 벗어나려 했다면 아직 완전히 자기 것으로 만들지 못한 무언가에 대한 조바심을 나타낸다는 해석도 있다. 안았을 때 느껴진 온기나 무게감이 유독 생생했다면, 그만큼 마음속에서 그 대상을 소중하게 여기고 있다는 뜻으로 볼 수 있다. 이런 꿈을 꾼 뒤에는 곁에 있는 사람이나 관계에 조금 더 마음을 쏟아보는 계기로 삼기도 한다. 고양이의 표정이나 울음소리까지 기억난다면 그 느낌도 함께 되짚어볼 만하다.', '소중한 관계나 성과를 품고 지키려는 마음', array[5,14,23,30,45], 3),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이에게-할퀴이는-꿈', '고양이에게 할퀴이는 꿈', '다가가거나 손을 내밀었다가 고양이에게 갑자기 할퀴이는 꿈이다. 예상치 못한 순간에 상처를 입는다는 점에서, 전통적으로 가까운 관계에서 비롯된 작은 갈등이나 배신감과 연결해 해석되곤 한다. 할퀸 자리가 따끔하고 아팠다면 그 감정의 여운이 실제로도 오래 남을 수 있다는 뜻으로 풀이되는 경우가 많고, 별다른 통증 없이 지나갔다면 곧 잊힐 만한 사소한 마찰로 보기도 한다. 어떤 상황에서 고양이가 갑자기 발톱을 세웠는지를 떠올려보면, 최근 자신이 무심코 건드린 상대의 예민한 부분이 있었는지 짚어보는 실마리가 되기도 한다. 이 꿈은 관계에서 거리를 조절할 필요가 있다는 신호로 받아들여지는 경우도 있다. 상처의 깊이보다는 그 상황에서 느낀 놀라움이나 서운함에 조금 더 주목해볼 만하다.', '가까운 관계에서 비롯된 작은 갈등이나 서운함', array[16], 4),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이가-우는-꿈', '고양이가 우는 꿈', '어디선가 고양이의 울음소리가 들려오거나, 눈앞의 고양이가 애처롭게 우는 소리를 내는 꿈이다. 고양이 울음은 유독 사람의 울음소리와 닮아 있어, 꿈속에서 들으면 마음이 불편해지는 경우가 많고 전통적으로 주변의 걱정거리나 마음 쓰이는 소식과 연결해 해석되곤 한다. 울음소리가 멀리서 희미하게 들렸다면 아직은 막연한 불안 정도로 여겨지기도 하고, 바로 곁에서 크고 또렷하게 울었다면 조만간 마주할 상황에 대한 마음의 대비가 필요하다는 해석도 있다. 우는 고양이를 달래주려 했는지, 아니면 그냥 지나쳤는지도 그 대응 방식과 겹쳐 볼 수 있는 부분이다. 이 꿈을 꾼 뒤에는 주변 사람들의 안부를 한 번 더 챙겨보는 계기로 삼는 경우도 있다. 울음소리의 느낌이 슬픔에 가까웠는지 짜증에 가까웠는지 되짚어보는 것도 도움이 될 수 있다.', '주변의 걱정거리나 마음 쓰이는 소식에 대한 예감', null, 5),
  ((select id from public.dreams where keyword = '고양이꿈'), '새끼-고양이가-나오는-꿈', '새끼 고양이가 나오는 꿈', '어미 고양이 곁에서 작은 새끼 고양이들이 여러 마리 나오거나 태어나는 장면을 보는 꿈이다. 새로운 생명이 여럿 등장하는 모습은 전통적으로 시작 단계에 있는 일이 여러 갈래로 뻗어나가거나, 작은 성과들이 조금씩 늘어나는 상황을 상징하는 꿈으로 보기도 한다. 새끼 고양이들이 건강하게 꼬물거리며 움직였다면 그만큼 일이 순조롭게 자라날 조짐으로 풀이되는 경우가 많고, 유난히 약하거나 힘없어 보였다면 아직은 세심한 관리가 필요한 단계라는 뜻으로 해석되기도 한다. 새끼의 수가 유독 많게 느껴졌다면 최근 벌여놓은 일이나 관심사가 여러 갈래로 나뉘어 있는 상황과 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 막 시작한 계획들을 하나씩 챙겨보는 계기로 삼는 경우도 있다. 어미 고양이가 새끼들을 어떻게 대했는지도 함께 떠올려보면 좋은 실마리가 된다.', '작은 성과나 새로운 시작이 여러 갈래로 자라나는 조짐', array[4,10,18,25,33,41], 6),
  ((select id from public.dreams where keyword = '고양이꿈'), '검은-고양이-꿈', '검은 고양이 꿈', '온몸이 검은 고양이가 눈앞에 나타나거나 길을 가로지르는 꿈이다. 검은 고양이는 문화권에 따라 불길함의 상징으로 여겨지기도 하지만, 한편으로는 신비롭고 영민한 존재로 받아들여지는 경우도 있어 해석이 엇갈리는 대표적인 소재로 꼽힌다. 검은 고양이가 유유히 지나가기만 했다면 대수롭지 않게 넘길 만한 변화의 조짐 정도로 보기도 하고, 눈을 마주치거나 가까이 다가왔다면 평소와는 다른 시선으로 상황을 다시 보라는 신호로 해석되기도 한다. 꿈속에서 느낀 감정이 두려움이었는지 호기심이었는지에 따라 그 의미도 다르게 받아들여지는 경우가 많다. 낯선 존재를 마주했을 때의 반응이 곧 지금 자신이 변화를 대하는 태도와 닮아 있다는 해석도 있다. 검은 고양이의 눈빛이나 움직임이 유독 인상 깊었다면 그 부분을 조금 더 곱씹어볼 만하다.', '해석이 엇갈리는 변화의 조짐과 시선을 다시 볼 신호', array[13,28], 7),
  ((select id from public.dreams where keyword = '고양이꿈'), '흰-고양이-꿈', '흰 고양이 꿈', '새하얀 털을 가진 고양이가 유독 눈에 띄게 등장하는 꿈이다. 흰색은 예로부터 깨끗함과 순수함을 나타내는 색으로 여겨져, 흰 고양이가 등장하는 꿈은 전통적으로 맑고 좋은 기운이나 반가운 소식과 연결해 해석되곤 한다. 흰 고양이가 여유롭게 다가와 곁을 맴돌았다면 가까운 시일 안에 마음이 놓이는 소식을 들을 조짐으로 풀이되는 경우가 많고, 멀리서 지켜보기만 했다면 아직은 그 좋은 기운이 서서히 다가오고 있는 단계로 보기도 한다. 털의 흰빛이 유난히 눈부시게 느껴졌다면 그만큼 지금 필요한 변화나 정리가 뚜렷하게 다가오고 있다는 뜻으로 해석되기도 한다. 이 꿈을 꾼 뒤에는 미뤄뒀던 정리나 마음의 짐을 하나씩 덜어보는 계기로 삼는 경우도 있다. 흰 고양이와 어떤 방식으로 마주쳤는지도 함께 떠올려보면 좋은 실마리가 된다.', '맑고 좋은 기운과 반가운 소식이 다가오는 조짐', array[6,15,24,32,39], 8),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이가-죽는-꿈', '고양이가 죽는 꿈', '눈앞에서 고양이가 힘을 잃고 숨을 거두는 모습을 지켜보는 꿈이다. 꿈에서 마주치는 죽음은 실제 죽음보다는 어떤 상태나 국면이 완전히 끝나고 새로운 단계로 넘어가는 상징으로 해석되는 경우가 많아, 지나치게 불길하게만 받아들일 필요는 없다는 시각도 있다. 고양이의 죽음을 슬프게 받아들였다면 그만큼 마음속에서 놓아주기 어려운 무언가가 있다는 뜻으로 풀이되기도 하고, 덤덤하게 지켜봤다면 이미 정리할 준비가 되어 있는 상태로 보기도 한다. 어떤 이유로 고양이가 힘을 잃었는지, 그 곁에 자신이 어떤 태도로 있었는지도 함께 떠올려보면 지금 마무리하고 싶은 일이 무엇인지 가늠해볼 수 있다. 이 꿈을 꾼 뒤에는 오래 붙잡고 있던 상황을 정리하는 계기로 삼는 경우도 있다. 꿈에서 느낀 감정의 크기가 실제 상황의 무게와 비슷한지 견주어보는 것도 도움이 된다.', '한 국면이 끝나고 새로운 단계로 넘어가는 상징', array[37], 9),
  ((select id from public.dreams where keyword = '고양이꿈'), '고양이가-쫓아오는-꿈', '고양이가 쫓아오는 꿈', '고양이가 뒤를 바짝 따라오거나 도망치는 자신을 쫓아오는 꿈이다. 무언가에게 쫓기는 상황은 대체로 현실에서 느끼는 압박감이나 피하고 싶은 문제가 꿈속에 그대로 옮겨진 것으로 해석되는 경우가 많다. 고양이가 사납게 으르렁대며 쫓아왔다면 그 압박감이 꽤 구체적이고 급박하게 느껴지는 상태라는 뜻으로 풀이되기도 하고, 장난스럽게 뒤따라오는 정도였다면 아직은 감당할 만한 수준의 부담으로 보기도 한다. 쫓기다가 결국 붙잡혔는지, 아니면 끝내 따돌렸는지에 따라 그 문제를 대하는 자신의 태도가 다르게 비춰질 수 있다. 도망치는 동안 느낀 숨 가쁨이나 초조함은 최근 미뤄두고 있는 일에 대한 부담과 맞닿아 있다는 해석도 있다. 이 꿈을 꾼 뒤에는 피하고 있던 문제를 정면으로 마주해보는 계기로 삼는 경우도 있다.', '피하고 싶은 문제나 현실의 압박감이 투영된 꿈', array[8], 10)
on conflict (dream_id, keyword) do nothing;

-- B-2. 아기꿈 (신규 Parent, category: 인물)
with new_dream_2 as (
  insert into public.dreams (keyword, category, interpretation)
  select '아기꿈', '인물', '## 아기꿈은 보통 어떻게 해석할까?
아기는 아직 다 자라지 않은 가능성이나 이제 막 시작된 일을 상징하는 경우가 많아, 꿈에 등장하는 아기는 대체로 새로운 시작이나 그에 따르는 책임감과 연결해 해석되곤 한다. 아기를 어떻게 대했는지, 아기가 어떤 상태였는지에 따라 해석의 방향이 크게 갈리는 것도 특징이다. 아기가 편안하고 밝은 모습이었다면 좋은 결실이나 순조로운 진행을, 울거나 사라지는 모습이었다면 아직 해결되지 않은 걱정이나 불안을 나타내는 경우가 많다는 해석도 있다. 이처럼 아기꿈은 시작 단계에 있는 일들을 얼마나 세심하게 돌보고 있는지 돌아보게 하는 계기로 받아들여지기도 한다.

## 아기의 감정 표현에 따라
아기가 우는 꿈은 마음속 걱정거리를, 웃는 꿈은 근심이 걷히는 시기를 나타내는 경우가 많다. 말을 할 리 없는 아기가 말을 하는 꿈은 예상치 못한 곳에서 전해지는 중요한 소식으로 해석되기도 한다.

## 아기와 함께한 상황에 따라
아기를 안거나 업는 꿈은 맡은 일과 책임을 정성껏 돌보는 마음을, 아기를 낳는 꿈은 오래 준비해온 일의 결실을 상징하는 경우가 많다. 반대로 아기를 잃어버리는 꿈은 무언가를 제대로 챙기지 못하고 있다는 불안을 나타내고, 낯선 아기나 쌍둥이 아기를 보는 꿈은 새로운 인연이나 겹쳐서 찾아오는 좋은 일과 연결해 풀이되기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '아기꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[4,13,20,29,37,45] from new_dream_2;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '아기꿈'), '아기를-안는-꿈', '아기를 안는 꿈', '작고 여린 아기를 품에 안고 다독이는 꿈이다. 아기는 시작 단계에 있는 일이나 아직 다 자라지 않은 가능성을 상징하는 경우가 많아, 이런 존재를 품에 안는 장면은 전통적으로 새롭게 맡게 된 일이나 관계를 정성껏 돌보려는 마음과 연결해 해석되곤 한다. 아기가 품 안에서 편안하게 잠들었다면 그 일이 순조롭게 자리 잡아가고 있다는 뜻으로 풀이되는 경우가 많고, 계속 뒤척이거나 보챘다면 아직은 손이 많이 가는 단계라는 해석도 있다. 안았을 때 느껴진 무게감이나 온기가 유난히 생생했다면, 그만큼 그 대상에 마음을 많이 쏟고 있다는 신호로 볼 수 있다. 이 꿈을 꾼 뒤에는 최근 시작한 일이나 새로 맡은 책임을 조금 더 세심하게 챙겨보는 계기로 삼는 경우도 있다. 아기의 표정이 편안했는지도 함께 떠올려보면 좋은 실마리가 된다.', '새로 맡은 일이나 관계를 정성껏 돌보는 마음', array[5,13,22,31,44], 1),
  ((select id from public.dreams where keyword = '아기꿈'), '아기가-우는-꿈', '아기가 우는 꿈', '품 안이나 눈앞에서 아기가 그치지 않고 우는 꿈이다. 아기의 울음은 아직 말로 표현하지 못하는 불편함이나 필요를 알리는 신호이기 때문에, 이런 꿈은 전통적으로 마음 한편에 남아있는 걱정이나 아직 해결되지 않은 문제와 연결해 해석되는 경우가 많다. 울음소리가 유독 크고 다급하게 느껴졌다면 그 걱정거리가 생각보다 시급하게 다가와 있다는 뜻으로 풀이되기도 하고, 달래자 금방 그쳤다면 조금만 신경 써주면 곧 해결될 문제로 보기도 한다. 아기를 어떻게든 달래려 애썼는지, 당황해서 어쩔 줄 몰랐는지도 그 상황을 대하는 자신의 태도와 겹쳐 볼 수 있는 부분이다. 이 꿈을 꾼 뒤에는 미뤄뒀던 걱정거리를 하나씩 들여다보는 계기로 삼는 경우도 있다.', '마음속에 남아있는 걱정이나 미해결 과제의 신호', null, 2),
  ((select id from public.dreams where keyword = '아기꿈'), '아기가-웃는-꿈', '아기가 웃는 꿈', '아기가 까르르 소리 내어 웃거나 환하게 미소 짓는 꿈이다. 아기의 웃음은 순수하고 걱정 없는 상태를 그대로 드러내는 모습이어서, 전통적으로 근심이 걷히고 마음이 놓이는 시기가 다가온다는 의미로 해석되곤 한다. 아기가 나를 보며 웃었다면 그 좋은 기운이 자신에게 직접 닿아 있다는 뜻으로 풀이되는 경우가 많고, 혼자 즐거워하는 모습을 지켜보기만 했다면 주변에서 좋은 소식이 들려올 조짐으로 보기도 한다. 웃음소리가 유독 맑고 오래 이어졌다면 그만큼 그 기운이 가볍게 스쳐 가지 않고 한동안 이어질 것이라는 해석도 있다. 이 꿈을 꾼 뒤에는 그동안 미뤄뒀던 즐거운 계획을 실행에 옮겨보는 계기로 삼는 경우도 있다.', '근심이 걷히고 마음이 놓이는 시기가 다가오는 신호', array[7,16,25,34,40,45], 3),
  ((select id from public.dreams where keyword = '아기꿈'), '낯선-아기를-보는-꿈', '낯선 아기를 보는 꿈', '누구의 아기인지 알 수 없는 낯선 아기를 우연히 마주치는 꿈이다. 익숙하지 않은 존재가 등장하는 만큼, 이런 꿈은 전통적으로 아직 실체가 뚜렷하지 않은 새로운 가능성이나 낯선 인연이 다가오고 있음을 암시하는 것으로 해석되곤 한다. 낯선 아기가 나를 보고 방긋 웃었다면 그 가능성이 긍정적인 방향으로 다가올 조짐으로 풀이되는 경우가 많고, 무표정하거나 낯가림을 했다면 아직은 서로 거리를 두고 지켜보는 단계로 보기도 한다. 그 아기를 어떻게 대했는지, 지나쳤는지 다가가 살펴봤는지도 새로운 상황을 받아들이는 자신의 태도와 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 최근 새롭게 알게 된 사람이나 제안이 있었는지 돌아보는 계기로 삼는 경우도 있다.', '아직 실체가 뚜렷하지 않은 새로운 인연이나 가능성', array[19,27], 4),
  ((select id from public.dreams where keyword = '아기꿈'), '아기를-낳는-꿈', '아기를 낳는 꿈', '산고를 겪은 끝에 직접 아기를 낳는 꿈이다. 출산은 오랜 시간과 노력 끝에 무언가가 마침내 세상에 나오는 과정이어서, 전통적으로 오래 준비해온 일이나 계획이 결실을 맺는 상황을 상징하는 꿈으로 보기도 한다. 출산 과정이 순조로웠다면 그 결실이 무리 없이 이루어질 조짐으로 풀이되는 경우가 많고, 힘들고 고통스러운 과정이었다면 그만큼 결실을 맺기까지 마지막 고비를 넘겨야 한다는 뜻으로 해석되기도 한다. 태어난 아기의 모습이 건강하고 우렁찼는지도 그 일의 앞날을 가늠하는 실마리로 여겨지는 경우가 많다. 이 꿈을 꾼 뒤에는 오래 준비해온 일을 마무리 짓는 데 조금 더 힘을 쏟아보는 계기로 삼기도 한다.', '오래 준비해온 일이 결실을 맺는 조짐', array[3,12,21,29,38,45], 5),
  ((select id from public.dreams where keyword = '아기꿈'), '아기를-잃어버리는-꿈', '아기를 잃어버리는 꿈', '잠깐 눈을 뗀 사이 아기가 사라져 애타게 찾아다니는 꿈이다. 소중한 존재를 놓치는 상황은 현실에서 느끼는 불안감, 특히 무언가를 제대로 챙기지 못하고 있다는 초조함과 연결해 해석되는 경우가 많다. 아기를 결국 찾아냈다면 그 불안이 실제로는 크게 번지지 않고 마무리될 조짐으로 풀이되기도 하고, 끝내 찾지 못한 채 꿈이 끝났다면 여전히 마음에 남은 걱정이 있다는 뜻으로 보기도 한다. 아기를 잃어버린 장소나 상황을 떠올려보면, 최근 소홀히 하고 있던 일이나 관계가 무엇인지 짚어보는 실마리가 되기도 한다. 이 꿈을 꾼 뒤에는 챙기지 못하고 있던 부분을 다시 점검해보는 계기로 삼는 경우도 있다.', '소중한 것을 제대로 챙기지 못한다는 불안의 표현', array[14], 6),
  ((select id from public.dreams where keyword = '아기꿈'), '아기가-말을-하는-꿈', '아기가 말을 하는 꿈', '아직 말을 할 나이가 아닌 아기가 또렷한 목소리로 말을 건네는 꿈이다. 있을 수 없는 일이 벌어지는 만큼 강렬한 인상을 남기는 경우가 많아, 전통적으로 예상치 못한 곳에서 중요한 소식이나 뜻밖의 계시 같은 메시지가 전해진다는 의미로 해석되곤 한다. 아기가 한 말이 구체적으로 기억난다면 그 내용 자체가 지금 고민하고 있는 문제에 대한 힌트로 여겨지는 경우가 많고, 무슨 말인지는 몰라도 말을 했다는 사실만 남았다면 조만간 예상 밖의 소식이 들려올 조짐으로 보기도 한다. 아기의 말투가 다정했는지 단호했는지도 그 메시지를 받아들이는 감정과 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 평소라면 흘려들었을 작은 말 한마디에 조금 더 귀 기울여보는 계기로 삼기도 한다.', '예상치 못한 곳에서 전해지는 중요한 소식이나 힌트', array[9,18,26,35,43], 7),
  ((select id from public.dreams where keyword = '아기꿈'), '쌍둥이-아기를-보는-꿈', '쌍둥이 아기를 보는 꿈', '똑같이 생긴 쌍둥이 아기가 나란히 있는 모습을 보는 꿈이다. 하나가 아니라 둘이 함께 등장하는 장면은 전통적으로 좋은 일이 겹쳐서 찾아오거나, 한 가지 결실이 두 배로 불어나는 상황을 상징하는 꿈으로 보기도 한다. 쌍둥이가 사이좋게 붙어 있었다면 그 겹치는 좋은 일들이 서로 조화를 이루며 찾아올 조짐으로 풀이되는 경우가 많고, 각자 다른 방향을 보고 있었다면 두 가지 일이 별개로 동시에 진행될 수 있다는 뜻으로 해석되기도 한다. 쌍둥이를 구별할 수 있었는지, 헷갈렸는지도 최근 진행 중인 여러 일들을 얼마나 명확히 파악하고 있는지와 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 동시에 진행되는 일들의 우선순위를 다시 정리해보는 계기로 삼기도 한다.', '좋은 일이 겹쳐서 찾아오거나 결실이 배가되는 조짐', array[2,10,24,33,39,45], 8),
  ((select id from public.dreams where keyword = '아기꿈'), '아기를-업는-꿈', '아기를 업는 꿈', '아기를 등에 업고 다독이며 걷는 꿈이다. 업는다는 행위는 안는 것보다 조금 더 오랜 시간 함께하며 책임을 짊어지는 모습과 닮아 있어, 전통적으로 맡은 일이나 사람에 대한 책임감이 깊어지는 상황과 연결해 해석되곤 한다. 아기를 업고 걷는 발걸음이 가벼웠다면 그 책임을 부담 없이 잘 감당하고 있다는 뜻으로 풀이되는 경우가 많고, 힘겹게 걸음을 옮겼다면 지금 맡은 일의 무게가 버겁게 느껴지고 있다는 해석도 있다. 업힌 아기가 편안하게 잠들었는지, 계속 움직이며 보챘는지도 그 책임을 대하는 상대방의 반응과 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 지금 지고 있는 책임의 무게를 한 번 점검해보는 계기로 삼는 경우도 있다.', '맡은 일이나 사람에 대한 책임감이 깊어지는 신호', array[6,17,28,36,44], 9)
on conflict (dream_id, keyword) do nothing;

-- B-3. 귀신꿈 (신규 Parent, category: 인물)
with new_dream_3 as (
  insert into public.dreams (keyword, category, interpretation)
  select '귀신꿈', '인물', '## 귀신꿈은 보통 어떻게 해석할까?
꿈에 등장하는 귀신은 실제로 초자연적인 존재를 의미한다기보다, 마음속에 오래 남아있는 감정이나 아직 정리되지 않은 기억, 현실에서 느끼는 부담감이 형체를 갖추고 나타난 것으로 해석되는 경우가 많다. 무섭게 느껴지는 꿈이라도 그 자체를 불길한 징조로만 볼 필요는 없으며, 귀신을 마주했을 때의 감정과 대응 방식이 오히려 지금 자신의 심리 상태를 보여주는 단서로 쓰이는 경우가 많다. 도망치거나 붙잡히는 상황은 회피하고 싶은 문제와, 대화를 나누거나 쫓아내는 상황은 그 문제를 마주하고 정리하려는 태도와 연결해 해석되곤 한다. 이처럼 귀신꿈은 두려움 자체보다 그 안에 담긴 감정의 결을 살펴보는 것이 중요하다는 해석도 있다.

## 귀신을 마주하는 태도에 따라
가만히 보거나 대화를 나누는 꿈은 감정을 마주하는 과정으로, 쫓기거나 잡히는 꿈은 아직 피하고 싶은 문제가 남아있다는 신호로 풀이되는 경우가 많다. 반대로 귀신을 직접 쫓아내는 꿈은 걱정을 스스로 정리해내는 힘을 상징하기도 한다.

## 등장하는 귀신의 모습에 따라
하얀 소복을 입은 귀신은 오래도록 풀리지 않은 서운함이나 한과, 집 안에 나타나는 귀신은 평온한 일상 속 신경 쓰이는 일과 연결해 해석되곤 한다. 여러 귀신이 한꺼번에 나타나는 꿈은 마음속에 쌓여있는 여러 걱정이 한번에 떠오르는 상황으로 보기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '귀신꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[8,19,25,33,38,44] from new_dream_3;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신을-보는-꿈', '귀신을 보는 꿈', '방 안이나 길 위에서 문득 귀신처럼 보이는 형체와 마주치는 꿈이다. 꿈에서 만나는 귀신은 실제 존재라기보다는 마음속에 오래 남아있는 감정이나 지나간 기억이 형체를 갖추고 나타난 것으로 해석되는 경우가 많다. 귀신이 멀리서 스쳐 지나가기만 했다면 아직 완전히 정리되지 않은 지난 일이 마음 한편에 남아있다는 뜻으로 풀이되기도 하고, 눈이 마주쳤다면 그 감정을 이제는 정면으로 마주할 때가 되었다는 신호로 보기도 한다. 그 형체가 낯익게 느껴졌는지, 전혀 모르는 존재였는지도 어떤 기억이 떠오른 것인지 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 오래 미뤄둔 감정이나 관계를 한 번 돌아보는 계기로 삼는 경우도 있다.', '마음속에 남아있는 지난 감정이나 미해결 기억', array[11], 1),
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신에게-쫓기는-꿈', '귀신에게 쫓기는 꿈', '정체를 알 수 없는 귀신에게 뒤를 쫓기며 정신없이 도망치는 꿈이다. 쫓기는 상황은 대체로 현실에서 느끼는 압박감이나 회피하고 싶은 문제가 꿈속에서 형태를 바꿔 나타난 것으로 해석되는 경우가 많다. 귀신이 바짝 따라붙어 숨 돌릴 틈이 없었다면 그 부담감이 상당히 급박하게 다가와 있다는 뜻으로 풀이되기도 하고, 거리를 두고 쫓아왔다면 아직은 마주하기까지 여유가 조금 남아있다는 해석도 있다. 도망치다 결국 붙잡혔는지, 안전한 곳으로 벗어났는지도 그 문제를 대하는 자신의 대응과 겹쳐 볼 수 있다. 이 꿈을 꾼 뒤에는 미뤄두고 있던 문제를 조금씩 마주해보는 계기로 삼는 경우도 있다.', '현실에서 피하고 싶은 문제나 압박감의 투영', null, 2),
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신과-대화하는-꿈', '귀신과 대화하는 꿈', '귀신처럼 보이는 존재와 놀랍게도 차분히 말을 주고받는 꿈이다. 두려워할 만한 상대와 오히려 대화를 나눈다는 점에서, 이런 꿈은 전통적으로 회피하지 않고 마주해야 할 감정이나 상황을 직접 대면하는 태도와 연결해 해석되곤 한다. 대화의 분위기가 차분하고 자연스러웠다면 마음속 갈등을 정리할 준비가 되어 있다는 뜻으로 풀이되는 경우가 많고, 대화 중에도 긴장감이 가시지 않았다면 아직은 완전히 받아들이지 못한 부분이 남아있다는 해석도 있다. 어떤 이야기를 나눴는지 구체적으로 기억난다면, 그 내용이 지금 마음속 고민과 맞닿아 있을 가능성도 있다. 이 꿈을 꾼 뒤에는 피하고 있던 대화나 감정 정리를 실제로 시도해보는 계기로 삼는 경우도 있다.', '회피하지 않고 마주해야 할 감정이나 상황', array[23,32], 3),
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신이-집에-나타나는-꿈', '귀신이 집에 나타나는 꿈', '익숙한 자기 집 안에 귀신이 불쑥 모습을 드러내는 꿈이다. 집은 심리적으로 안정과 휴식을 뜻하는 공간이어서, 그 안에 낯선 존재가 나타나는 장면은 전통적으로 평온하다고 여겼던 생활 속에 신경 쓰이는 일이 생겨나고 있다는 신호로 해석되곤 한다. 귀신이 특정한 방이나 공간에 자주 나타났다면, 그 공간이 상징하는 생활의 영역에서 마음이 편치 않은 부분이 있다는 뜻으로 풀이되기도 한다. 귀신을 보고도 크게 동요하지 않았다면 그 신경 쓰이는 일을 어느 정도 감당할 여유가 있다는 뜻으로 보기도 하고, 몹시 불안했다면 아직은 대처할 준비가 덜 된 상태로 해석되기도 한다. 이 꿈을 꾼 뒤에는 집안 분위기나 가까운 관계에서 불편한 부분이 없는지 돌아보는 계기로 삼는 경우도 있다.', '평온한 생활 속에 신경 쓰이는 일이 생기는 신호', array[17], 4),
  ((select id from public.dreams where keyword = '귀신꿈'), '하얀-소복을-입은-귀신-꿈', '하얀 소복을 입은 귀신 꿈', '새하얀 소복 차림의 귀신이 조용히 서 있거나 스쳐 지나가는 꿈이다. 소복은 전통적으로 애도와 한을 나타내는 옷차림으로 여겨져, 이런 모습으로 등장하는 귀신은 오래도록 풀리지 않은 서운함이나 억눌린 감정을 상징하는 꿈으로 보기도 한다. 소복 입은 귀신이 아무 말 없이 가만히 서 있었다면 아직 표현되지 못한 감정이 마음속에 머물러 있다는 뜻으로 풀이되는 경우가 많고, 무언가 몸짓을 하거나 다가왔다면 그 감정이 이제는 드러나고 싶어 한다는 해석도 있다. 흰옷이 유독 깨끗하고 단정하게 느껴졌는지, 낡고 해져 보였는지도 그 감정이 얼마나 오래되었는지를 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 마음 한편에 눌러두었던 감정을 조금씩 꺼내보는 계기로 삼는 경우도 있다.', '오래도록 풀리지 않은 서운함이나 억눌린 감정', null, 5),
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신을-쫓아내는-꿈', '귀신을 쫓아내는 꿈', '집이나 방 안에 있던 귀신을 향해 소리치거나 힘을 다해 밖으로 몰아내는 꿈이다. 위협적인 존재를 스스로의 힘으로 물리친다는 점에서, 이런 꿈은 전통적으로 마음을 짓누르던 걱정이나 불편한 상황을 스스로 정리해내는 힘과 연결해 해석되곤 한다. 귀신이 순순히 물러갔다면 그 문제가 생각보다 수월하게 정리될 조짐으로 풀이되는 경우가 많고, 끝까지 버티며 저항했다면 조금 더 시간과 노력이 필요한 상황으로 보기도 한다. 쫓아내는 과정에서 사용한 방법이 기억난다면, 그 방식이 현실에서 문제를 해결하는 자신의 접근과 닮아 있는지 견주어볼 만하다. 이 꿈을 꾼 뒤에는 미뤄뒀던 문제를 직접 정리하려는 행동으로 옮겨보는 계기로 삼는 경우도 있다.', '마음을 짓누르던 걱정을 스스로 정리해내는 힘', array[9,20,31,42], 6),
  ((select id from public.dreams where keyword = '귀신꿈'), '여러-귀신을-보는-꿈', '여러 귀신을 보는 꿈', '한둘이 아니라 여러 귀신이 동시에 눈앞에 나타나는 꿈이다. 하나가 아니라 여럿이 한꺼번에 등장하는 장면은 대체로 마음속에 쌓여있는 여러 걱정이나 미뤄둔 일들이 한꺼번에 떠오르는 상황과 연결해 해석되는 경우가 많다. 귀신들이 각자 흩어져 있었다면 그 걱정거리들이 아직은 서로 얽히지 않은 채 개별적으로 남아있다는 뜻으로 풀이되기도 하고, 한데 모여 있었다면 여러 문제가 서로 맞물려 있다는 해석도 있다. 그 수가 유독 많게 느껴졌다면 최근 감당하고 있는 일의 양이 많다는 신호로 받아들여지는 경우도 있다. 이 꿈을 꾼 뒤에는 쌓여있는 걱정거리들을 하나씩 목록으로 정리해보는 계기로 삼기도 한다.', '마음속에 쌓여있는 여러 걱정이나 미뤄둔 일들', array[26], 7),
  ((select id from public.dreams where keyword = '귀신꿈'), '귀신에게-잡히는-꿈', '귀신에게 잡히는 꿈', '도망치다 결국 귀신에게 손목이나 어깨를 붙잡히는 꿈이다. 피하려던 대상에게 붙잡히는 상황은 전통적으로 계속 미뤄왔던 문제를 더는 피할 수 없게 되었다는 신호로 해석되는 경우가 많다. 붙잡힌 순간 극심한 공포를 느꼈다면 그 문제를 마주하는 일이 상당히 부담스럽게 느껴지고 있다는 뜻으로 풀이되기도 하고, 붙잡히고도 의외로 담담했다면 이미 어느 정도 받아들일 준비가 되어 있다는 해석도 있다. 붙잡힌 뒤에 꿈이 어떻게 이어졌는지, 그대로 끝났는지 벗어날 방법을 찾았는지도 앞으로의 전개를 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 더는 미룰 수 없는 문제를 목록의 맨 앞으로 옮겨보는 계기로 삼는 경우도 있다.', '계속 미뤄온 문제를 더는 피할 수 없다는 신호', array[30], 8),
  ((select id from public.dreams where keyword = '귀신꿈'), '무서운-귀신을-피해-도망치는-꿈', '무서운 귀신을 피해 도망치는 꿈', '험상궂은 귀신을 피해 있는 힘껏 도망치는 꿈이다. 극심한 공포 속에서 도망치는 장면은 대체로 현실에서 느끼는 큰 스트레스나 감당하기 벅찬 압박감이 꿈속에서 과장되어 나타난 것으로 해석되는 경우가 많다. 도망친 끝에 안전한 곳을 찾았다면 지금의 부담이 결국은 해소될 조짐으로 풀이되기도 하고, 도망치는 도중 꿈이 끝나버렸다면 아직 그 문제에서 완전히 벗어나지 못했다는 뜻으로 보기도 한다. 도망치는 동안 주변 풍경이나 함께 있던 사람이 기억난다면, 그 상황이 현실의 어떤 부담과 닮아 있는지 짚어보는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 쌓여있는 스트레스를 풀어낼 나름의 방법을 찾아보는 계기로 삼는 경우도 있다.', '감당하기 벅찬 스트레스나 압박감의 과장된 표현', null, 9)
on conflict (dream_id, keyword) do nothing;

-- B-4. 자동차꿈 (신규 Parent, category: 교통)
with new_dream_4 as (
  insert into public.dreams (keyword, category, interpretation)
  select '자동차꿈', '교통', '## 자동차꿈은 보통 어떻게 해석할까?
자동차는 살아가는 방향이나 앞으로 나아가는 힘, 그리고 그 흐름을 스스로 얼마나 통제하고 있는지를 보여주는 상징으로 여겨지는 경우가 많다. 차의 상태가 좋고 순조롭게 나아갔다면 지금의 흐름이 원하는 방향으로 잘 진행되고 있다는 뜻으로, 사고가 나거나 고장이 나는 등 문제가 생겼다면 그 흐름에 변수나 걸림돌이 생기고 있다는 뜻으로 풀이되는 경우가 많다. 누가 운전대를 잡고 있었는지도 중요한 해석의 기준이 되는데, 스스로 운전했다면 주도권을 쥔 상황을, 남이 운전했다면 상황을 다른 사람에게 맡긴 상태를 나타내곤 한다. 이처럼 자동차꿈은 지금 자신이 가고 있는 방향과 그 방향을 얼마나 통제하고 있는지를 함께 살펴보게 하는 꿈으로 받아들여지기도 한다.

## 사고나 문제가 생기는 상황
사고, 고장, 브레이크가 듣지 않는 상황은 모두 진행 중인 일에 변수가 생기거나 통제력을 잃는 느낌과 연결해 해석되는 경우가 많다. 차를 도둑맞는 꿈 역시 가진 것을 지키지 못할 수 있다는 불안과 맞닿아 있다.

## 새로운 차나 동승 상황에 따라
새 차를 사거나 고급차를 타는 꿈은 생활에 활력이 더해지거나 주변의 인정을 받는 조짐으로 풀이되는 경우가 많다. 남이 운전하는 차를 타는 꿈은 주도권을 맡긴 상황을, 차가 물에 빠지는 꿈은 억눌러온 감정이 한꺼번에 밀려오는 상태를 나타내기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '자동차꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[6,14,23,31,39,45] from new_dream_4;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '자동차꿈'), '새-차를-사는-꿈', '새 차를 사는 꿈', '오랫동안 눈여겨보던 새 차를 마침내 계약하고 손에 넣는 꿈이다. 자동차는 살아가는 방향이나 앞으로 나아가는 힘을 상징하는 경우가 많아, 새 차를 마련하는 장면은 전통적으로 생활에 새로운 활력이 더해지거나 상황을 바꿀 좋은 기회가 다가온다는 의미로 해석되곤 한다. 원하던 차종이나 색상을 마음에 쏙 들게 골랐다면 그 변화가 자신이 바라던 방향과 잘 맞아떨어질 조짐으로 풀이되는 경우가 많고, 얼떨결에 차를 받게 되었다면 예상치 못한 곳에서 기회가 찾아올 수 있다는 해석도 있다. 계약서에 서명하거나 열쇠를 건네받는 순간의 감정이 설렘에 가까웠다면 그만큼 지금의 변화를 반기고 있다는 뜻으로 볼 수 있다. 이 꿈을 꾼 뒤에는 미뤄뒀던 새로운 시도를 실제로 계획해보는 계기로 삼는 경우도 있다.', '생활에 새로운 활력이나 기회가 더해지는 조짐', array[5,14,23,32,41,45], 1),
  ((select id from public.dreams where keyword = '자동차꿈'), '자동차-사고가-나는-꿈', '자동차 사고가 나는 꿈', '운전 중 예상치 못하게 다른 차와 부딪히거나 충돌하는 꿈이다. 사고는 순식간에 계획이 흐트러지는 상황이라는 점에서, 전통적으로 진행 중인 일이 갑작스러운 변수로 어긋나거나 늦춰질 수 있다는 신호로 해석되는 경우가 많다. 사고의 충격이 크고 심각했다면 그만큼 계획에 생길 변수도 만만치 않을 수 있다는 뜻으로 풀이되기도 하고, 가벼운 접촉 정도로 끝났다면 사소한 차질에 그칠 조짐으로 보기도 한다. 사고의 원인이 자신의 실수였는지, 상대방으로 인한 것이었는지도 그 변수가 어디서 비롯될지를 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 진행 중인 일의 진행 속도나 안전장치를 한 번 더 점검해보는 계기로 삼는 경우도 있다.', '진행 중인 일이 갑작스러운 변수로 어긋날 신호', array[18], 2),
  ((select id from public.dreams where keyword = '자동차꿈'), '운전하다-브레이크가-안-듣는-꿈', '운전하다 브레이크가 안 듣는 꿈', '속도를 줄이려 브레이크를 밟았지만 아무런 반응이 없어 당황하는 꿈이다. 멈추고 싶어도 멈출 수 없는 상황은 대체로 현실에서 어떤 흐름이나 결정을 자기 뜻대로 조절하지 못하고 있다는 무력감과 연결해 해석되는 경우가 많다. 브레이크가 전혀 듣지 않아 계속 속도가 붙었다면 그만큼 지금 상황이 통제 밖으로 벗어나고 있다는 느낌이 크다는 뜻으로 풀이되기도 하고, 애를 쓴 끝에 조금씩 속도가 줄었다면 아직은 상황을 되돌릴 여지가 남아있다는 해석도 있다. 그 순간 느낀 공포와 무력감이 유독 생생했다면, 최근 스스로 결정권을 잃었다고 느끼는 일이 있었는지 돌아볼 만하다. 이 꿈을 꾼 뒤에는 자신이 통제할 수 있는 부분과 그렇지 못한 부분을 나눠보는 계기로 삼는 경우도 있다.', '상황이나 결정을 자기 뜻대로 조절하지 못하는 무력감', null, 3),
  ((select id from public.dreams where keyword = '자동차꿈'), '자동차가-고장나는-꿈', '자동차가 고장나는 꿈', '잘 달리던 차가 갑자기 멈춰 서거나 시동이 걸리지 않는 꿈이다. 나아가던 흐름이 뜻하지 않게 멈추는 상황은 전통적으로 순조롭게 진행되던 일이 잠시 지체되거나 예상치 못한 걸림돌을 만나는 신호로 해석되곤 한다. 고장의 원인을 금방 찾아 해결했다면 그 지체가 오래가지 않을 조짐으로 풀이되는 경우가 많고, 원인을 알 수 없어 발만 동동 굴렀다면 조금 더 시간을 들여 문제를 파악해야 하는 상황으로 보기도 한다. 고장이 난 장소가 목적지 근처였는지, 한참 남은 길목이었는지도 그 지연이 일에 얼마나 영향을 줄지 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 진행 중인 계획에 예비 대안을 마련해두는 계기로 삼는 경우도 있다.', '순조롭던 일이 잠시 지체되거나 걸림돌을 만나는 신호', array[21,36], 4),
  ((select id from public.dreams where keyword = '자동차꿈'), '남이-운전하는-차를-타는-꿈', '남이 운전하는 차를 타는 꿈', '운전대를 직접 잡지 않고 다른 사람이 모는 차의 조수석이나 뒷자리에 앉아 있는 꿈이다. 방향을 스스로 정하지 않고 남에게 맡긴다는 점에서, 이런 꿈은 전통적으로 지금 진행되는 일의 주도권을 다른 사람에게 맡기고 있는 상황과 연결해 해석되는 경우가 많다. 운전하는 사람이 믿음직스럽고 능숙했다면 그 상황을 편안하게 받아들이고 있다는 뜻으로 풀이되기도 하고, 불안하게 운전했다면 주도권을 넘긴 것에 대한 불안감이 남아있다는 해석도 있다. 그 운전자가 누구였는지, 얼마나 친밀한 사이였는지도 지금 어떤 관계나 상황에 의지하고 있는지를 보여주는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 맡겨둔 일에 얼마나 마음을 놓고 있는지 스스로에게 물어보는 계기로 삼는 경우도 있다.', '진행 중인 일의 주도권을 다른 사람에게 맡긴 상황', array[10,27,39], 5),
  ((select id from public.dreams where keyword = '자동차꿈'), '차를-도둑맞는-꿈', '차를 도둑맞는 꿈', '잠깐 자리를 비운 사이 세워둔 차가 감쪽같이 사라진 꿈이다. 소중하게 여기던 것을 순식간에 잃어버리는 상황은 대체로 지금 가진 것을 지키지 못할 수도 있다는 불안감이나, 이미 손에서 벗어난 기회에 대한 아쉬움과 연결해 해석되는 경우가 많다. 차를 잃어버린 사실을 알고도 크게 동요하지 않았다면 그 상실감이 실제로는 크지 않을 것이라는 뜻으로 풀이되기도 하고, 애타게 찾아다녔다면 그만큼 소중하게 여기던 무언가에 대한 미련이 남아있다는 해석도 있다. 차를 세워둔 장소나 상황이 얼마나 부주의했는지도 최근 소홀히 하고 있던 부분을 돌아보는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 지금 가진 것을 관리하는 방식을 한 번 점검해보는 계기로 삼는 경우도 있다.', '가진 것을 지키지 못할 수 있다는 불안이나 아쉬움', array[15], 6),
  ((select id from public.dreams where keyword = '자동차꿈'), '고급차를-타는-꿈', '고급차를 타는 꿈', '평소 타던 것과는 다른 화려하고 값비싼 고급차에 올라타는 꿈이다. 남다른 대우와 격을 갖춘 자리에 앉는 장면은 전통적으로 주변으로부터 인정받거나 위상이 높아지는 상황과 연결해 해석되곤 한다. 고급차 안에서 편안하고 여유롭게 있었다면 그 인정받는 상황을 자연스럽게 받아들이고 있다는 뜻으로 풀이되는 경우가 많고, 어색하고 불편하게 느껴졌다면 아직은 그 자리가 낯설게 느껴지고 있다는 해석도 있다. 직접 운전을 했는지, 누군가 태워준 것이었는지도 그 위상이 스스로 이룬 것인지 주어진 것인지를 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 그동안의 노력을 인정받을 기회를 적극적으로 찾아보는 계기로 삼는 경우도 있다.', '주변으로부터 인정받거나 위상이 높아지는 조짐', array[6,19,28,35,42,45], 7),
  ((select id from public.dreams where keyword = '자동차꿈'), '차가-물에-빠지는-꿈', '차가 물에 빠지는 꿈', '운전하던 차가 갑자기 강이나 바다로 미끄러져 들어가 가라앉는 꿈이다. 물은 대체로 감정을 상징하는 경우가 많아, 차가 물에 빠지는 장면은 전통적으로 지금까지 애써 통제해온 감정이 한꺼번에 밀려와 감당하기 벅찬 상태에 놓였다는 신호로 해석되곤 한다. 차 안에 물이 서서히 차올랐다면 그 감정이 조금씩 쌓여가고 있다는 뜻으로 풀이되기도 하고, 순식간에 잠겨버렸다면 이미 감정이 걷잡을 수 없이 몰아친 상태로 보기도 한다. 차 밖으로 무사히 빠져나왔는지, 갇혀 있었는지도 지금 그 감정 상태에서 벗어날 여지가 있는지를 가늠하는 실마리가 될 수 있다. 이 꿈을 꾼 뒤에는 눌러왔던 감정을 안전한 방식으로 풀어낼 방법을 찾아보는 계기로 삼는 경우도 있다.', '억눌러온 감정이 한꺼번에 밀려와 벅찬 상태의 신호', null, 8)
on conflict (dream_id, keyword) do nothing;

-- B-5. 새꿈 (신규 Parent, category: 동물)
with new_dream_5 as (
  insert into public.dreams (keyword, category, interpretation)
  select '새꿈', '동물', '## 새꿈은 보통 어떻게 해석할까?
새는 하늘과 땅을 자유롭게 오가는 존재로, 전통적으로 소식과 인연을 실어 나르는 전령으로 여겨지곤 한다. 그래서 새가 등장하는 꿈은 대체로 새로운 정보나 반가운 만남, 혹은 눈앞의 기회와 관련지어 해석되는 경우가 많다. 다만 같은 새라 해도 다가오는지 떠나가는지, 온전한 모습인지 다친 모습인지에 따라 풀이의 결이 크게 달라진다는 점이 특징이다. 즉 새 자체보다는 새와 내가 어떤 관계를 맺고 있는지를 살펴보는 것이 해몽의 핵심이라고 할 수 있다.

## 새가 다가오거나 날아갈 때
새가 집 안으로 스스럼없이 들어오거나 무리 지어 나타났다면 좋은 소식과 기회가 풍성하게 찾아드는 흐름으로 풀이되곤 한다. 반대로 새가 손을 떠나 하늘 저편으로 날아가버렸다면 묶여 있던 상황에서 벗어나거나, 때로는 스쳐 지나가는 인연에 대한 아쉬움을 나타낸다는 해석도 있다.

## 다치거나 사라지는 새를 볼 때
새를 붙잡아 손에 넣었다면 노력한 만큼의 성과를 거둔다는 의미로, 다치거나 생을 다한 새를 보았다면 걱정거리나 마무리되어가는 국면을 상징한다는 이야기로 이어지곤 한다. 어느 경우든 새의 상태와 그때 느낀 감정을 함께 떠올려보면 해몽의 실마리를 찾기 좋다.'
  where not exists (select 1 from public.dreams where keyword = '새꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,11,18,24,32,41] from new_dream_5;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '새꿈'), '새가-집으로-들어오는-꿈', '새가 집으로 들어오는 꿈', '집 안으로 새 한 마리가 스스럼없이 날아들어오는 꿈이다. 예로부터 새가 집 안으로 들어오는 장면은 반가운 소식이나 귀한 손님이 찾아온다는 의미로 해석되곤 한다. 특히 창문이나 문을 통해 자연스럽게 들어왔다면 막혀 있던 기회가 스스로 열리는 흐름으로 풀이되기도 한다. 새가 어디에 자리를 잡고 앉는지도 눈여겨볼 만한데, 안방이나 거실처럼 중심이 되는 공간에 앉았다면 그만큼 의미 있는 소식일 가능성이 높다고 보는 시각도 있다. 반대로 새가 놀라서 이리저리 부딪히며 어수선하게 날아다녔다면 소식이 오긴 하되 다소 정신없이 전해질 수 있다는 해석도 있다. 대체로 새가 집에 들어오는 꿈은 문이 열려 있다는 느낌, 즉 새로운 기회에 마음을 열어두라는 신호로 받아들여지곤 한다.', '반가운 소식이나 인연이 찾아드는 신호로 해석', array[7,14,22,33,40], 1),
  ((select id from public.dreams where keyword = '새꿈'), '새를-잡는-꿈', '새를 잡는 꿈', '날아다니는 새를 손으로 직접 붙잡는 꿈이다. 새를 잡는다는 것은 눈앞을 스쳐가는 기회나 정보를 놓치지 않고 확보한다는 의미로 해석되곤 한다. 특히 새를 쫓아가서 애쓴 끝에 붙잡았다면, 그만큼 노력을 들여야 손에 넣을 수 있는 성과를 뜻하는 것으로 풀이되기도 한다. 반면 큰 힘을 들이지 않고 손쉽게 새를 잡았다면 뜻밖에 굴러들어오는 행운을 암시한다는 이야기도 있다. 손안에 쥔 새가 파닥거리며 빠져나가려 했는지, 아니면 얌전히 안겨 있었는지에 따라서도 해석이 갈리는데, 계속 빠져나가려 했다면 손에 넣은 것을 지키는 데 신경을 써야 한다는 의미로도 읽힌다. 새를 잡은 뒤 새장에 넣거나 품에 안았다면 그 성과를 안정적으로 지켜냈다는 뜻으로 보는 경우가 많다.', '노력 끝에 기회를 손에 넣는 성취를 암시', array[2,9,17,26,38], 2),
  ((select id from public.dreams where keyword = '새꿈'), '새가-날아가는-꿈', '새가 날아가는 꿈', '하늘 높이 새가 날아올라 멀리 사라져가는 꿈이다. 새가 훨훨 날아가는 모습은 답답했던 상황에서 벗어나 자유로워지는 흐름으로 해석되는 경우가 많다. 무언가에 얽매여 있던 마음이 새를 따라 함께 풀려나가는 듯한 느낌을 받았다면, 실제로도 걱정거리가 하나씩 정리되어가는 시기일 수 있다는 해석도 있다. 다만 아끼던 새나 곁에 두고 싶었던 새가 뒤도 안 돌아보고 날아가버렸다면, 소중한 기회나 인연이 스쳐 지나가는 아쉬움을 나타낸다고 보기도 한다. 새가 날아가는 방향이 밝고 탁 트인 하늘 쪽이었는지, 아니면 어두운 쪽으로 사라졌는지에 따라서도 느낌이 달라지는데, 밝은 쪽이라면 새로운 시작을, 어두운 쪽이라면 잠시 거리를 두어야 할 일을 뜻한다는 이야기도 있다. 새가 날아간 자리를 오래도록 바라보았다면 그만큼 그 흐름에 미련이 남아 있다는 신호로 읽히기도 한다.', '얽매임에서 벗어나거나 인연이 스쳐가는 흐름', array[5,19,29], 3),
  ((select id from public.dreams where keyword = '새꿈'), '다친-새를-보는-꿈', '다친 새를 보는 꿈', '날개나 몸에 상처를 입은 새를 발견하는 꿈이다. 다친 새를 보는 장면은 주변의 누군가, 혹은 나 자신의 건강이나 상황에 대한 걱정을 반영한다는 해석이 있다. 날개를 다쳐 제대로 날지 못하는 새를 보았다면 하려던 일이 뜻대로 진행되지 않아 답답함을 느끼는 심리가 투영된 것으로 풀이되기도 한다. 다친 새를 그냥 지나치지 못하고 데려와 돌보아주었다면, 힘든 상황 속에서도 누군가를 돕거나 스스로를 추스르려는 마음가짐을 나타낸다는 이야기도 있다. 반대로 다친 새를 보고도 손쓰지 못한 채 안타까워만 했다면, 마음은 있어도 당장 해결할 방법이 없는 답답한 처지를 상징한다고 보기도 한다. 다친 새가 시간이 지나 회복하는 모습까지 이어졌다면 지금의 어려움도 차차 나아질 것이라는 위안으로 받아들여지기도 한다.', '건강이나 상황에 대한 걱정이 투영된 장면', array[12,27], 4),
  ((select id from public.dreams where keyword = '새꿈'), '새가-죽는-꿈', '새가 죽는 꿈', '지저귀던 새가 눈앞에서 숨을 거두는 꿈이다. 꿈속에서 동물이 죽는 장면은 불길하게 느껴지기 쉽지만, 전통적인 해몽에서는 오히려 묵은 상황이 끝나고 새로운 국면으로 넘어간다는 의미로 풀이되는 경우가 많다. 다만 꿈을 꾼 직후의 감정이 놀람이나 슬픔으로 강하게 남았다면, 그만큼 마음속에 정리하지 못한 걱정이 자리 잡고 있다는 신호로 볼 수도 있다. 새가 어떤 이유로 죽었는지도 해석에 영향을 주는데, 자연스럽게 생을 다한 모습이었다면 순리대로 마무리되는 일을, 갑작스러운 사고나 다른 존재에 의해 죽었다면 외부 요인으로 인한 변화를 뜻한다는 이야기도 있다. 죽은 새를 정성껏 묻어주었다면 지난 일을 잘 매듭짓고 다음 단계로 넘어가려는 마음가짐을 나타낸다고 풀이되기도 한다. 이 꿈을 꾸었다고 해서 실제로 나쁜 일이 벌어진다고 단정할 필요는 없으며, 마음속 변화의 흐름 정도로 가볍게 받아들이는 편이 좋다.', '묵은 상황이 끝나고 새 국면으로 넘어감을 암시', null, 5),
  ((select id from public.dreams where keyword = '새꿈'), '여러-마리-새떼를-보는-꿈', '여러 마리 새떼를 보는 꿈', '하늘을 가득 메운 새떼가 무리 지어 날아가는 꿈이다. 새가 떼를 지어 나타나는 모습은 한꺼번에 여러 소식이나 기회가 몰려드는 풍성한 흐름으로 해석되곤 한다. 새떼가 질서 있게 대형을 이루며 날아갔다면 여러 일이 순차적으로, 그리고 순조롭게 풀려나갈 것이라는 신호로 받아들여지기도 한다. 반대로 새떼가 사방으로 흩어지며 어지럽게 날았다면 여러 갈래의 일들이 한꺼번에 몰려와 정신없이 느껴질 수 있다는 해석도 있다. 새떼가 내 머리 위를 지나가며 그늘을 드리웠다면 주변 사람들의 관심이나 도움이 함께한다는 의미로 풀이되는 경우도 있다. 넓은 하늘을 가득 채운 새떼를 올려다보며 벅찬 기분을 느꼈다면, 그만큼 마음의 여유와 풍요로움이 채워지는 시기라는 뜻으로도 읽힌다.', '여러 소식과 기회가 한꺼번에 몰려드는 흐름', array[4,13,21,30,36,44], 6)
on conflict (dream_id, keyword) do nothing;

-- B-6. 거미꿈 (신규 Parent, category: 동물)
with new_dream_6 as (
  insert into public.dreams (keyword, category, interpretation)
  select '거미꿈', '동물', '## 거미꿈은 보통 어떻게 해석할까?
거미는 부지런히 집을 짓고 먹이를 거둬들이는 습성 때문에 전통적으로 재물운이나 성취와 연결지어 해석되는 동물이다. 특히 저녁에 거미를 보면 좋은 일이 생긴다는 옛말이 있을 만큼, 거미꿈 전반은 나쁘게만 보지 않는 경우가 많다. 다만 거미가 어떤 크기와 모습으로 나타났는지, 나와 어떻게 부딪혔는지에 따라 해석의 무게가 달라진다는 점은 유의할 만하다. 조용히 자리를 지키는 거미와 몸에 달라붙거나 물어오는 거미는 전해주는 메시지의 결이 사뭇 다르다.

## 거미와 거미줄을 마주할 때
가만히 있는 거미를 보거나 정교한 거미줄을 발견했다면 차근차근 쌓아온 계획과 재물운이 무르익어가는 흐름으로 풀이되곤 한다. 거미의 크기가 클수록 그 성취의 규모도 크게 해석되는 경향이 있다.

## 물리거나 몸에 닿을 때
거미에게 물리거나 몸에 달라붙는 경험은 걱정거리나 부담이 가까이 다가와 있다는 신호로, 거미를 직접 없애는 행동은 그런 문제를 스스로 정리하려는 마음가짐으로 해석되기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '거미꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[5,12,19,26,33,40] from new_dream_6;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '거미꿈'), '거미를-보는-꿈', '거미를 보는 꿈', '방 안이나 벽 한켠에서 거미 한 마리를 발견하는 꿈이다. 전통 해몽에서 거미는 부지런히 집을 짓고 무언가를 거둬들이는 습성 때문에 재물운이나 성취와 연결지어 해석되는 경우가 많다. 거미가 조용히 자기 자리를 지키고 있었다면 지금 하고 있는 일이 차근차근 결실을 맺어가고 있다는 신호로 받아들여지기도 한다. 거미를 보고 놀라거나 징그럽다는 느낌이 강하게 들었다면, 그 감정 자체가 최근 신경 쓰이는 문제에 대한 반응일 수 있다는 해석도 있다. 거미가 나타난 장소가 집 안인지 낯선 곳인지에 따라서도 뜻이 갈리는데, 익숙한 공간에서 보았다면 가까운 곳에서 성과가 찾아온다는 의미로 풀이되는 경우가 있다. 거미를 오래도록 지켜보며 관찰했다면 그만큼 다가오는 기회를 신중하게 살피고 있는 상태라는 뜻으로도 읽힌다.', '부지런한 성취나 재물운과 연결짓는 해석', array[6,15,23,31,39], 1),
  ((select id from public.dreams where keyword = '거미꿈'), '거미에게-물리는-꿈', '거미에게 물리는 꿈', '거미가 갑자기 팔이나 다리를 물어 놀라는 꿈이다. 거미에게 물리는 순간은 예상치 못한 곳에서 작은 문제나 구설이 불거질 수 있다는 걱정을 반영한다는 해석이 있다. 물린 자리가 따끔하고 아팠다면 그 문제가 당장은 신경 쓰이지만 크게 번지지는 않을 자잘한 일일 가능성으로 풀이되기도 한다. 반대로 물린 자리가 부어오르거나 오래 아팠다면, 마음에 걸리는 일을 서둘러 처리하지 않고 미뤄두고 있다는 신호로 볼 수도 있다는 이야기가 있다. 누구에게, 어떤 상황에서 물렸는지를 떠올려보면 그 걱정의 정체를 짐작하는 데 도움이 된다고 보기도 한다. 물린 뒤에 상처를 소독하거나 치료하는 장면까지 이어졌다면 문제를 스스로 잘 수습해나가는 모습으로 해석되기도 한다.', '예기치 못한 구설이나 자잘한 걱정거리를 암시', array[16,34], 2),
  ((select id from public.dreams where keyword = '거미꿈'), '거미줄을-보는-꿈', '거미줄을 보는 꿈', '정교하게 짜인 거미줄을 마주하는 꿈이다. 거미줄은 촘촘하게 이어진 그물 모양 때문에 계획이나 인간관계가 하나씩 얽히고 짜여가는 과정을 상징한다고 보는 해석이 있다. 이슬이 맺혀 반짝이는 거미줄을 보았다면 공들여 준비해온 일이 마침내 빛을 보는 시기라는 뜻으로 풀이되기도 한다. 거미줄이 여러 겹으로 넓게 펼쳐져 있었다면 그만큼 폭넓은 인맥이나 다방면의 준비가 잘 갖춰져 있다는 신호로 읽는 경우도 있다. 반대로 거미줄이 낡고 먼지 쌓인 모습이었다면 오래 방치해둔 계획이나 관계를 다시 손봐야 한다는 의미로 해석되기도 한다. 거미줄에 걸려 있는 벌레를 함께 보았다면 그 계획이 실제로 무언가를 거둬들이는 단계에 들어섰다는 뜻으로 보기도 한다.', '차근차근 짜여가는 계획이나 인맥을 상징', array[8,20,28,42], 3),
  ((select id from public.dreams where keyword = '거미꿈'), '거미를-죽이는-꿈', '거미를 죽이는 꿈', '눈앞에 나타난 거미를 손이나 물건으로 내리쳐 죽이는 꿈이다. 거미를 죽이는 행동은 거슬리던 걱정거리나 성가신 일을 스스로 정리하려는 마음이 반영된 것으로 해석되곤 한다. 단번에 시원하게 처리했다면 마음속에 쌓여 있던 불편함을 실제로도 후련하게 털어낼 수 있다는 신호로 풀이되기도 한다. 다만 거미를 죽인 뒤에도 찜찜한 기분이 남았다면, 눈앞의 문제는 해결했어도 근본적인 걱정은 아직 남아 있다는 뜻으로 보는 시각도 있다. 거미를 죽이는 데 애를 먹고 여러 번 시도했다면, 정리하려는 일이 생각보다 손이 많이 가는 상황임을 암시한다는 이야기도 있다. 거미를 죽인 자리를 깨끗이 치우는 데까지 이어졌다면 문제를 완전히 마무리 짓고 넘어가려는 태도로 해석되기도 한다.', '성가신 걱정거리를 스스로 정리하려는 마음', array[10,25], 4),
  ((select id from public.dreams where keyword = '거미꿈'), '큰-거미를-보는-꿈', '큰 거미를 보는 꿈', '보통 크기를 훌쩍 넘어서는 커다란 거미와 마주하는 꿈이다. 거미의 크기가 클수록 그것이 상징하는 재물운이나 성취의 규모도 그만큼 크게 해석되는 경우가 많다. 거대한 거미를 보고 위압감보다는 신기함이나 놀라움을 느꼈다면, 예상보다 큰 기회나 성과가 찾아올 수 있다는 뜻으로 풀이되기도 한다. 반대로 그 크기에 두려움을 느껴 피하거나 도망쳤다면, 감당하기 버거울 만큼 큰 부담감이 마음 한편에 자리하고 있다는 해석도 있다. 큰 거미가 유유히 자기 갈 길을 갔는지, 아니면 나를 향해 다가왔는지에 따라서도 뜻이 갈리는데, 다가오는 모습이었다면 조만간 큰 변화가 내 삶에 직접적으로 영향을 줄 수 있다는 신호로 보기도 한다. 큰 거미를 무사히 지나쳐 보냈다면 큰 흐름을 스스로 잘 감당해낼 수 있다는 뜻으로 받아들여지기도 한다.', '규모가 큰 재물운이나 성취 가능성을 암시', array[1,14,27,45], 5),
  ((select id from public.dreams where keyword = '거미꿈'), '거미가-몸에-붙는-꿈', '거미가 몸에 붙는 꿈', '거미가 스멀스멀 기어와 몸이나 옷에 달라붙는 꿈이다. 거미가 몸에 붙는 느낌은 어떤 기회나 문제가 이미 내 곁에 바짝 다가와 있다는 의미로 해석되곤 한다. 놀라지 않고 거미를 가만히 떼어냈다면 눈앞의 상황을 침착하게 다룰 수 있는 여유가 있다는 신호로 풀이되기도 한다. 반대로 소스라치게 놀라 몸을 털어내려 했다면, 갑작스럽게 떠맡게 된 일이나 부담감에 당황스러운 마음이 반영된 것이라는 해석도 있다. 거미가 붙은 위치도 살펴볼 만한데, 손이나 팔처럼 눈에 잘 띄는 곳이었다면 곧 드러나게 될 일을, 등처럼 보이지 않는 곳이었다면 아직 인지하지 못한 문제를 뜻한다는 이야기도 있다. 거미를 떼어낸 뒤 별다른 자국이 남지 않았다면 그 일이 큰 탈 없이 지나갈 것이라는 뜻으로 받아들여지기도 한다.', '기회나 문제가 바짝 다가와 있음을 암시', array[19,37], 6)
on conflict (dream_id, keyword) do nothing;

-- B-7. 말꿈 (신규 Parent, category: 동물)
with new_dream_7 as (
  insert into public.dreams (keyword, category, interpretation)
  select '말꿈', '동물', '## 말꿈은 보통 어떻게 해석할까?
말은 힘차게 내달리는 특유의 기세 때문에 전통적으로 성취, 명예, 사회적 진전을 상징하는 동물로 해석되곤 한다. 말꿈은 대체로 좋은 흐름으로 풀이되는 경우가 많지만, 말을 타고 있는지, 말이 어떻게 움직이는지에 따라 그 의미의 결이 조금씩 달라진다. 특히 말과 내가 얼마나 안정적으로 호흡을 맞추고 있는지가 해석의 중요한 기준이 되곤 한다.

## 말을 타고 달릴 때
말에 올라타 뜻대로 나아가거나 힘차게 내달리는 모습은 목표를 향한 추진력과 순조로운 진행을 뜻하는 경우가 많다. 백마처럼 특별한 빛깔의 말을 만났다면 그만큼 귀한 인연이나 명예로운 기회로 풀이되기도 한다.

## 균형을 잃거나 새로 시작할 때
말에서 떨어지는 꿈은 순조롭던 흐름이 잠시 흔들릴 수 있다는 걱정을, 망아지를 보는 꿈은 이제 막 시작하는 일의 성장 가능성을 암시한다는 해석으로 이어지곤 한다.'
  where not exists (select 1 from public.dreams where keyword = '말꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[7,16,22,29,35,44] from new_dream_7;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '말꿈'), '말을-타는-꿈', '말을 타는 꿈', '씩씩한 말 등에 올라타 고삐를 잡는 꿈이다. 말을 탄다는 것은 목표를 향해 힘 있게 나아가는 추진력이나 사회적 성취를 상징한다고 해석되는 경우가 많다. 말이 내 의지대로 순순히 움직여주었다면 지금 추진하는 일이 계획한 방향대로 잘 풀려나가고 있다는 신호로 받아들여지기도 한다. 반대로 말이 자꾸 엇나가거나 고삐를 다루기 힘들었다면, 의욕은 있지만 아직 상황을 완전히 장악하지는 못한 상태라는 뜻으로 풀이되기도 한다. 말 위에 올라탔을 때의 높이감과 시야가 탁 트여 시원했다면 그만큼 앞으로의 전망이 밝다는 의미로 보는 시각도 있다. 말을 타고 어디로 향했는지도 함께 떠올려보면, 그 방향이 곧 지금 마음이 향하고 있는 목표와 맞닿아 있다는 해석으로 이어지기도 한다.', '목표를 향한 추진력과 성취를 상징', array[9,17,25,34,43], 1),
  ((select id from public.dreams where keyword = '말꿈'), '백마를-보는-꿈', '백마를 보는 꿈', '새하얀 털을 가진 백마와 마주치는 꿈이다. 백마는 예로부터 귀하고 상서로운 존재로 여겨져, 남다른 인연이나 명예로운 자리와 연결지어 해석되는 경우가 많다. 백마가 유유히 걸어오는 모습을 가만히 지켜보았다면, 조만간 품격 있는 소식이나 도움을 주는 귀인을 만날 수 있다는 뜻으로 풀이되기도 한다. 백마의 갈기가 바람에 휘날리며 유난히 눈부시게 느껴졌다면 그만큼 인상 깊은 계기나 성과가 기다리고 있다는 신호로 보는 시각도 있다. 백마를 직접 쓰다듬거나 가까이 다가갈 수 있었다면 그 좋은 기운이 나와 실제로 맞닿아 있다는 의미로 해석되기도 한다. 멀리서 백마를 바라보기만 했다면 아직은 거리가 있지만 곧 다가올 좋은 흐름의 전조로 받아들여지기도 한다.', '귀한 인연이나 명예로운 기회를 암시', array[4,13,21,30,45], 2),
  ((select id from public.dreams where keyword = '말꿈'), '말이-달리는-꿈', '말이 달리는 꿈', '말이 갈기를 휘날리며 힘차게 들판을 내달리는 꿈이다. 말이 거침없이 달리는 모습은 막힘없이 뻗어나가는 기세나 빠르게 진행되는 일의 흐름을 상징한다고 해석되곤 한다. 내가 그 말을 타고 함께 달렸다면 지금 하고 있는 일이 탄력을 받아 속도감 있게 진행될 수 있다는 신호로 풀이되기도 한다. 반대로 말이 나를 태우지 않은 채 저 혼자 앞서 달려갔다면, 상황이 내 의지보다 빠르게 흘러가고 있어 잠시 숨을 고를 필요가 있다는 뜻으로 보는 시각도 있다. 말이 달리는 길이 탁 트인 평지였는지, 험한 산길이었는지에 따라서도 느낌이 달라지는데, 평탄한 길이었다면 순조로운 진행을, 험한 길이었다면 그만큼 애쓰며 나아가야 하는 상황을 뜻한다는 이야기도 있다. 말발굽 소리가 우렁차게 울려 퍼졌다면 그 기세가 주변에도 뚜렷하게 드러나는 시기라는 의미로 읽히기도 한다.', '막힘없이 뻗어나가는 기세와 속도감', array[2,11,28,36], 3),
  ((select id from public.dreams where keyword = '말꿈'), '말에서-떨어지는-꿈', '말에서 떨어지는 꿈', '잘 달리던 말 위에서 균형을 잃고 바닥으로 떨어지는 꿈이다. 말에서 떨어지는 장면은 순조롭게 진행되던 일이 예상치 못한 순간에 흔들릴 수 있다는 걱정을 반영한다는 해석이 있다. 떨어지면서 크게 다치지 않고 가볍게 일어났다면 잠깐의 차질일 뿐 크게 염려할 정도는 아니라는 뜻으로 풀이되기도 한다. 반대로 떨어진 뒤 몸을 제대로 가누지 못했다면, 그만큼 충격이나 여파가 한동안 이어질 수 있다는 신호로 보는 시각도 있다. 말에서 떨어진 이유가 스스로 고삐를 놓쳐서였는지, 말이 갑자기 놀라서였는지도 해석에 영향을 주는데, 외부 요인이었다면 예상 밖의 변수를, 스스로의 실수였다면 방심하지 말아야 할 부분을 짚어준다는 이야기도 있다. 떨어진 뒤 다시 말에 올라탔다면 잠시 흔들렸던 상황을 다시 추스르고 나아갈 힘이 있다는 뜻으로 받아들여지기도 한다.', '순조롭던 흐름이 잠시 흔들릴 수 있음을 암시', array[23,39], 4),
  ((select id from public.dreams where keyword = '말꿈'), '망아지를-보는-꿈', '망아지를 보는 꿈', '아직 다리가 가늘고 어설픈 망아지가 뛰노는 모습을 보는 꿈이다. 망아지는 이제 막 시작하는 단계에 있는 존재이기 때문에, 새로운 시작이나 앞으로 성장할 가능성을 상징한다고 해석되는 경우가 많다. 망아지가 비틀거리면서도 씩씩하게 일어서서 걸으려 하는 모습을 보았다면, 지금은 서툴러도 꾸준히 나아가면 자리를 잡아갈 일이 있다는 뜻으로 풀이되기도 한다. 어미 말 곁에서 망아지가 편안하게 뛰노는 장면이었다면 주변의 든든한 지지와 보살핌 속에서 시작할 수 있는 여건이 마련되어 있다는 신호로 보는 시각도 있다. 망아지를 직접 쓰다듬거나 돌봐주었다면 새로 시작하는 일에 정성을 쏟으려는 마음가짐을 나타낸다는 이야기도 있다. 망아지가 무럭무럭 자라는 모습까지 이어졌다면 지금의 작은 시작이 시간이 지나 큰 결실로 이어질 수 있다는 기대감으로 읽히기도 한다.', '새로운 시작과 성장 가능성을 상징', array[6,15,24,32,41], 5)
on conflict (dream_id, keyword) do nothing;

-- B-8. 닭꿈 (신규 Parent, category: 동물)
with new_dream_8 as (
  insert into public.dreams (keyword, category, interpretation)
  select '닭꿈', '동물', '## 닭꿈은 보통 어떻게 해석할까?
닭은 새벽을 알리는 울음소리와 알을 낳아 생명을 잇는 습성 때문에, 전통적으로 좋은 소식과 결실을 함께 상징하는 동물로 해석되곤 한다. 닭꿈은 전반적으로 무난하거나 긍정적인 흐름으로 풀이되는 경우가 많지만, 닭이 어떤 행동을 하는지에 따라 소식을 알리는 쪽인지, 결실을 맺는 쪽인지가 갈리곤 한다. 병아리처럼 어린 개체가 등장하면 이제 막 시작하는 일과, 성체 닭이 등장하면 이미 진행 중이거나 마무리 단계에 있는 일과 연결지어 보는 경우가 많다.

## 알리거나 결실을 맺을 때
닭이 우는 꿈은 새로운 소식과 시작을, 알을 낳는 꿈은 준비해온 일의 결실을 뜻하는 경우가 많다. 병아리를 보는 꿈 역시 이제 막 자라나는 작은 성과나 인연을 암시한다는 해석으로 이어진다.

## 잡거나 쫓길 때
닭을 직접 잡는 꿈은 애써서 성과를 손에 넣는 과정을, 반대로 닭에게 쫓기는 꿈은 사소해 보였던 일이 뜻밖에 부담스럽게 다가오는 심리를 나타낸다는 해석으로 갈리곤 한다.'
  where not exists (select 1 from public.dreams where keyword = '닭꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[2,9,18,26,33,42] from new_dream_8;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '닭꿈'), '닭이-우는-꿈', '닭이 우는 꿈', '새벽녘 수탉이 목청껏 홰를 치며 우는 꿈이다. 닭 울음소리는 예로부터 어둠이 걷히고 새로운 하루가 시작됨을 알리는 신호로 여겨져, 반가운 소식이나 좋은 출발을 상징한다고 해석되는 경우가 많다. 닭 울음소리가 크고 우렁차게 울려 퍼졌다면 그만큼 알림의 강도가 세다는 뜻으로, 뚜렷하게 체감할 만한 소식이 찾아올 수 있다는 신호로 풀이되기도 한다. 여러 번 반복해서 울었다면 한 번으로 끝나지 않고 연이어 좋은 소식이 이어질 수 있다는 해석도 있다. 닭 울음소리를 듣고 잠에서 깨어나는 느낌이 들었다면, 미뤄두었던 일을 이제는 실행에 옮길 때가 되었다는 뜻으로 받아들여지기도 한다. 반대로 닭 울음소리가 어딘가 힘없고 가늘게 들렸다면, 기대했던 소식이 예상보다 소박한 규모일 수 있다는 이야기도 있다.', '새로운 시작과 반가운 소식을 알리는 신호', array[5,14,23,32,41], 1),
  ((select id from public.dreams where keyword = '닭꿈'), '닭이-알을-낳는-꿈', '닭이 알을 낳는 꿈', '닭이 둥지에 자리를 잡고 알을 낳는 장면을 지켜보는 꿈이다. 알을 낳는 모습은 그동안 준비해온 일이 결실을 맺거나 새로운 성과가 생겨난다는 의미로 해석되는 경우가 많다. 알을 낳는 과정을 처음부터 끝까지 지켜보았다면 그 성과가 만들어지는 과정을 직접 확인하는 만큼 뿌듯함이 큰 시기라는 뜻으로 풀이되기도 한다. 낳은 알의 개수가 여러 개였다면 한 가지가 아니라 여러 방면에서 좋은 결과가 이어질 수 있다는 해석도 있다. 알을 조심스럽게 주워 담았다면 얻은 성과를 소중히 지키고 관리하려는 마음가짐을 나타낸다고 보기도 한다. 갓 낳은 알이 유난히 따뜻하고 매끈하게 느껴졌다면, 그 성과가 질적으로도 만족스러운 결과물이라는 뜻으로 받아들여지기도 한다.', '준비해온 일이 결실을 맺는 성과를 상징', array[3,12,21,30,38,44], 2),
  ((select id from public.dreams where keyword = '닭꿈'), '닭을-잡는-꿈', '닭을 잡는 꿈', '마당을 뛰어다니는 닭을 뒤쫓아 손으로 붙잡는 꿈이다. 닭을 잡는 행동은 눈앞의 기회나 실질적인 성과를 손에 넣기 위해 직접 움직이고 애쓰는 모습으로 해석되곤 한다. 이리저리 도망 다니는 닭을 힘겹게 쫓아가 겨우 붙잡았다면, 원하는 것을 얻기까지 적잖은 수고가 필요하다는 뜻으로 풀이되기도 한다. 반대로 닭이 별다른 저항 없이 순순히 잡혔다면 생각보다 수월하게 원하는 바를 이룰 수 있다는 신호로 보는 시각도 있다. 잡은 닭을 어떻게 처리했는지도 해석에 영향을 주는데, 정성껏 요리해서 나누어 먹었다면 손에 넣은 성과를 실제 생활에 유용하게 활용한다는 의미로 풀이되는 경우가 있다. 닭을 잡은 뒤 뿌듯함과 만족감이 남았다면 그만큼 노력한 만큼의 보람을 느끼는 시기라는 뜻으로도 읽힌다.', '노력을 들여 실질적 성과를 얻는 과정', array[8,19,27,35], 3),
  ((select id from public.dreams where keyword = '닭꿈'), '병아리를-보는-꿈', '병아리를 보는 꿈', '노란 솜털이 보송보송한 병아리들이 삐약거리며 몰려다니는 꿈이다. 병아리는 아직 여리고 작지만 앞으로 자라날 가능성을 품고 있어, 새로운 시작이나 소소하지만 반가운 결실을 상징한다고 해석되는 경우가 많다. 병아리 여러 마리가 어미 닭을 졸졸 따라다니는 모습이었다면, 작은 일들이 하나둘 늘어나며 순조롭게 자리를 잡아가는 흐름으로 풀이되기도 한다. 병아리를 품에 안거나 직접 모이를 주며 돌보았다면 새로 맡게 된 일이나 사람을 정성껏 챙기려는 마음가짐을 나타낸다는 이야기도 있다. 병아리가 다치지 않고 활발하게 뛰노는 모습을 보았다면 그만큼 시작이 순탄하게 흘러가고 있다는 신호로 받아들여지기도 한다. 병아리 한 마리가 무리에서 떨어져 헤맸다면, 아직 자리를 잡지 못한 부분이 있으니 조금 더 세심하게 살펴야 한다는 뜻으로 보기도 한다.', '작지만 반가운 시작과 성장 가능성', array[1,10,20,29,37], 4),
  ((select id from public.dreams where keyword = '닭꿈'), '닭에게-쫓기는-꿈', '닭에게 쫓기는 꿈', '날개를 퍼덕이는 닭에게 놀라 정신없이 도망치는 꿈이다. 닭에게 쫓기는 상황은 사소하게 여겼던 일이나 관계가 예상외로 부담스럽게 느껴지는 심리를 반영한다는 해석이 있다. 닭이 생각보다 빠르고 사납게 쫓아왔다면, 대수롭지 않게 넘겼던 일이 의외로 신경 쓰이는 문제로 커질 수 있다는 뜻으로 풀이되기도 한다. 도망치다 결국 붙잡히거나 넘어졌다면 피하려 했던 상황을 결국 마주하게 되는 흐름을 암시한다는 이야기도 있다. 반대로 요령 있게 방향을 틀어 무사히 벗어났다면, 부담스러운 상황에서도 나름의 대처법을 찾아낼 수 있다는 신호로 보는 시각도 있다. 쫓기는 내내 느낀 다급함이 유난히 생생했다면, 요즘 실제로 마음을 졸이게 하는 사소한 걱정거리가 있는지 돌아볼 만하다는 해석도 있다.', '사소한 일이 부담스럽게 느껴지는 심리 반영', array[17,40], 5)
on conflict (dream_id, keyword) do nothing;

-- B-9. 원숭이꿈 (신규 Parent, category: 동물)
with new_dream_9 as (
  insert into public.dreams (keyword, category, interpretation)
  select '원숭이꿈', '동물', '## 원숭이꿈은 보통 어떻게 해석할까?
원숭이는 영리하고 재치 있는 이미지로 널리 알려져 있어, 순발력이나 재능, 임기응변이 필요한 상황과 연결지어 해석되는 경우가 많다. 다만 변덕스럽고 예측하기 어려운 특성도 함께 지니고 있어, 상황이나 사람의 마음이 이랬다저랬다 바뀔 수 있다는 경계의 의미로 풀이되기도 한다. 원숭이가 어떤 행동을 하고 나와 어떻게 마주치는지에 따라 재능을 발휘하는 쪽으로 읽힐 수도, 조심해야 할 관계를 암시하는 쪽으로 읽힐 수도 있다.

## 재주를 부리거나 성장할 때
원숭이가 재주를 부리는 모습은 나의 능력이 돋보이는 기회로, 새끼 원숭이를 보는 꿈은 이제 막 시작한 일이 서툴게나마 자라나는 과정으로 풀이되곤 한다.

## 물리거나 가까이 다가올 때
원숭이에게 물리는 꿈은 가까운 관계에서의 배신감이나 서운함을, 원숭이가 집 안으로 들어오는 꿈은 예상치 못한 변수가 생활 가까이 다가오는 상황을 나타낸다는 해석으로 이어지곤 한다.'
  where not exists (select 1 from public.dreams where keyword = '원숭이꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,10,19,27,35,43] from new_dream_9;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '원숭이꿈'), '원숭이를-보는-꿈', '원숭이를 보는 꿈', '나무 사이를 재빠르게 오가는 원숭이를 발견하는 꿈이다. 원숭이는 영리하고 재치 있는 이미지 때문에 순발력이나 임기응변이 필요한 상황과 연결지어 해석되는 경우가 많다. 원숭이가 나를 흥미롭다는 듯 빤히 쳐다보았다면, 주변에서 나의 재치나 순발력을 눈여겨보는 상황이 생길 수 있다는 뜻으로 풀이되기도 한다. 원숭이가 여유롭게 움직이며 장난스러운 몸짓을 보였다면 다가오는 상황을 가볍고 유연하게 풀어갈 수 있다는 신호로 보는 시각도 있다. 다만 원숭이 특유의 변덕스러운 이미지 때문에, 상황이나 사람의 마음이 이랬다저랬다 바뀔 수 있다는 주의로 받아들이는 해석도 있다. 원숭이를 편안한 거리에서 지켜보기만 했다면, 그런 변수들을 침착하게 관찰하며 대응할 여유가 있다는 뜻으로도 풀이된다.', '순발력과 재치가 필요한 상황을 암시', array[7,16,25,38], 1),
  ((select id from public.dreams where keyword = '원숭이꿈'), '원숭이가-재주를-부리는-꿈', '원숭이가 재주를 부리는 꿈', '재주 많은 원숭이가 이런저런 묘기를 선보이는 꿈이다. 원숭이가 재주를 부리는 모습은 나 자신의 능력이나 재능이 여러 사람 앞에서 돋보일 기회를 상징한다고 해석되는 경우가 많다. 원숭이의 재주가 능숙하고 화려해서 보는 이들이 박수를 쳤다면, 그만큼 준비해온 실력을 인정받는 기쁜 순간이 찾아올 수 있다는 뜻으로 풀이되기도 한다. 반대로 재주를 부리다 실수하거나 어설픈 모습을 보였다면, 아직은 다듬어야 할 부분이 남아 있다는 신호로 보는 시각도 있다. 원숭이의 재주를 흥미롭게 구경하는 입장이었다면, 주변 사람의 재능이나 새로운 아이디어에서 좋은 자극을 받는 시기라는 이야기도 있다. 원숭이가 재주를 부리며 보상을 받는 장면까지 이어졌다면, 노력에 걸맞은 인정이나 대가가 뒤따를 수 있다는 뜻으로 받아들여지기도 한다.', '능력과 재능이 돋보이는 기회를 암시', array[4,13,22,31,40], 2),
  ((select id from public.dreams where keyword = '원숭이꿈'), '원숭이에게-물리는-꿈', '원숭이에게 물리는 꿈', '장난스럽게 다가온 원숭이에게 갑자기 손이나 팔을 물리는 꿈이다. 원숭이에게 물리는 상황은 믿었던 사람이나 가까운 관계에서 예상치 못한 배신감이나 서운함을 느낄 수 있다는 걱정을 반영한다는 해석이 있다. 처음에는 친근하게 다가와 놓고 갑자기 돌변해 물었다면, 겉으로 보이는 모습과 실제 속내가 다른 사람을 조심하라는 신호로 풀이되기도 한다. 물린 상처가 가볍게 지나갔다면 그 서운함이 오래가지 않고 곧 풀릴 수 있는 사소한 문제일 가능성으로 보는 시각도 있다. 반대로 물린 자리가 깊고 아팠다면, 그만큼 관계에서 받은 상처가 신경 쓰이는 상황이라는 뜻으로 해석되기도 한다. 물린 뒤 원숭이와 다시 거리를 두게 되었다면, 자연스럽게 그 관계에 대한 경계심이 커지는 시기라는 이야기도 있다.', '가까운 관계에서의 배신감이나 서운함 암시', array[11,29], 3),
  ((select id from public.dreams where keyword = '원숭이꿈'), '새끼-원숭이를-보는-꿈', '새끼 원숭이를 보는 꿈', '어미 품에 안겨 있거나 나뭇가지를 서툴게 오르는 새끼 원숭이를 보는 꿈이다. 새끼 원숭이는 아직 서툴지만 앞으로 커나갈 존재라는 점에서, 이제 막 시작한 일이나 아이디어가 성장해가는 과정을 상징한다고 해석되는 경우가 많다. 새끼 원숭이가 어미에게 꼭 안겨 있는 모습이었다면, 새로 시작한 일이 든든한 배경이나 지지 속에서 안정적으로 자리 잡아가고 있다는 뜻으로 풀이되기도 한다. 나뭇가지를 오르내리다 몇 번이고 미끄러지면서도 다시 도전하는 모습을 보였다면, 서툴러도 포기하지 않는 태도가 결국 성장으로 이어진다는 신호로 보는 시각도 있다. 새끼 원숭이를 직접 안아보거나 쓰다듬었다면, 새로 맡은 일이나 사람을 세심하게 돌보고 싶은 마음이 반영된 것이라는 해석도 있다. 새끼 원숭이가 즐겁게 뛰노는 모습이 오래도록 기억에 남았다면, 그 시작이 앞으로 좋은 기억으로 남을 만큼 순조롭다는 뜻으로도 읽힌다.', '서툴지만 성장해가는 시작을 상징', array[6,15,24,33,42], 4),
  ((select id from public.dreams where keyword = '원숭이꿈'), '원숭이가-집에-들어오는-꿈', '원숭이가 집에 들어오는 꿈', '낯선 원숭이가 문을 열고 불쑥 집 안으로 들어오는 꿈이다. 원숭이가 집 안까지 들어왔다는 것은 예상치 못한 사람이나 일이 내 생활 영역 가까이 다가온다는 의미로 해석되곤 한다. 원숭이가 반갑다는 듯 재롱을 부리며 들어왔다면, 그 새로운 요소가 생활에 즐거움이나 활기를 더해줄 수 있다는 뜻으로 풀이되기도 한다. 반대로 원숭이가 집 안을 어지럽히거나 물건을 함부로 만졌다면, 예상치 못한 변수가 일상의 흐름을 다소 흐트러뜨릴 수 있다는 신호로 보는 시각도 있다. 원숭이를 순순히 받아들여 함께 지냈다면 새로운 변화를 유연하게 받아들이는 태도를 나타낸다는 이야기도 있다. 원숭이를 다시 밖으로 내보냈다면, 그 변수를 내 생활 안으로 깊이 들이지 않고 적당한 선에서 정리하려는 마음가짐으로 읽히기도 한다.', '예상치 못한 변수가 생활 가까이 다가옴', array[9,20,36], 5)
on conflict (dream_id, keyword) do nothing;

-- B-10. 사자꿈 (신규 Parent, category: 동물)
with new_dream_10 as (
  insert into public.dreams (keyword, category, interpretation)
  select '사자꿈', '동물', '## 사자꿈은 보통 어떻게 해석할까?
사자는 백수의 왕으로 불릴 만큼 강한 존재감을 지니고 있어, 전통적으로 권위와 자신감, 강한 추진력을 상징하는 동물로 해석되곤 한다. 사자꿈은 사자와 내가 어떤 관계로 마주하는지에 따라 해석이 크게 갈리는 편인데, 사자를 다루거나 함께하는 입장이라면 힘과 영향력을 상징하는 쪽으로, 사자에게 쫓기거나 압도되는 입장이라면 부담감이나 압박감을 나타내는 쪽으로 풀이되곤 한다.

## 마주하거나 함께할 때
사자를 보거나 눈이 마주치는 꿈은 권위 있는 대상과의 만남을, 사자를 타는 꿈은 그런 힘을 스스로 다루고 이끄는 위치에 서는 것을 뜻하는 경우가 많다.

## 맞서거나 쫓길 때, 그리고 새로 자라날 때
사자와 싸워 이기는 꿈은 큰 어려움을 극복하는 성취를, 사자에게 쫓기는 꿈은 그 반대로 감당하기 버거운 압박감을 나타낸다는 해석으로 이어진다. 새끼 사자를 보는 꿈은 아직 작지만 앞으로 커나갈 역량을 상징한다고 풀이되기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '사자꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[1,9,17,28,37,45] from new_dream_10;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '사자꿈'), '사자를-보는-꿈', '사자를 보는 꿈', '멀리서 위풍당당한 사자 한 마리를 마주하는 꿈이다. 사자는 예로부터 백수의 왕으로 불릴 만큼 강한 존재감을 지니고 있어, 권위나 자신감, 강한 추진력을 상징한다고 해석되는 경우가 많다. 사자가 여유롭게 걸으며 위엄을 드러냈다면, 지금 내가 맡은 자리나 역할에서 그만큼 무게감 있는 존재감을 보여줄 수 있다는 뜻으로 풀이되기도 한다. 사자를 보고 두려움보다 경외감을 느꼈다면, 큰 책임이나 도전 앞에서도 압도되기보다 스스로를 다잡을 힘이 있다는 신호로 보는 시각도 있다. 반대로 사자의 존재만으로 위축되고 몸이 굳었다면, 아직 감당하기 벅차게 느껴지는 상황이 있다는 뜻으로 해석되기도 한다. 사자가 자리를 지키며 주변을 둘러보는 모습이었다면, 내가 속한 자리나 영역을 든든하게 지켜내고 있다는 의미로도 읽힌다.', '강한 권위와 존재감, 자신감을 상징', array[3,12,26,34,43], 1),
  ((select id from public.dreams where keyword = '사자꿈'), '사자에게-쫓기는-꿈', '사자에게 쫓기는 꿈', '포효하는 사자에게 놀라 있는 힘껏 도망치는 꿈이다. 사자에게 쫓기는 상황은 감당하기 버거운 압박감이나 권위 있는 대상 앞에서 느끼는 부담감을 반영한다는 해석이 있다. 사자와의 거리가 점점 좁혀지며 다급함이 커졌다면, 최근 마음을 짓누르는 부담이 상당히 크게 느껴지고 있다는 신호로 풀이되기도 한다. 도망치다 몸을 숨길 곳을 찾아 위기를 넘겼다면, 힘든 상황 속에서도 나름의 대처법을 찾아낼 여지가 있다는 뜻으로 보는 시각도 있다. 반대로 끝내 붙잡히거나 쫓기다 지쳐버렸다면, 그 부담감을 피하기보다 정면으로 마주해야 할 시점이 다가오고 있다는 이야기도 있다. 꿈에서 느낀 다급함과 두려움이 유난히 강렬했다면, 실제로 나를 압박하는 대상이나 상황이 무엇인지 돌아볼 만하다는 해석도 있다.', '감당하기 버거운 압박감이나 부담을 암시', array[18,36], 2),
  ((select id from public.dreams where keyword = '사자꿈'), '사자와-눈이-마주치는-꿈', '사자와 눈이 마주치는 꿈', '가까운 거리에서 사자와 정면으로 눈이 마주치는 꿈이다. 사자와 눈을 맞춘다는 것은 강한 존재나 권위 있는 사람과 직접적으로 관계를 맺게 된다는 의미로 해석되곤 한다. 눈이 마주친 순간 사자가 별다른 반응 없이 지나쳤다면, 긴장했던 것과 달리 상황이 무난하게 지나갈 수 있다는 신호로 풀이되기도 한다. 반대로 사자가 눈을 떼지 않고 계속 나를 응시했다면, 누군가 나를 유심히 지켜보거나 평가하는 상황이 이어질 수 있다는 뜻으로 보는 시각도 있다. 눈이 마주친 순간 피하지 않고 시선을 맞받았다면, 부담스러운 상황에서도 위축되지 않는 배짱을 나타낸다는 이야기도 있다. 그 눈빛에서 위협보다 어떤 교감 같은 것을 느꼈다면, 강한 존재와도 예상외로 좋은 관계를 맺을 수 있다는 의미로 읽히기도 한다.', '권위 있는 대상과의 직접적인 마주함', array[8,20,29], 3),
  ((select id from public.dreams where keyword = '사자꿈'), '사자를-타는-꿈', '사자를 타는 꿈', '사자 등에 올라타 함께 움직이는 꿈이다. 사자 위에 올라탔다는 것은 강한 힘이나 권위를 스스로 다루고 이끌어가는 위치에 서게 됨을 상징한다고 해석되는 경우가 많다. 사자가 얌전히 나를 태우고 다녔다면, 지금 맡고 있는 큰 책임이나 영향력을 무리 없이 통솔해나가고 있다는 뜻으로 풀이되기도 한다. 사자가 힘차게 내달리는데도 흔들림 없이 자세를 유지했다면, 그만큼 강한 흐름 속에서도 중심을 잃지 않는 능력을 나타낸다는 해석도 있다. 반대로 사자 등에서 자꾸 미끄러지거나 불안했다면, 맡은 역할이 아직은 벅차게 느껴지는 상태라는 신호로 보는 시각도 있다. 사자를 타고 높은 곳이나 넓은 벌판을 내려다보았다면, 지금의 위치에서 이전보다 넓은 시야와 영향력을 갖게 되었다는 의미로도 읽힌다.', '강한 힘과 권위를 이끄는 위치를 상징', array[2,11,27,35,44], 4),
  ((select id from public.dreams where keyword = '사자꿈'), '사자와-싸워-이기는-꿈', '사자와 싸워 이기는 꿈', '사자와 맞서 싸워 결국 승리를 거두는 꿈이다. 사자와의 싸움에서 이겼다는 것은 큰 어려움이나 강력한 경쟁 상대를 상대로 결국 원하는 결과를 얻어낸다는 의미로 해석되곤 한다. 처음에는 힘에 부쳐 밀리다가 끝내 역전해 이겼다면, 지금 겪고 있는 어려움도 끈기를 가지고 버티면 결국 극복할 수 있다는 신호로 풀이되기도 한다. 큰 상처 없이 비교적 수월하게 승리했다면, 예상했던 것보다 쉽게 문제를 풀어낼 수 있다는 뜻으로 보는 시각도 있다. 싸움에서 이긴 뒤 벅찬 성취감을 느꼈다면, 그 결과가 스스로에게도 의미 있는 자신감으로 남을 만한 일이라는 해석도 있다. 쓰러진 사자를 내려다보며 담담한 기분이 들었다면, 힘든 과정을 거치며 한층 단단해진 마음가짐을 나타낸다는 이야기도 있다.', '강력한 어려움을 극복하고 얻는 성취', array[8,16,25,33,42], 5),
  ((select id from public.dreams where keyword = '사자꿈'), '새끼-사자를-보는-꿈', '새끼 사자를 보는 꿈', '아직 몸집이 작고 어설픈 새끼 사자가 뒹굴며 노는 모습을 보는 꿈이다. 새끼 사자는 앞으로 강한 존재로 자라날 잠재력을 지니고 있어, 이제 막 싹트기 시작한 역량이나 리더십을 상징한다고 해석되는 경우가 많다. 어미 사자 곁에서 새끼 사자가 응석을 부리며 노는 장면이었다면, 아직은 보호받는 위치에 있지만 앞으로 성장할 여지가 크다는 뜻으로 풀이되기도 한다. 새끼 사자가 형제들과 뒤엉켜 장난치는 모습을 보았다면, 여럿 가운데서도 자신만의 존재감을 조금씩 키워가는 과정을 나타낸다는 해석도 있다. 새끼 사자를 직접 안아보거나 쓰다듬었다면, 이제 막 시작한 일이나 사람을 세심하게 키워내고 싶은 마음이 반영된 것이라는 이야기도 있다. 새끼 사자가 서툴게나마 포효를 흉내 내는 모습을 보았다면, 아직은 작지만 자기 목소리를 내기 시작하는 시기라는 뜻으로도 읽힌다.', '이제 막 싹트는 역량과 리더십을 상징', array[4,13,22,31,39], 6)
on conflict (dream_id, keyword) do nothing;

-- B-11. 피꿈 (신규 Parent, category: 신체)
with new_dream_11 as (
  insert into public.dreams (keyword, category, interpretation)
  select '피꿈', '신체', '## 피꿈은 보통 어떻게 해석할까?
피가 나오는 꿈은 놀라서 깨는 경우가 많지만, 전통 해몽에서는 흉몽으로만 보지 않는다. 피는 생명력과 재물, 감정의 흐름을 동시에 상징한다고 여겨지며, 상황에 따라 전혀 다르게 풀이된다. 흐르는 피의 양이나 놀란 정도보다, 꿈속에서 느낀 감정의 결이 더 중요한 실마리로 다뤄지는 편이다.

## 피가 나는 부위와 상황에 따른 차이
코피처럼 자연스럽게 흐르는 경우와 상처에서 배어 나오는 경우는 조금 다르게 해석된다. 전자는 쌓인 감정이 풀려나가는 흐름으로, 후자는 아직 아물지 않은 마음으로 보는 시선이 많다. 몸에 피가 묻어 있거나 남이 피 흘리는 모습을 보는 꿈은 자신보다 주변 상황에 대한 반응으로 풀이되곤 한다.

## 놀란 마음을 다스리는 법
이런 꿈은 신체적인 걱정보다 마음에 쌓인 감정을 돌아보라는 신호로 받아들이는 것이 일반적이다. 놀란 채로 깨어났다면 잠시 심호흡을 하고, 요즘 마음에 걸리는 일이 없는지 가볍게 점검해 보는 정도로 충분하다.'
  where not exists (select 1 from public.dreams where keyword = '피꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,11,19,24,32,41] from new_dream_11;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '피꿈'), '코피가-나는-꿈', '코피가 나는 꿈', '코피가 왈칵 쏟아지는 꿈이다. 전통적으로 피는 재물이나 에너지의 흐름을 상징한다고 해석되곤 한다. 갑작스레 코피가 터지는 장면은 그동안 억눌러 온 감정이나 스트레스가 한꺼번에 풀려나가는 신호로 여겨지기도 한다. 흐르는 피의 양이 많았다면 그만큼 마음속에 쌓인 것이 컸다는 뜻으로 풀이하는 시선도 있다. 반대로 코피를 닦아내며 대수롭지 않게 넘겼다면, 걱정거리를 스스로 잘 추스르고 있다는 의미로 받아들이기도 한다. 꿈에서 놀랐던 감정이 컸다면, 최근 무리하고 있는 부분은 없는지 가볍게 돌아보는 계기로 삼아도 좋겠다.', '억눌린 감정과 긴장이 한번에 풀려나가는 신호', null, 1),
  ((select id from public.dreams where keyword = '피꿈'), '몸에-피가-묻는-꿈', '몸에 피가 묻는 꿈', '내 몸 여기저기에 피가 묻어 있는 것을 발견하는 꿈이다. 상처를 입은 기억이 없는데도 피가 묻어 있다면, 최근 겪은 일이 예상보다 마음에 깊게 남아 있다는 뜻으로 해석되곤 한다. 옷이나 손에 피가 묻은 정도에 따라 마음의 짐이 얼마나 무거운지를 가늠해 보는 풀이도 있다. 피를 씻어내려 애쓰는 장면이었다면, 지금 그 부담을 정리하고 싶은 마음이 꿈으로 나타난 것으로 보기도 한다. 반대로 피 묻은 모습을 별다른 동요 없이 바라보았다면, 상황을 담담하게 받아들이는 태도를 상징한다는 시선도 있다. 이런 꿈을 꾼 뒤에는 마음에 걸리는 일을 하나씩 정리해 보는 것도 도움이 될 수 있다.', '마음에 남은 부담의 무게를 가늠해보는 신호', array[7,22], 2),
  ((select id from public.dreams where keyword = '피꿈'), '남이-피-흘리는-것을-보는-꿈', '남이 피 흘리는 것을 보는 꿈', '다른 사람이 피를 흘리는 모습을 지켜보는 꿈이다. 이런 장면은 흔히 주변 사람에 대한 걱정이나 관심이 꿈으로 옮겨진 것이라는 해석이 많다. 피를 흘리는 사람이 아는 얼굴이었다면, 그 사람의 상황에 자신도 모르게 마음을 쓰고 있다는 뜻으로 풀이되기도 한다. 낯선 사람이었을 경우에는 자신이 통제하기 어려운 외부 상황에 대한 불안이 반영된 것으로 보는 시선도 있다. 피 흘리는 이를 도와주려 했다면, 누군가를 돕고 싶은 마음이나 책임감이 강하게 작용하고 있다는 의미로 여겨지기도 한다. 그저 지켜보기만 했다면, 자신이 개입하기 조심스러운 상황에 놓여 있다는 신호로 해석하는 경우도 있다.', '주변 사람에 대한 걱정과 관심이 투영된 장면', null, 3),
  ((select id from public.dreams where keyword = '피꿈'), '피를-토하는-꿈', '피를 토하는 꿈', '자신이 피를 토하는 꿈이다. 놀라서 잠에서 깨는 경우가 많지만, 전통적인 해몽에서는 오히려 억눌러 온 말이나 감정을 밖으로 쏟아내고 싶은 마음을 상징한다고 보는 편이다. 하고 싶은 말을 참아온 시간이 길었다면, 그 답답함이 극적인 장면으로 표현된 것으로 풀이되기도 한다. 피를 토한 뒤 오히려 후련한 기분이 들었다면, 묵혀둔 감정을 털어내고 나아지는 흐름으로 여겨지는 해석도 있다. 이 꿈은 신체적인 증상과는 무관하게, 마음속 응어리에 초점을 맞춰 받아들이는 것이 일반적이다. 최근 하지 못한 말이 있다면, 편한 방식으로 조금씩 풀어보는 것도 좋은 방법이 될 수 있다.', '참아온 감정을 밖으로 쏟아내고 싶은 마음', array[15], 4),
  ((select id from public.dreams where keyword = '피꿈'), '상처에서-피가-나는-꿈', '상처에서 피가 나는 꿈', '작은 상처에서 피가 배어 나오는 것을 보는 꿈이다. 상처와 피는 흔히 마음에 남은 서운함이나 아직 아물지 않은 감정을 나타낸다고 해석되곤 한다. 상처의 크기가 작았다면 그 감정 역시 크지 않아 시간이 지나면 자연스레 가라앉을 것이라는 풀이가 많다. 피가 계속 흐르는 장면이었다면, 마음에 걸리는 일을 아직 제대로 마주하지 못했다는 신호로 보기도 한다. 상처를 직접 소독하거나 감쌌다면, 스스로 그 마음을 다독이고 회복하려는 의지가 담긴 것으로 여겨진다. 이런 꿈을 꾼 뒤에는 마음에 걸리는 일을 억지로 참기보다 조금씩 풀어가 보는 편이 낫다는 해석도 있다.', '아직 아물지 않은 서운한 감정의 흔적', array[9,28], 5)
on conflict (dream_id, keyword) do nothing;

-- B-12. 머리카락 빠지는 꿈 (신규 Parent, category: 신체)
with new_dream_12 as (
  insert into public.dreams (keyword, category, interpretation)
  select '머리카락 빠지는 꿈', '신체', '## 머리카락 빠지는 꿈은 보통 어떻게 해석할까?
머리카락은 예로부터 기력, 재물, 사회적 체면을 함께 상징하는 소재로 다뤄져 왔다. 그래서 머리카락이 빠지거나 잘리는 꿈은 무언가를 잃는다는 두려움보다, 지금 짊어진 것을 내려놓거나 새롭게 정리하는 흐름으로 해석되는 경우가 많다. 반대로 머리카락이 자라거나 풍성해지는 꿈은 기운과 재물이 채워지는 신호로 받아들여지곤 한다.

## 빠지는 꿈과 자라는 꿈의 차이
머리카락이 빠지거나 대머리가 되는 꿈은 소진된 기력이나 부담감을 반영하는 경우가 많고, 머리카락을 자르는 꿈은 스스로 변화를 택하는 의미가 강하다. 반대로 길게 자라는 꿈은 채워지는 흐름을, 흰 머리카락을 보는 꿈은 쌓여가는 연륜을 나타낸다고 보는 시선이 일반적이다.

## 몸과 마음을 함께 돌아볼 시기
이런 꿈을 꾸었다면 최근 무리하고 있지는 않은지, 혹은 정리하고 싶은 일이 쌓여 있지는 않은지 가볍게 점검해 보는 것도 좋다.'
  where not exists (select 1 from public.dreams where keyword = '머리카락 빠지는 꿈')
  returning id
)
