insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '머리카락 빠지는 꿈'), '머리카락이-한-움큼-빠지는-꿈', '머리카락이 한 움큼 빠지는 꿈', '머리를 만졌는데 머리카락이 한 움큼씩 빠져나오는 꿈이다. 예로부터 머리카락은 그 사람의 기력이나 사회적 위치를 상징한다고 여겨져, 이런 꿈은 힘이 빠지는 상황이나 소진된 기분을 반영한다는 해석이 많다. 빠진 머리카락을 손에 쥐고 놀랐다면, 최근 부담스러운 일에 에너지를 많이 쓰고 있다는 신호로 풀이되기도 한다. 거울을 보며 빠진 자리를 확인했다면, 스스로도 지쳐가고 있다는 것을 어렴풋이 느끼고 있다는 뜻으로 보는 시선도 있다. 다만 머리카락이 빠지는 꿈을 무조건 나쁘게만 보지는 않으며, 묵은 것을 덜어내고 새로 채울 자리를 마련하는 과정으로 풀이하는 경우도 있다. 요즘 몸과 마음을 돌보는 시간이 부족하지 않았는지 한 번쯤 점검해 볼 만하다.', '소진된 기력과 부담감이 드러나는 신호', null, 1),
  ((select id from public.dreams where keyword = '머리카락 빠지는 꿈'), '대머리가-되는-꿈', '대머리가 되는 꿈', '거울을 보니 어느새 머리카락이 다 빠지고 대머리가 되어 있는 꿈이다. 갑작스러운 변화라 당황스럽게 느껴지지만, 전통적으로는 지금까지 짊어지고 있던 무언가를 완전히 내려놓게 되는 상황을 상징한다고 해석되곤 한다. 대머리가 된 모습을 낯설어하며 받아들이지 못했다면, 변화 자체에 아직 마음의 준비가 덜 되어 있다는 뜻으로 풀이되기도 한다. 반대로 담담하게 받아들이는 꿈이었다면, 체면이나 겉치레보다 본질에 집중하려는 마음가짐을 나타낸다고 보는 시선도 있다. 주변 사람들의 반응이 인상적이었다면, 그 반응은 실제로 자신이 신경 쓰고 있는 시선을 대변하는 것으로 여겨지기도 한다. 이 시기에는 겉으로 보이는 것보다 스스로의 상태를 먼저 챙기는 편이 좋겠다.', '짊어진 것을 완전히 내려놓게 되는 변화', array[12], 2),
  ((select id from public.dreams where keyword = '머리카락 빠지는 꿈'), '머리카락을-자르는-꿈', '머리카락을 자르는 꿈', '미용실이나 어딘가에서 머리카락을 짧게 자르는 꿈이다. 머리카락을 자르는 행위는 전통적으로 지난 일을 정리하고 새로운 국면으로 넘어가려는 마음을 상징한다고 해석되곤 한다. 스스로 원해서 머리를 잘랐다면, 변화를 주도적으로 받아들이려는 의지가 반영된 것으로 풀이되기도 한다. 누군가에게 억지로 잘렸다면, 원치 않는 변화나 압박감을 느끼고 있다는 뜻으로 보는 시선도 있다. 잘린 머리카락의 길이가 짧을수록 정리하고 싶은 마음이 크다는 의미로 다루는 해석도 있다. 산뜻한 기분으로 거울을 봤다면, 새로운 시작을 앞두고 있다는 긍정적인 신호로 받아들여도 좋겠다.', '지난 일을 정리하고 새로 나아가려는 의지', array[2,17,29,38], 3),
  ((select id from public.dreams where keyword = '머리카락 빠지는 꿈'), '흰-머리카락을-보는-꿈', '흰 머리카락을 보는 꿈', '거울 속에서 새치나 흰 머리카락을 발견하는 꿈이다. 흰 머리카락은 흔히 지혜나 연륜, 혹은 세월의 흐름을 상징한다고 여겨져, 이런 꿈은 그동안의 경험이 쌓여가고 있다는 뜻으로 해석되기도 한다. 흰 머리카락을 발견하고 놀랐다면, 나이 들어가는 것에 대한 막연한 걱정이 담겨 있다는 풀이도 있다. 반대로 대수롭지 않게 받아들였다면, 지금의 자신을 있는 그대로 받아들이는 여유가 생겼다는 신호로 보기도 한다. 흰 머리카락을 하나씩 뽑는 꿈이었다면, 신경 쓰이는 부분을 하나하나 해결해 나가려는 마음가짐을 나타낸다는 해석도 있다. 세월이 쌓아준 경험을 긍정적으로 바라보는 계기로 삼아도 좋을 꿈이다.', '쌓여가는 경험과 연륜을 받아들이는 마음', array[8,21,33], 4),
  ((select id from public.dreams where keyword = '머리카락 빠지는 꿈'), '머리카락이-길게-자라는-꿈', '머리카락이 길게 자라는 꿈', '머리카락이 눈에 띄게 길게 자라 있는 것을 보는 꿈이다. 머리카락이 풍성하게 자라는 모습은 전통적으로 재물이나 기운이 채워지는 흐름을 상징한다고 여겨지곤 한다. 길게 자란 머리카락을 만족스럽게 바라보았다면, 그동안 노력한 것들이 서서히 결실을 맺어가고 있다는 뜻으로 풀이되기도 한다. 머리카락이 바람에 찰랑이는 느낌이 좋았다면, 마음의 여유와 자신감이 커지고 있다는 신호로 보는 시선도 있다. 지나치게 길어 다루기 힘들었던 경우라면, 넘치는 기운을 어떻게 쓸지 고민이 필요하다는 해석도 곁들여진다. 전반적으로 성장과 축적의 기운이 담긴 꿈으로 받아들여도 좋겠다.', '기운과 재물이 서서히 채워지는 흐름', array[5,14,23,31,42], 5)
on conflict (dream_id, keyword) do nothing;

-- B-13. 옛 연인이 나오는 꿈 (신규 Parent, category: 인물)
with new_dream_13 as (
  insert into public.dreams (keyword, category, interpretation)
  select '옛 연인이 나오는 꿈', '인물', '## 옛 연인이 나오는 꿈은 보통 어떻게 해석할까?
옛 연인이 꿈에 나오는 것은 그 사람을 향한 그리움이라기보다, 그 시절 자신의 감정을 다시 마주하는 과정으로 해석되는 경우가 많다. 실제 재회나 특정한 사건을 예고한다고 보기보다는, 아직 정리되지 않은 마음이나 지나간 관계에 대한 기억이 떠오른 것으로 풀이하는 시선이 일반적이다. 등장하는 옛 연인의 표정과 분위기, 그리고 그 안에서 느끼는 자신의 감정이 해석의 핵심이 된다.

## 만남의 분위기에 따른 차이
반갑게 다시 만나거나 편안한 시간을 보내는 꿈은 마음의 부담이 가벼워졌다는 신호로, 다투거나 눈물을 보이는 꿈은 아직 남은 감정을 정리해야 한다는 신호로 다뤄지곤 한다. 다른 사람과 함께 있는 모습을 보는 꿈 역시 질투보다는 스스로의 미련을 확인하는 계기로 해석되는 경우가 많다.

## 감정 정리의 신호로 받아들이기
옛 연인이 반복해서 꿈에 나온다면, 그 관계에서 배운 것을 정리하고 지금의 관계에 집중하라는 신호로 가볍게 받아들이는 것이 좋다.'
  where not exists (select 1 from public.dreams where keyword = '옛 연인이 나오는 꿈')
  returning id
)
