insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '옛 연인이 나오는 꿈'), '헤어진-연인이-나타나는-꿈', '헤어진 연인이 나타나는 꿈', '오랫동안 연락이 끊겼던 옛 연인이 갑자기 눈앞에 나타나는 꿈이다. 이런 꿈은 실제로 그 사람을 다시 만나고 싶다는 의미보다, 그 시절에 남아 있던 감정이나 미처 정리하지 못한 마음이 떠오른 것이라는 해석이 많다. 아무렇지 않게 인사를 나눴다면, 그 관계에 대한 마음이 이제는 많이 정리되었다는 뜻으로 풀이되기도 한다. 반대로 놀라거나 어색했다면, 아직 완전히 매듭짓지 못한 감정이 남아 있다는 신호로 보는 시선도 있다. 옛 연인의 표정이나 분위기가 유독 인상적이었다면, 그 인상이 지금의 자신에게 어떤 의미로 다가오는지 되짚어볼 만하다. 지나간 인연이 꿈에 나온다고 해서 특별한 사건으로 이어진다고 보기보다는, 마음 정리의 신호로 가볍게 받아들이는 편이 좋겠다.', '정리되지 못한 지난 감정이 떠오르는 신호', array[11], 1),
  ((select id from public.dreams where keyword = '옛 연인이 나오는 꿈'), '옛-연인과-다시-만나는-꿈', '옛 연인과 다시 만나는 꿈', '헤어졌던 연인과 다시 만나 예전처럼 시간을 보내는 꿈이다. 실제로 재회를 예고한다기보다, 그 관계에서 느꼈던 편안함이나 그리움이 마음 한켠에 남아 있다는 해석으로 보는 경우가 많다. 즐거운 분위기로 함께 있었다면, 지금의 인간관계에서 그와 비슷한 편안함을 바라고 있다는 뜻으로 풀이되기도 한다. 다시 만나는 장소가 예전에 자주 가던 곳이었다면, 그 시절의 익숙함을 그리워하는 마음이 반영된 것으로 보는 시선도 있다. 어색함 없이 자연스럽게 대화를 나눴다면, 지나간 인연에 대한 감정이 이제는 무겁지 않게 자리 잡았다는 의미로 여겨지기도 한다. 이런 꿈은 새로운 관계를 맺는 데 있어 마음의 문을 여는 신호로 해석되는 경우도 있다.', '그리웠던 편안함을 다시 바라는 마음', array[3,16,29], 2),
  ((select id from public.dreams where keyword = '옛 연인이 나오는 꿈'), '옛-연인이-다른-사람과-있는-꿈', '옛 연인이 다른 사람과 있는 꿈', '옛 연인이 다른 사람과 다정하게 있는 모습을 지켜보는 꿈이다. 질투나 서운함이 느껴졌다면, 아직 완전히 정리되지 않은 미련이 남아 있다는 뜻으로 해석되곤 한다. 별다른 동요 없이 담담하게 바라보았다면, 그 관계에 대한 마음이 이미 충분히 정리되었다는 신호로 풀이되기도 한다. 옆에 있는 사람이 낯선 얼굴이었다면 막연한 상실감을, 아는 얼굴이었다면 주변 관계에 대한 복잡한 감정을 반영한다는 시선도 있다. 이 장면을 보고 오히려 홀가분한 기분이 들었다면, 새로운 관계를 받아들일 준비가 되어가고 있다는 의미로 여겨지기도 한다. 지나간 감정에 얽매이기보다, 지금의 자신에게 집중하라는 신호로 받아들이는 해석이 많다.', '남아있는 미련을 스스로 확인하는 장면', null, 3),
  ((select id from public.dreams where keyword = '옛 연인이 나오는 꿈'), '옛-연인과-싸우는-꿈', '옛 연인과 싸우는 꿈', '옛 연인과 다시 만나 예전처럼 다투는 꿈이다. 헤어질 당시 풀리지 않았던 감정이나 하고 싶었던 말이 여전히 마음 한구석에 남아 있다는 해석이 많다. 꿈속에서 언성을 높이며 다퉜다면, 그때 다 하지 못한 이야기에 대한 미련이 표출된 것으로 풀이되기도 한다. 반대로 차분하게 언쟁을 마무리했다면, 그 감정을 정리해 가는 과정에 있다는 뜻으로 보는 시선도 있다. 싸움의 내용이 실제 헤어진 이유와 비슷했다면, 그 문제에 대한 미해결된 마음을 다시 들여다볼 시점이라는 해석도 있다. 꿈에서 느낀 답답함은 실제 관계보다는 자기 안의 감정 정리에 초점을 맞춰 받아들이는 것이 일반적이다.', '풀리지 않은 감정과 하지 못한 말의 흔적', array[7], 4),
  ((select id from public.dreams where keyword = '옛 연인이 나오는 꿈'), '옛-연인이-우는-꿈', '옛 연인이 우는 꿈', '옛 연인이 눈물을 흘리는 모습을 보는 꿈이다. 상대가 우는 모습은 실제 그 사람의 감정과는 무관하게, 자신이 그 관계에 대해 품고 있는 미안함이나 아쉬움이 투영된 것이라는 해석이 많다. 다가가 달래주었다면, 그 시절의 감정을 스스로 보듬고 정리하려는 마음이 담긴 것으로 풀이되기도 한다. 멀리서 지켜보기만 했다면, 아직 그 감정에 다가가기 조심스러운 상태라는 뜻으로 보는 시선도 있다. 우는 이유가 꿈속에서 짐작이 갔다면, 평소 마음에 걸려 있던 부분이 구체적으로 드러난 것일 수 있다는 해석도 있다. 이런 꿈을 꾼 뒤에는 지나간 감정에 너무 오래 머무르기보다, 담담히 흘려보내는 태도가 도움이 될 수 있다.', '관계에 대한 미안함과 아쉬움의 투영', array[20], 5)
on conflict (dream_id, keyword) do nothing;

-- B-14. 비 오는 꿈 (신규 Parent, category: 자연)
with new_dream_14 as (
  insert into public.dreams (keyword, category, interpretation)
  select '비 오는 꿈', '자연', '## 비 오는 꿈은 보통 어떻게 해석할까?
비는 전통 해몽에서 감정의 정화, 변화, 때로는 재물의 흐름을 함께 상징하는 소재로 다뤄진다. 그래서 같은 비라도 어떤 상황에서, 어떤 감정으로 맞이하느냐에 따라 전혀 다른 의미로 풀이되곤 한다. 비의 세기와 꿈속에서 느낀 감정이 해석의 방향을 가르는 중요한 기준이 된다.

## 비의 세기에 따라 달라지는 의미
가볍게 비를 맞거나 소나기를 만나는 꿈은 일시적인 변화나 감정의 해소로, 폭우처럼 거센 비는 감당하기 버거운 상황이나 쌓인 고민으로 해석되는 경우가 많다. 반대로 비가 그치고 해가 뜨는 꿈은 어려운 시기가 지나가고 있다는 신호로 널리 알려져 있다.

## 대비하는 태도가 중요한 이유
우산을 쓰고 비를 피하는 꿈처럼, 스스로 대비하고 있는 장면이라면 지금의 걱정을 지나치게 키울 필요는 없다는 해석이 많다. 비 오는 꿈을 꾼 뒤에는 지금의 감정이 무엇을 향해 있는지 차분히 들여다보는 것도 좋다.'
  where not exists (select 1 from public.dreams where keyword = '비 오는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[2,10,17,26,33,45] from new_dream_14;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '비 오는 꿈'), '비를-맞는-꿈', '비를 맞는 꿈', '우산도 없이 비를 그대로 맞는 꿈이다. 비는 전통적으로 정화나 감정의 해소를 상징한다고 여겨져, 이런 꿈은 마음속에 쌓여 있던 응어리가 씻겨 내려가는 과정으로 해석되곤 한다. 비를 맞으면서도 개운한 기분이었다면, 묵은 감정을 털어내고 있다는 긍정적인 신호로 풀이되기도 한다. 반대로 춥고 서러운 기분이었다면, 최근 겪은 일에 마음이 지쳐 있다는 뜻으로 보는 시선도 있다. 비의 세기가 약했다면 잔잔한 변화를, 세찼다면 감정의 기복이 크다는 것을 나타낸다는 해석도 있다. 어떤 감정으로 비를 맞았는지가 이 꿈을 이해하는 중요한 열쇠가 된다.', '쌓인 감정을 씻어내는 정화의 과정', array[14], 1),
  ((select id from public.dreams where keyword = '비 오는 꿈'), '소나기가-내리는-꿈', '소나기가 내리는 꿈', '맑던 하늘에서 갑자기 소나기가 쏟아지는 꿈이다. 예상치 못한 상황이나 갑작스러운 변화가 찾아올 수 있다는 것을 암시한다고 보는 해석이 많다. 소나기를 피해 급히 뛰어다녔다면, 갑작스러운 일에 당황하고 있는 최근의 심리 상태가 반영된 것으로 풀이되기도 한다. 비가 금방 그쳤다면, 그 변화가 오래가지 않고 빠르게 지나갈 것이라는 신호로 보는 시선도 있다. 소나기를 맞으면서도 크게 개의치 않았다면, 갑작스러운 변화에도 유연하게 대처할 수 있는 여유가 있다는 뜻으로 여겨진다. 짧고 굵은 변화에 대비하되, 너무 크게 동요할 필요는 없다는 해석이 일반적이다.', '짧고 갑작스러운 변화에 대한 신호', null, 2),
  ((select id from public.dreams where keyword = '비 오는 꿈'), '비가-그치고-해가-뜨는-꿈', '비가 그치고 해가 뜨는 꿈', '내리던 비가 그치고 구름 사이로 해가 비치는 꿈이다. 힘들었던 시기가 지나가고 상황이 나아지기 시작한다는 뜻으로 해석되는 대표적인 장면으로 꼽힌다. 젖었던 몸이나 옷이 햇볕에 마르는 느낌이 좋았다면, 그동안의 고생이 서서히 보상받는 흐름으로 풀이되기도 한다. 무지개까지 함께 떠올랐다면, 기다려온 좋은 소식이나 결실이 가까워졌다는 신호로 보는 시선도 있다. 맑아진 하늘을 올려다보며 안도감을 느꼈다면, 마음의 짐을 상당 부분 내려놓았다는 의미로 여겨진다. 전반적으로 회복과 전환의 기운이 강하게 담긴 꿈으로 받아들여진다.', '힘든 시기가 지나가고 회복되는 흐름', array[4,13,22,31,38,43], 3),
  ((select id from public.dreams where keyword = '비 오는 꿈'), '우산을-쓰고-비를-피하는-꿈', '우산을 쓰고 비를 피하는 꿈', '우산을 쓰고 비를 피하며 걸어가는 꿈이다. 어려운 상황 속에서도 스스로를 지킬 방법을 마련해 두고 있다는 것을 상징한다고 해석되곤 한다. 우산이 튼튼하고 넓었다면, 지금 기대고 있는 대비책이나 주변의 도움이 든든하다는 뜻으로 풀이되기도 한다. 바람에 우산이 흔들리거나 뒤집혔다면, 준비해 둔 것만으로는 부족한 변수가 생길 수 있다는 신호로 보는 시선도 있다. 다른 사람과 우산을 함께 썼다면, 어려운 시기를 함께 헤쳐갈 사람이 곁에 있다는 의미로 여겨지기도 한다. 스스로 대비하고 있다는 점에서 크게 걱정할 상황은 아니라는 해석이 많다.', '스스로 마련해둔 대비책과 든든함', array[6,19,27], 4),
  ((select id from public.dreams where keyword = '비 오는 꿈'), '폭우가-쏟아지는-꿈', '폭우가 쏟아지는 꿈', '앞이 잘 보이지 않을 정도로 세찬 폭우가 쏟아지는 꿈이다. 감당하기 버거운 상황이나 한꺼번에 몰려드는 걱정거리를 상징한다고 보는 해석이 많다. 빗속에서 길을 잃거나 헤맸다면, 지금 겪고 있는 여러 문제 중 무엇부터 해결해야 할지 막막한 심정이 반영된 것으로 풀이되기도 한다. 안전한 곳을 찾아 몸을 피했다면, 그 와중에도 상황을 수습할 방법을 찾아가고 있다는 뜻으로 보는 시선도 있다. 폭우가 그친 뒤의 장면까지 이어졌다면, 지금의 어려움도 결국 지나갈 것이라는 신호로 해석되기도 한다. 급한 마음이 들더라도 하나씩 차근차근 정리해 나가는 편이 좋겠다.', '한꺼번에 몰려드는 걱정거리의 무게', array[9], 5)
on conflict (dream_id, keyword) do nothing;

-- B-15. 눈 오는 꿈 (신규 Parent, category: 자연)
with new_dream_15 as (
  insert into public.dreams (keyword, category, interpretation)
  select '눈 오는 꿈', '자연', '## 눈 오는 꿈은 보통 어떻게 해석할까?
눈은 전통 해몽에서 순수함, 축적된 재물, 반가운 소식을 함께 상징하는 소재로 다뤄진다. 그래서 눈이 나오는 꿈은 대체로 좋은 흐름으로 해석되는 경우가 많지만, 눈길을 걷다 넘어지는 것처럼 세부 상황에 따라 주의가 필요한 신호가 섞이기도 한다. 눈이 내리는 모습과 그 안에서 느낀 감정을 함께 살펴보는 것이 중요하다.

## 쌓이는 눈과 활동하는 눈의 차이
소복이 쌓이거나 함박눈이 내리는 꿈은 안정과 풍요의 기운으로, 눈사람을 만들거나 눈싸움을 하는 꿈은 노력과 관계의 역동을 나타내는 것으로 풀이되곤 한다. 눈길을 걷는 꿈은 신중함이 필요한 시기임을 알려주는 신호로 다뤄지는 경우가 많다.

## 이 시기에 새겨볼 점
눈이 나오는 꿈을 꾸었다면 지금까지 쌓아온 노력이 차곡차곡 결실로 이어지고 있다는 신호로 받아들이되, 눈길처럼 미끄러운 부분은 없는지 조심스럽게 살펴보는 것이 좋다.'
  where not exists (select 1 from public.dreams where keyword = '눈 오는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[1,8,16,24,30,39] from new_dream_15;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '눈 오는 꿈'), '눈이-소복이-쌓이는-꿈', '눈이 소복이 쌓이는 꿈', '밤사이 눈이 소복이 쌓여 세상이 하얗게 덮인 꿈이다. 눈은 전통적으로 순수함과 새로운 시작, 때로는 재물이 쌓이는 것을 상징한다고 여겨진다. 쌓인 눈을 보며 마음이 평온했다면, 지금의 상황이 차분하게 정리되어 가고 있다는 뜻으로 풀이되기도 한다. 눈 덮인 풍경이 유난히 아름답게 느껴졌다면, 가까운 시일 안에 반가운 소식이 찾아올 수 있다는 신호로 보는 시선도 있다. 눈이 쌓인 만큼 발이 푹푹 빠져 걷기 힘들었다면, 좋은 흐름이지만 서두르지 말고 천천히 나아가라는 뜻으로 해석되기도 한다. 전반적으로 안정과 축적의 기운이 담긴 꿈으로 받아들여진다.', '안정과 재물이 차곡차곡 쌓이는 신호', array[5,12,21,28,36], 1),
  ((select id from public.dreams where keyword = '눈 오는 꿈'), '눈사람을-만드는-꿈', '눈사람을 만드는 꿈', '눈을 굴려 눈사람을 만드는 꿈이다. 하나씩 정성을 들여 무언가를 완성해 가는 과정을 상징한다고 해석되는 경우가 많다. 눈사람을 완성하고 뿌듯함을 느꼈다면, 그동안 공들여온 일이 곧 결실을 맺을 것이라는 신호로 풀이되기도 한다. 누군가와 함께 눈사람을 만들었다면, 그 사람과의 협력이나 관계가 좋은 결과로 이어질 수 있다는 뜻으로 보는 시선도 있다. 만들다가 눈사람이 무너졌다면, 진행 중인 일에 예상치 못한 변수가 생길 수 있다는 의미로 해석되기도 한다. 정성을 들인 만큼 결과도 따라온다는 것을 보여주는 꿈으로 여겨진다.', '정성 들인 노력이 결실을 맺어가는 과정', array[3,15,26,40], 2),
  ((select id from public.dreams where keyword = '눈 오는 꿈'), '눈싸움을-하는-꿈', '눈싸움을 하는 꿈', '친구나 가족과 눈싸움을 하며 즐거워하는 꿈이다. 가벼운 다툼이나 경쟁, 혹은 활발한 에너지를 상징한다고 해석되곤 한다. 눈싸움에서 이겼다면, 최근 신경 쓰이는 경쟁이나 갈등에서 유리한 위치에 서게 된다는 뜻으로 풀이되기도 한다. 웃으며 눈싸움을 즐겼다면, 사람들과의 관계에서 활력과 즐거움을 느끼고 있다는 신호로 보는 시선도 있다. 눈을 맞고 속상해했다면, 사소한 다툼이나 서운함이 마음에 남아 있다는 의미로 해석되기도 한다. 크게 심각한 갈등보다는 가벼운 관계의 역동으로 받아들이는 것이 일반적이다.', '가벼운 경쟁과 관계 속 활력의 표현', array[10,23], 3),
  ((select id from public.dreams where keyword = '눈 오는 꿈'), '눈길을-걷는-꿈', '눈길을 걷는 꿈', '눈이 쌓인 길을 조심스레 걸어가는 꿈이다. 미끄러운 눈길은 조심스럽게 나아가야 하는 상황이나 신중함이 필요한 시기를 상징한다고 보는 해석이 많다. 넘어지지 않고 잘 걸었다면, 지금 신중하게 처신하고 있는 태도가 좋은 결과로 이어질 것이라는 뜻으로 풀이되기도 한다. 미끄러져 넘어졌다면, 방심했던 부분에서 작은 실수가 생길 수 있다는 신호로 보는 시선도 있다. 발자국이 눈길에 선명하게 남는 것을 보았다면, 지금 걸어가는 방향이 뚜렷한 흔적을 남기고 있다는 의미로 여겨지기도 한다. 서두르지 않고 한 걸음씩 나아가는 태도가 중요하다는 것을 보여주는 꿈이다.', '신중함이 필요한 시기임을 알리는 신호', array[7], 4),
  ((select id from public.dreams where keyword = '눈 오는 꿈'), '함박눈이-내리는-꿈', '함박눈이 내리는 꿈', '굵고 탐스러운 함박눈이 펑펑 내리는 꿈이다. 풍요와 축복, 반가운 소식이 찾아오는 것을 상징하는 대표적인 장면으로 꼽힌다. 함박눈을 맞으며 기뻐했다면, 기다려온 좋은 일이 가까워지고 있다는 신호로 풀이되기도 한다. 눈이 소리 없이 쌓여가는 풍경이 인상 깊었다면, 노력의 결과가 차곡차곡 쌓이고 있다는 뜻으로 보는 시선도 있다. 눈 내리는 하늘을 올려다보며 편안함을 느꼈다면, 마음의 여유와 안정이 함께 찾아오고 있다는 의미로 여겨진다. 전반적으로 이 꿈들 가운데서도 특히 긍정적인 기운이 강하게 담긴 것으로 해석된다.', '반가운 소식과 풍요가 찾아오는 기운', array[2,11,19,25,34,44], 5)
on conflict (dream_id, keyword) do nothing;

-- B-16. 번개 치는 꿈 (신규 Parent, category: 자연)
with new_dream_16 as (
  insert into public.dreams (keyword, category, interpretation)
  select '번개 치는 꿈', '자연', '## 번개 치는 꿈은 보통 어떻게 해석할까?
번개는 전통 해몽에서 갑작스러운 깨달음, 강한 자극, 급격한 변화를 상징하는 소재로 다뤄진다. 놀랄 만큼 강렬한 이미지이지만, 무조건 나쁜 징조로만 보지는 않으며 상황을 명확하게 정리해 주는 계기로 풀이되는 경우도 많다. 번개를 직접 맞았는지, 멀리서 지켜보았는지에 따라 해석의 결이 크게 달라진다.

## 거리감에 따라 달라지는 의미
번개를 직접 맞거나 집에 떨어지는 꿈은 자신에게 직접적인 영향을 주는 변화로, 멀리서 지켜보는 꿈은 주변에서 벌어지는 사건을 관망하는 상황으로 해석되곤 한다. 천둥과 번개가 함께 치는 꿈은 감정의 격변을 상징하지만, 이후 하늘이 개는 장면이 이어진다면 안정을 되찾는 흐름으로 보는 시선이 많다.

## 강한 자극을 받아들이는 자세
이런 꿈을 꾸었다면 갑작스러운 소식이나 변화에 너무 당황하기보다, 상황을 침착하게 정리해 나가는 태도가 도움이 된다는 해석이 일반적이다.'
  where not exists (select 1 from public.dreams where keyword = '번개 치는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[6,14,22,29,37,45] from new_dream_16;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '번개 치는 꿈'), '번개를-맞는-꿈', '번개를 맞는 꿈', '몸에 번개가 내리치는 강렬한 꿈이다. 번개는 예로부터 갑작스러운 깨달음이나 큰 자극, 혹은 강한 기운의 유입을 상징한다고 해석되곤 한다. 번개를 맞고도 크게 다치지 않았다면, 갑작스러운 변화나 자극이 오히려 좋은 방향으로 작용할 수 있다는 뜻으로 풀이되기도 한다. 순간적으로 온몸이 저릿했던 느낌이 강했다면, 최근 큰 충격을 받을 만한 소식이나 상황을 마주하게 될 수 있다는 신호로 보는 시선도 있다. 번개를 맞은 뒤 오히려 정신이 또렷해졌다면, 흐릿했던 생각이 명확해지는 계기가 될 수 있다는 의미로 여겨지기도 한다. 강렬한 꿈인 만큼, 그 안에서 느낀 감정을 곱씹어보는 것이 해석의 핵심이 된다.', '갑작스러운 깨달음과 강한 자극의 순간', array[17], 1),
  ((select id from public.dreams where keyword = '번개 치는 꿈'), '멀리서-번개를-보는-꿈', '멀리서 번개를 보는 꿈', '저 멀리 하늘에서 번쩍이는 번개를 바라보는 꿈이다. 직접 겪는 위협이라기보다, 주변에서 일어나는 큰 변화나 사건을 한 발짝 떨어져서 지켜보는 상황을 상징한다고 해석되곤 한다. 번개가 아름답다고 느꼈다면, 그 변화에 대해 호기심이나 기대감을 갖고 있다는 뜻으로 풀이되기도 한다. 번개 소리에 놀라 움츠러들었다면, 주변 상황에 아직은 조심스러운 태도를 취하고 있다는 신호로 보는 시선도 있다. 번개가 여러 차례 반복해서 쳤다면, 연이은 소식이나 변화가 이어질 수 있다는 의미로 여겨지기도 한다. 직접적인 영향권 밖에 있다는 점에서, 너무 불안해할 필요는 없다는 해석이 많다.', '한 발짝 떨어져 지켜보는 큰 변화', array[4,20,32], 2),
  ((select id from public.dreams where keyword = '번개 치는 꿈'), '천둥과-번개가-함께-치는-꿈', '천둥과 번개가 함께 치는 꿈', '하늘이 요란하게 울리며 천둥과 번개가 함께 몰아치는 꿈이다. 감정의 격변이나 갑작스럽게 몰려오는 큰 사건을 상징한다고 보는 해석이 많다. 천둥소리에 크게 놀랐다면, 예상치 못한 소식에 마음의 준비가 덜 되어 있다는 뜻으로 풀이되기도 한다. 번개의 빛이 유난히 눈부셨다면, 그 사건이 오히려 상황을 명확하게 정리해 주는 계기가 될 수 있다는 신호로 보는 시선도 있다. 폭풍이 지나간 뒤 하늘이 개는 장면까지 이어졌다면, 격변 이후 오히려 안정을 찾게 된다는 의미로 해석되기도 한다. 강한 자극인 만큼, 침착하게 상황을 받아들이는 태도가 필요하다는 해석이 일반적이다.', '예상치 못한 감정의 격변과 충격', null, 3),
  ((select id from public.dreams where keyword = '번개 치는 꿈'), '번개가-집에-떨어지는-꿈', '번개가 집에 떨어지는 꿈', '번개가 자신이 살고 있는 집에 떨어지는 꿈이다. 집은 자신의 삶의 터전이나 가정을 상징하는 만큼, 이런 꿈은 가정이나 일상에 갑작스러운 변화가 찾아올 수 있다는 신호로 해석되곤 한다. 번개를 맞은 집이 무너지지 않고 그대로였다면, 큰 자극이 있더라도 근본은 흔들리지 않을 것이라는 뜻으로 풀이되기도 한다. 집안이 환하게 밝아지는 느낌이었다면, 오히려 가정에 활기나 좋은 기운이 들어오는 계기로 보는 시선도 있다. 집이 손상되거나 불안한 느낌이 강했다면, 최근 가정 내에 신경 쓰이는 문제가 있는지 돌아볼 필요가 있다는 해석도 있다. 갑작스러운 변화 앞에서도 근본을 잘 지키고 있는지가 이 꿈의 핵심으로 다뤄진다.', '일상과 가정에 찾아오는 급격한 변화', array[9,26], 4)
on conflict (dream_id, keyword) do nothing;

-- B-17. 이사하는 꿈 (신규 Parent, category: 상황)
with new_dream_17 as (
  insert into public.dreams (keyword, category, interpretation)
  select '이사하는 꿈', '상황', '## 이사하는 꿈은 보통 어떻게 해석할까?
이사하는 꿈은 살던 곳을 떠나 새로운 공간으로 옮겨간다는 상징성 때문에 예로부터 변화와 전환의 의미로 풀이되어 왔다. 단순히 주거지가 바뀌는 것을 넘어, 생활 방식이나 인간관계, 마음가짐 등 삶의 여러 국면이 새로운 흐름을 맞이한다는 뜻으로 해석되곤 한다. 다만 어떤 집으로, 어떤 상황에서 이사하느냐에 따라 그 변화가 반가운 것인지 부담스러운 것인지가 크게 갈린다고 보는 시각이 많다.

## 어떤 집으로 이사하느냐가 중요하다
새 집이나 큰 집으로 이사하는 꿈은 흔히 긍정적인 변화나 넓어지는 가능성을 상징하는 것으로 여겨지는 반면, 낡은 집으로 이사하는 꿈은 아직 해소되지 않은 불안이나 부담을 반영한다고 보는 해석이 많다. 집의 상태와 분위기를 꿈에서 어떻게 느꼈는지가 해몽의 결을 가르는 중요한 단서가 된다.

## 짐을 챙기고 옮기는 과정도 함께 본다
짐을 싸거나 옮기는 과정에서 물건을 잃어버리거나 정리가 순조롭지 않았다면, 이는 지금 마음속에서 정리되지 않은 고민이나 놓치고 싶지 않은 것에 대한 불안으로 풀이되기도 한다. 반대로 이사할 집을 구하러 다니는 꿈처럼 아직 방향을 정하지 못한 채 여러 선택지를 살피는 전개라면, 중요한 결정을 앞두고 신중하게 고민하는 심리가 반영된 것으로 보는 경우가 많다.'
  where not exists (select 1 from public.dreams where keyword = '이사하는 꿈')
  returning id
)
