insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '이사하는 꿈'), '새-집으로-이사하는-꿈', '새 집으로 이사하는 꿈', '낯선 새 집의 문을 열고 들어서며 넓고 환한 공간을 둘러보는 꿈이다. 짐을 다 풀기도 전에 방 구조나 채광부터 살피게 되는 것이 특징인데, 이는 새로운 환경이나 국면에 대한 기대감을 반영한다고 해석되곤 한다. 특히 집이 이전보다 밝고 정돈된 느낌으로 그려질수록 지금의 변화가 긍정적인 방향으로 흘러갈 조짐으로 여겨지기도 한다. 다만 낯선 집이 편안하게 느껴지는지 아니면 어색하고 서먹하게 느껴지는지에 따라 해몽의 결이 달라진다고 보는 시각도 있다. 새로운 시작을 상징하는 꿈으로 보기도 하는 만큼, 최근 준비해온 일이나 관계에 변화가 찾아올 수 있다는 신호로 받아들이는 사람도 많다. 꿈에서 느낀 설렘의 정도를 떠올려보면 지금 마음이 새로운 국면을 얼마나 반기고 있는지 가늠해볼 수 있다.', '새로운 국면에 대한 기대와 설렘을 상징', array[3,14,22,29,35,41], 1),
  ((select id from public.dreams where keyword = '이사하는 꿈'), '이삿짐을-싸는-꿈', '이삿짐을 싸는 꿈', '상자에 물건을 하나씩 담으며 무엇을 챙기고 무엇을 버릴지 고민하는 꿈이다. 정리가 끝나지 않아 손이 바쁘게 움직이는 장면이 이어지는 것이 특징으로, 마음속에서 지금 정리해야 할 일이나 관계를 추리고 있다는 뜻으로 풀이되기도 한다. 짐이 쉽게 정리되고 상자가 착착 쌓이는 꿈이라면 현재 진행 중인 일이 순조롭게 마무리될 조짐으로 보는 해석도 있다. 반대로 아무리 싸도 짐이 줄지 않고 어수선하게 남아 있다면 아직 정리되지 못한 고민이 남아 있다는 암시로 여겨지기도 한다. 버리려던 물건에 유독 눈이 가는 꿈이었다면 미련이 남은 무언가를 상징한다고 보기도 한다. 짐을 싸는 손길이 가벼웠는지 무거웠는지 되짚어보면 지금 마음의 정리 상태를 짐작하는 데 도움이 될 수 있다.', '마음속 정리와 준비 과정을 상징', array[7,18,26,33], 2),
  ((select id from public.dreams where keyword = '이사하는 꿈'), '낡은-집으로-이사하는-꿈', '낡은 집으로 이사하는 꿈', '벽지가 벗겨지고 곳곳이 삐걱거리는 오래된 집으로 이사를 가게 되는 꿈이다. 새 보금자리에 대한 기대보다 낡고 허름한 상태에 먼저 눈길이 가는 것이 특징으로, 예로부터 마음 한구석에 자리한 불안이나 부담감을 반영한다고 해석되곤 한다. 집 상태가 안 좋을수록, 혹은 손볼 곳이 많이 보일수록 지금 처한 상황을 개선하고 싶은 마음이 크다는 뜻으로 풀이되는 경우도 있다. 다만 낡은 집이라도 구조가 튼튼하거나 넓게 느껴졌다면 겉모습과 달리 기반은 단단하다는 위안으로 해석하는 시선도 있다. 옛 기억이 담긴 물건이 낡은 집 안에서 발견되는 꿈이라면 지나간 인연이나 시절에 대한 미련을 상징한다고 보기도 한다. 이런 꿈을 꾼 뒤라면 오래 미뤄둔 정리나 보수가 필요한 일이 없는지 한 번쯤 돌아볼 만하다.', '해소되지 않은 불안과 부담감을 반영', array[11,39], 3),
  ((select id from public.dreams where keyword = '이사하는 꿈'), '큰-집으로-이사하는-꿈', '큰 집으로 이사하는 꿈', '지금 살던 곳보다 훨씬 넓고 방이 여러 개인 큰 집으로 이사하는 꿈이다. 걸어도 걸어도 방이 계속 나오거나 천장이 유난히 높게 느껴지는 장면이 등장하는 것이 특징으로, 마음의 여유나 커지는 포부를 상징하는 꿈으로 보기도 한다. 집의 규모가 클수록, 그리고 그 공간이 채워지지 않고 넉넉하게 비어 있을수록 앞으로의 가능성이 넓어진다는 뜻으로 해석되곤 한다. 가족이나 지인들과 함께 그 큰 집을 둘러보는 꿈이었다면 주변과의 관계나 협업에서 좋은 흐름이 열릴 조짐으로 여겨지기도 한다. 반면 넓은 집이 오히려 낯설고 텅 빈 느낌으로 다가왔다면 아직 그 여유를 온전히 누릴 준비가 안 됐다는 암시로 보는 시각도 있다. 꿈속 큰 집의 분위기가 따뜻했는지 서늘했는지에 따라 이 기대감의 성격도 달라진다고 볼 수 있다.', '커지는 포부와 여유로운 가능성을 상징', array[5,16,24,31,40,45], 4),
  ((select id from public.dreams where keyword = '이사하는 꿈'), '이사하다-짐을-잃어버리는-꿈', '이사하다 짐을 잃어버리는 꿈', '이사 도중 챙겨야 할 짐 일부가 사라지거나 어디에 뒀는지 기억나지 않아 당황하는 꿈이다. 새집에 도착해서야 상자 하나가 비었거나 아예 없어진 걸 알아차리는 전개가 특징으로, 무언가를 놓치거나 잃을지 모른다는 불안감이 반영된 것으로 해석되곤 한다. 잃어버린 짐이 평소 아끼던 물건일수록 놓치고 싶지 않은 대상이나 기회에 대한 걱정으로 풀이되는 경우도 있다. 짐을 찾아 헤매다 결국 찾아내는 꿈이었다면 걱정하던 일이 우려와 달리 무사히 해결될 조짐으로 보는 시선도 있다. 반대로 끝내 찾지 못한 채 꿈이 끝났다면 당분간은 마음의 정리가 더 필요하다는 뜻으로 여겨지기도 한다. 이런 꿈을 꾼 날은 중요한 물건이나 일정을 한 번 더 점검해보는 것도 나쁘지 않다.', '놓칠지 모른다는 불안한 마음을 반영', null, 5),
  ((select id from public.dreams where keyword = '이사하는 꿈'), '이사할-집을-구하러-다니는-꿈', '이사할 집을 구하러 다니는 꿈', '여러 부동산을 돌아다니며 마음에 드는 집을 찾으려 애쓰는 꿈이다. 마음에 드는 곳을 발견해도 조건이 안 맞거나 이미 나갔다는 말을 듣는 등 쉽게 결정을 내리지 못하는 전개가 이어지는 것이 특징으로, 현재 진로나 방향을 두고 고민하는 마음이 투영된 것으로 해석되곤 한다. 발품을 많이 팔수록, 그리고 다양한 집을 비교해볼수록 여러 선택지를 신중하게 저울질하고 있다는 뜻으로 풀이되기도 한다. 마침내 마음에 쏙 드는 집을 계약하는 데까지 이어지는 꿈이라면 고민하던 일이 원하는 방향으로 결론 날 조짐으로 여겨지는 경우도 있다. 반대로 끝내 마땅한 집을 찾지 못한 채 헤매다 끝나는 꿈이었다면 아직 결정을 내리기엔 이르다는 신호로 보는 시각도 있다. 이런 꿈을 꾼 뒤라면 지금 고려 중인 선택지들을 다시 한번 차분히 정리해보는 것도 도움이 될 수 있다.', '방향을 정하지 못한 고민과 신중함을 상징', array[8,21,27,36], 6)
on conflict (dream_id, keyword) do nothing;

-- B-18. 화장실꿈 (신규 Parent, category: 상황)
with new_dream_18 as (
  insert into public.dreams (keyword, category, interpretation)
  select '화장실꿈', '상황', '## 화장실꿈은 보통 어떻게 해석할까?
화장실은 몸속에 쌓인 것을 비워내는 공간이라는 점에서, 화장실이 등장하는 꿈은 흔히 마음속 스트레스나 묵은 감정을 해소하려는 심리와 연결지어 해석되곤 한다. 화장실을 찾고, 사용하고, 그 상태를 마주하는 일련의 과정이 곧 현재 내가 문제를 어떻게 대하고 있는지를 보여주는 상징으로 여겨지는 경우가 많다.

## 화장실의 상태가 해몽을 가른다
깨끗한 화장실을 보는 꿈은 대체로 마음이 정돈되고 걱정이 해소되는 흐름으로 풀이되는 반면, 더러운 화장실을 마주하는 꿈은 아직 해소하지 못한 스트레스나 찜찜함을 반영한다고 보는 해석이 많다. 화장실이 얼마나 깔끔했는지, 얼마나 편안하게 느껴졌는지가 꿈의 결을 가르는 핵심 단서가 된다.

## 찾거나 갇히는 상황도 눈여겨볼 만하다
화장실을 못 찾아 헤매거나 갇혀서 나오지 못하는 꿈은 현재 상황에서 느끼는 답답함이나 막막함을 상징하는 것으로 여겨지곤 한다. 반면 공중화장실처럼 여러 사람과 공간을 나눠 쓰는 상황이라면 사회적 관계 속에서 느끼는 부담이나 적응의 과정으로 해석되는 경우가 많다.'
  where not exists (select 1 from public.dreams where keyword = '화장실꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[1,10,16,23,30,37] from new_dream_18;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '화장실꿈'), '화장실을-못-찾는-꿈', '화장실을 못 찾는 꿈', '급한 마음으로 화장실을 찾아 이곳저곳 뛰어다니지만 좀처럼 발견하지 못하는 꿈이다. 문을 열어도 화장실이 아니거나, 있어야 할 자리에 화장실이 사라진 듯한 상황이 반복되는 것이 특징으로, 해결하고 싶은 문제를 두고 마땅한 방법을 찾지 못해 답답해하는 심리가 반영된 것으로 해석되곤 한다. 애가 타는 그 감정이 클수록 현실에서도 어딘가 막혀 있다고 느끼는 일이 있다는 신호로 보는 시각도 있다. 헤매다 결국 화장실을 찾아내는 꿈이었다면 막막하던 문제에도 곧 실마리가 보일 조짐으로 여겨지는 경우가 있다. 끝내 찾지 못한 채 잠에서 깼다면 아직은 답을 서두르기보다 조금 더 기다려야 한다는 뜻으로 풀이되기도 한다. 이런 꿈을 꾼 뒤에는 지금 마음을 조급하게 만드는 일이 무엇인지 짚어보는 것도 좋다.', '막막한 문제 앞에서 느끼는 답답함을 반영', array[17], 1),
  ((select id from public.dreams where keyword = '화장실꿈'), '화장실이-더러운-꿈', '화장실이 더러운 꿈', '들어간 화장실이 온통 지저분하고 냄새가 심해 눈살을 찌푸리게 되는 꿈이다. 발 디딜 곳조차 마땅치 않을 만큼 더러운 상태가 강조되는 것이 특징으로, 전통적으로 마음속에 쌓인 스트레스나 해소하지 못한 찜찜함을 반영한다고 해석되곤 한다. 더러운 정도가 심할수록 최근 쌓인 불편한 감정이나 미뤄둔 문제가 그만큼 크다는 뜻으로 풀이되는 경우도 있다. 다만 더러운 화장실을 애써 청소하거나 정리하는 꿈으로 이어졌다면 그 문제를 스스로 해결해나가려는 의지로 보는 시선도 있다. 도저히 사용할 수 없어 다른 곳을 찾아 나서는 전개였다면 지금의 방식이 아닌 다른 해결책이 필요하다는 암시로 여겨지기도 한다. 꿈에서 느낀 불쾌감을 떠올려보면 요즘 마음에 쌓인 것이 무엇인지 짐작해볼 수 있다.', '해소되지 못한 스트레스와 찜찜함을 상징', null, 2),
  ((select id from public.dreams where keyword = '화장실꿈'), '화장실에-갇히는-꿈', '화장실에 갇히는 꿈', '볼일을 보다가 문이 열리지 않거나 잠겨서 화장실 안에 갇히는 꿈이다. 아무리 문을 밀고 두드려도 밖으로 나가지 못하는 상황이 이어지는 것이 특징으로, 현재 처한 상황이나 관계에서 답답함을 느끼고 있다는 마음이 투영된 것으로 해석되곤 한다. 갇힌 시간이 길게 느껴질수록 스스로 벗어나기 어렵다고 여기는 부담이 크다는 뜻으로 풀이되기도 한다. 누군가 밖에서 문을 열어주거나 스스로 힘으로 문을 열고 나오는 꿈이었다면 막혔던 상황이 곧 풀릴 조짐으로 보는 시각도 있다. 반대로 끝내 갇힌 채로 꿈이 끝났다면 아직은 답답함이 좀 더 이어질 수 있다는 암시로 여겨지는 경우도 있다. 이런 꿈을 꾼 뒤라면 지금 나를 옥죄고 있는 것이 무엇인지 차분히 짚어보는 시간을 가져볼 만하다.', '벗어나기 힘든 답답한 상황을 반영', array[9,38], 3),
  ((select id from public.dreams where keyword = '화장실꿈'), '깨끗한-화장실을-보는-꿈', '깨끗한 화장실을 보는 꿈', '반짝일 만큼 깨끗하게 정돈된 화장실을 마주하는 꿈이다. 타일이며 세면대까지 티 하나 없이 깔끔한 모습이 인상 깊게 남는 것이 특징으로, 마음이 정돈되고 홀가분해지는 기운을 상징하는 꿈으로 보기도 한다. 화장실이 깨끗할수록, 그리고 그 안에서 편안함을 느낄수록 그동안 쌓였던 근심이 해소되는 흐름으로 해석되는 경우가 많다. 특히 낯선 곳인데도 화장실이 유난히 깨끗하게 느껴졌다면 새로운 환경에서도 마음이 편안해질 조짐으로 여겨지기도 한다. 볼일을 시원하게 보고 나오는 꿈으로 이어졌다면 묵혀둔 걱정거리가 말끔히 정리된다는 뜻으로 풀이되기도 한다. 이런 꿈을 꾼 뒤에는 그동안 애써온 일이 좋은 결실로 이어질 수 있다는 기대를 가져봐도 좋다.', '근심이 해소되는 홀가분한 기운을 상징', array[2,15,28,34,42], 4),
  ((select id from public.dreams where keyword = '화장실꿈'), '공중화장실을-쓰는-꿈', '공중화장실을 쓰는 꿈', '모르는 사람들과 함께 쓰는 공중화장실에 들어가 볼일을 보는 꿈이다. 칸마다 사람이 있거나 순서를 기다려야 하는 등 혼자만의 공간이 아니라는 점이 부각되는 것이 특징으로, 사회적인 관계나 여러 사람과 얽힌 상황 속 자신의 위치를 돌아보게 하는 꿈으로 여겨지기도 한다. 원하는 칸을 무리 없이 찾아 편하게 볼일을 보는 꿈이었다면 주변 사람들과의 관계가 무난하게 흘러가고 있다는 뜻으로 해석되는 경우가 있다. 반대로 마땅한 칸을 찾지 못하거나 눈치가 보이는 상황이었다면 공적인 자리에서 느끼는 부담감이 반영된 것으로 보는 시선도 있다. 낯선 사람과 어색하게 마주치는 장면이 있었다면 새로운 관계나 환경에 적응하는 과정에 있다는 암시로 풀이되기도 한다. 이런 꿈을 꾼 뒤에는 요즘 사람들과의 관계에서 느끼는 부담이 없는지 돌아봐도 좋다.', '사회적 관계 속 부담과 적응을 상징', array[6,20,25], 5)
on conflict (dream_id, keyword) do nothing;

-- B-19. 학교에 가는 꿈 (신규 Parent, category: 상황)
with new_dream_19 as (
  insert into public.dreams (keyword, category, interpretation)
  select '학교에 가는 꿈', '상황', '## 학교에 가는 꿈은 보통 어떻게 해석할까?
학교는 배움과 평가, 그리고 정해진 규칙 속에서 하루하루를 보내던 공간이라는 점에서, 학교에 가는 꿈은 흔히 현재 마주한 과제나 스스로에 대한 평가와 관련된 심리를 반영한다고 해석되곤 한다. 지각하거나 준비가 부족한 채로 학교에 가는 전개는 불안감을, 옛 학교나 졸업처럼 지나온 시간을 돌아보는 전개는 그리움이나 성취감을 상징하는 경우가 많다.

## 늦거나 준비되지 않은 상황이 주는 의미
지각해서 학교에 가거나 시험공부를 하지 못한 채 등교하는 꿈은 무언가를 앞두고 준비가 충분하지 않다고 느끼는 불안감을 반영한다고 보는 시선이 많다. 학교 안에서 길을 잃는 꿈 역시 익숙한 상황에서 뜻밖에 방향을 잃은 듯한 심리와 연결지어 해석되곤 한다.

## 지나온 시간을 돌아보는 꿈들
옛 학교로 돌아가는 꿈은 그 시절에 대한 그리움이나 초심을 되새기는 계기로, 졸업하는 꿈은 하나의 과정을 잘 마무리하고 다음 단계로 나아가는 흐름으로 풀이되는 경우가 많다. 두 꿈 모두 지금까지 걸어온 길을 돌아보게 한다는 공통점이 있다.'
  where not exists (select 1 from public.dreams where keyword = '학교에 가는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[5,12,21,28,36,44] from new_dream_19;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '학교에 가는 꿈'), '지각해서-학교에-가는-꿈', '지각해서 학교에 가는 꿈', '늦잠을 자거나 준비가 늦어져 서둘러 학교로 뛰어가는 꿈이다. 교문이 눈앞에서 닫히거나 이미 수업이 시작된 것 같아 마음이 조급해지는 전개가 특징으로, 무언가를 놓칠지 모른다는 불안이 반영된 것으로 해석되곤 한다. 아슬아슬하게라도 제시간에 도착하는 꿈이었다면 걱정했던 일이 결국 무리 없이 지나갈 조짐으로 여겨지는 경우가 있다. 반대로 끝내 늦고 마는 꿈이었다면 준비가 부족하다고 느끼는 마음이 좀 더 크게 자리하고 있다는 뜻으로 풀이되기도 한다. 지각하는 이유가 반복해서 발목을 잡는 것이었다면 스스로 통제하기 어려운 상황에 대한 답답함을 상징한다고 보는 시선도 있다. 이런 꿈을 꾼 뒤에는 요즘 시간에 쫓기며 미뤄둔 일이 없는지 점검해보는 계기로 삼아도 좋다.', '준비 부족에서 오는 불안감을 반영', array[12], 1),
  ((select id from public.dreams where keyword = '학교에 가는 꿈'), '옛-학교로-돌아가는-꿈', '옛 학교로 돌아가는 꿈', '이미 졸업한 지 오래된 옛 학교 교실이나 운동장을 다시 걷고 있는 꿈이다. 그 시절 친구나 선생님이 함께 등장하기도 하는 것이 특징으로, 지나간 시절에 대한 그리움이나 그때의 마음가짐을 돌아보고 싶은 심리가 반영된 것으로 해석되곤 한다. 학교의 풍경이 익숙하고 편안하게 느껴졌다면 그 시절의 좋은 기운이나 초심을 다시 떠올리게 되는 조짐으로 여겨지기도 한다. 반대로 낯설고 어색하게 변해버린 학교였다면 지금과 그때 사이의 거리감을 실감하고 있다는 뜻으로 풀이되는 경우도 있다. 옛 친구를 만나 반가워하는 장면으로 이어졌다면 소원해졌던 인연이 다시 이어질 수 있다는 암시로 보는 시각도 있다. 이런 꿈을 꾼 뒤에는 오랫동안 연락이 뜸했던 사람을 떠올려보는 것도 좋은 계기가 될 수 있다.', '지나간 시절에 대한 그리움과 초심을 상징', array[4,18,26,33], 2),
  ((select id from public.dreams where keyword = '학교에 가는 꿈'), '시험공부를-안-하고-학교에-간-꿈', '시험공부를 안 하고 학교에 간 꿈', '시험이 코앞인데 하나도 준비하지 못한 채 학교에 도착해 당황하는 꿈이다. 책을 펼쳐도 눈에 들어오지 않고 시험 범위조차 기억나지 않는 상황이 이어지는 것이 특징으로, 어떤 일을 앞두고 준비가 부족하다고 느끼는 불안감을 반영한다고 해석되곤 한다. 시험 시간이 다가올수록 초조함이 커지는 꿈이었다면 현실에서도 마감이나 평가를 앞두고 부담을 느끼고 있다는 뜻으로 풀이되는 경우가 있다. 그럼에도 문제를 하나씩 풀어나가거나 예상 밖으로 잘 넘기는 꿈으로 이어졌다면 걱정과 달리 결과는 나쁘지 않을 조짐으로 보는 시선도 있다. 결국 시험을 망치는 꿈으로 끝났다면 지금부터라도 준비를 서둘러야 한다는 신호로 여겨지기도 한다. 이런 꿈을 꾼 뒤에는 앞두고 있는 일 중 미뤄둔 준비가 없는지 돌아보는 것도 도움이 된다.', '부족한 준비에 대한 초조함을 반영', null, 3),
  ((select id from public.dreams where keyword = '학교에 가는 꿈'), '학교에서-길을-잃는-꿈', '학교에서 길을 잃는 꿈', '분명 다니던 학교인데도 복도와 계단이 낯설게 얽혀 있어 교실을 찾지 못하고 헤매는 꿈이다. 같은 곳을 몇 번이고 지나치는 듯한 느낌이 드는 것이 특징으로, 익숙하다고 여겼던 상황에서 뜻밖에 방향을 잃은 듯한 심리를 반영한다고 해석되곤 한다. 헤매는 시간이 길어질수록 지금 처한 상황을 어떻게 풀어가야 할지 확신이 서지 않는 마음이 크다는 뜻으로 풀이되는 경우도 있다. 지나가던 누군가의 도움으로 길을 찾는 꿈이었다면 막막하던 문제에 뜻밖의 조언이나 도움이 찾아올 조짐으로 여겨지기도 한다. 끝내 교실을 찾지 못한 채 꿈이 끝났다면 조급해하지 말고 천천히 방향을 다시 잡아볼 필요가 있다는 암시로 보는 시선도 있다. 이런 꿈을 꾼 뒤라면 지금 익숙하다고만 여겼던 일들을 새로운 시선으로 점검해보는 것도 좋다.', '익숙한 상황에서 방향을 잃은 심리를 반영', array[31], 4),
  ((select id from public.dreams where keyword = '학교에 가는 꿈'), '졸업하는-꿈', '졸업하는 꿈', '졸업식장에 서서 졸업장을 받거나 학사모를 던지며 학교를 떠나는 꿈이다. 지나온 시간을 뒤로하고 새로운 문을 향해 나아가는 장면이 강조되는 것이 특징으로, 하나의 과정을 잘 마무리하고 다음 단계로 넘어가는 흐름을 상징하는 꿈으로 보기도 한다. 졸업식 분위기가 밝고 홀가분했다면 지금 마무리 짓고 있는 일이 좋은 결실로 이어질 조짐으로 여겨지는 경우가 많다. 함께한 사람들과 웃으며 인사를 나누는 꿈이었다면 그동안의 노력을 주변에서도 인정받는다는 뜻으로 풀이되기도 한다. 반대로 졸업식이 어수선하거나 아쉬움이 남는 분위기였다면 마무리에 좀 더 신경 쓸 부분이 남아 있다는 신호로 보는 시각도 있다. 이런 꿈을 꾼 뒤에는 지금까지 이어온 노력을 스스로 다독여봐도 좋을 시점이다.', '과정을 잘 마무리한 성취감을 상징', array[3,17,24,29,38,43], 5)
on conflict (dream_id, keyword) do nothing;

-- B-20. 비행기꿈 (신규 Parent, category: 교통)
with new_dream_20 as (
  insert into public.dreams (keyword, category, interpretation)
  select '비행기꿈', '교통', '## 비행기꿈은 보통 어떻게 해석할까?
비행기는 먼 거리를 빠르게 이동하며 새로운 곳으로 데려다주는 교통수단이라는 점에서, 비행기가 등장하는 꿈은 흔히 목표를 향한 도약이나 큰 변화의 흐름을 상징한다고 해석되곤 한다. 탑승부터 이륙, 비행, 그리고 도착에 이르는 과정 하나하나가 지금 진행 중인 일의 흐름과 맞닿아 있다고 보는 시각이 많다.

## 순조로운 비행이 주는 의미
비행기를 타고 무사히 이륙하는 꿈은 계획한 일이 본격적으로 궤도에 오르는 조짐으로, 하늘에서 풍경을 내려다보는 꿈은 상황을 한 걸음 물러나 넓은 시야로 바라보게 된다는 뜻으로 풀이되는 경우가 많다.

## 흔들리거나 놓치는 상황은 변수를 뜻한다
비행 중 기체가 흔들리거나 비행기를 놓치는 꿈은 계획에 예상치 못한 변수가 생기거나 눈앞의 기회를 아쉽게 놓칠지 모른다는 불안감을 반영한다고 보는 해석이 많다. 다만 흔들림이 다시 가라앉거나 대체편을 찾아내는 전개라면 어려움을 무사히 넘길 조짐으로 여겨지기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '비행기꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[2,9,18,26,34,42] from new_dream_20;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '비행기꿈'), '비행기를-타는-꿈', '비행기를 타는 꿈', '공항에서 탑승 수속을 마치고 비행기 좌석에 자리를 잡는 꿈이다. 창가나 통로 자리에 앉아 이륙을 기다리는 장면이 구체적으로 그려지는 것이 특징으로, 새로운 목표를 향해 나아가려는 마음가짐을 상징하는 꿈으로 보기도 한다. 좌석이 편안하고 마음이 설렜다면 앞으로의 계획이 순조롭게 진행될 조짐으로 여겨지는 경우가 많다. 반대로 자리를 찾지 못해 우왕좌왕했다면 아직 방향을 뚜렷하게 정하지 못한 채 서두르고 있다는 뜻으로 풀이되기도 한다. 옆자리에 낯선 사람과 대화를 나누는 꿈이었다면 예상 밖의 인연이나 기회가 찾아올 수 있다는 암시로 보는 시각도 있다. 이런 꿈을 꾼 뒤에는 지금 어떤 목표를 향해 나아가고 있는지 스스로 점검해봐도 좋다.', '새로운 목표를 향한 설렘과 기대를 상징', array[2,9,19,27,35,41], 1),
  ((select id from public.dreams where keyword = '비행기꿈'), '비행기가-이륙하는-꿈', '비행기가 이륙하는 꿈', '활주로를 달리던 비행기가 서서히 속도를 내며 하늘로 떠오르는 꿈이다. 땅이 점점 멀어지고 몸이 붕 뜨는 느낌이 생생하게 전해지는 것이 특징으로, 전통적으로 새로운 도약이나 본격적인 시작을 상징하는 꿈으로 해석되곤 한다. 이륙이 매끄럽고 안정적으로 느껴졌다면 준비해온 일이 큰 무리 없이 궤도에 오를 조짐으로 여겨지는 경우가 많다. 반대로 이륙 과정에서 덜컹거리거나 불안정한 느낌이 있었다면 시작 단계에서 예상치 못한 변수를 마주할 수 있다는 뜻으로 풀이되기도 한다. 창밖으로 멀어지는 풍경을 바라보는 장면이 인상 깊었다면 지금까지의 일상에서 한 걸음 벗어나려는 마음이 반영된 것으로 보는 시선도 있다. 이런 꿈을 꾼 뒤라면 새로 시작하려는 일의 첫걸음을 다시 점검해봐도 좋다.', '본격적인 도약과 시작을 상징', array[6,14,23,30,39,45], 2),
  ((select id from public.dreams where keyword = '비행기꿈'), '비행기가-흔들리는-꿈', '비행기가 흔들리는 꿈', '순항하던 비행기가 갑자기 요동치며 좌석이 흔들리고 기내가 술렁이는 꿈이다. 안전벨트를 다시 매라는 안내가 나오거나 승객들이 불안해하는 분위기가 이어지는 것이 특징으로, 계획하거나 진행 중인 일에 예상치 못한 변수가 생길지 모른다는 불안감을 반영한다고 해석되곤 한다. 흔들림이 금세 가라앉고 다시 평온해지는 꿈이었다면 일시적인 어려움을 무사히 넘길 조짐으로 여겨지는 경우가 많다. 반대로 흔들림이 심해지며 위태롭게 느껴졌다면 대비가 필요한 변수가 남아 있다는 신호로 보는 시각도 있다. 주변 승객들과 서로 의지하며 견디는 장면이 있었다면 어려운 상황일수록 주변의 도움이 힘이 된다는 뜻으로 풀이되기도 한다. 이런 꿈을 꾼 뒤에는 진행 중인 일에 변수가 없는지 한 번 더 점검해보는 것이 좋다.', '예상치 못한 변수에 대한 불안을 반영', array[16], 3),
  ((select id from public.dreams where keyword = '비행기꿈'), '비행기를-놓치는-꿈', '비행기를 놓치는 꿈', '공항에 늦게 도착하거나 게이트를 착각해 타야 할 비행기를 놓치는 꿈이다. 탑승구가 이미 닫히거나 활주로로 나가는 비행기를 발만 동동 구르며 바라보는 장면이 특징으로, 눈앞의 기회를 놓칠지 모른다는 아쉬움과 조바심이 반영된 것으로 해석되곤 한다. 다음 비행기를 다시 예약하거나 대체 항공편을 찾아내는 꿈으로 이어졌다면 놓친 기회를 대신할 방법이 곧 나타날 조짐으로 여겨지기도 한다. 반대로 끝내 다른 방법을 찾지 못한 채 공항에 남겨진 꿈이었다면 지금은 아쉬움을 인정하고 다음을 준비해야 할 때라는 뜻으로 풀이되는 경우도 있다. 짐을 챙기다 늦어진 것이었다면 준비 과정에서의 미흡함을 스스로 돌아보게 하는 신호로 보는 시선도 있다. 이런 꿈을 꾼 뒤에는 지금 놓치고 싶지 않은 일이 무엇인지 점검해보는 계기로 삼아도 좋다.', '놓친 기회에 대한 아쉬움과 조바심을 반영', null, 4),
  ((select id from public.dreams where keyword = '비행기꿈'), '비행기에서-내려다보는-꿈', '비행기에서 내려다보는 꿈', '창가 자리에 앉아 구름 위를 날며 아득히 펼쳐진 땅을 내려다보는 꿈이다. 도시와 산, 바다가 작은 모형처럼 눈 아래 펼쳐지는 풍경이 인상적으로 남는 것이 특징으로, 지금까지와는 다른 시야로 상황을 넓게 바라보게 된다는 뜻으로 해석되곤 한다. 내려다본 풍경이 맑고 탁 트여 있었다면 복잡했던 고민이 한결 정리되고 명확해지는 조짐으로 여겨지는 경우가 많다. 구름이나 안개에 가려 풍경이 잘 보이지 않았다면 아직은 상황을 온전히 파악하기 이르다는 신호로 풀이되기도 한다. 익숙한 장소를 하늘에서 알아보는 꿈이었다면 지나온 시간을 새로운 관점에서 돌아보게 된다는 암시로 보는 시각도 있다. 이런 꿈을 꾼 뒤라면 눈앞의 일에서 한 걸음 물러나 전체를 조망해보는 여유를 가져봐도 좋다.', '넓은 시야로 상황을 조망하는 여유를 상징', array[3,11,20,28,37,44], 5)
on conflict (dream_id, keyword) do nothing;

